#[cfg(unix)]
pub(crate) fn materialize_source_only_program_target(
    manifest: &DepsManifest,
    canonical: &Path,
    output_root: &Path,
    arch: TargetArch,
) -> Result<Vec<MaterializedProgramMemberV1>, String> {
    materialize_source_only_program_target_with(
        manifest,
        canonical,
        output_root,
        arch,
        &mut |_| {},
        &mut |_| Ok(()),
    )
}

#[cfg(unix)]
fn materialize_source_only_program_target_with<AfterCopy, BeforePublish>(
    manifest: &DepsManifest,
    canonical: &Path,
    output_root: &Path,
    arch: TargetArch,
    after_copy: &mut AfterCopy,
    before_publish: &mut BeforePublish,
) -> Result<Vec<MaterializedProgramMemberV1>, String>
where
    AfterCopy: FnMut(&Path),
    BeforePublish: FnMut(&Path) -> Result<(), String>,
{
    materialize_source_only_program_target_with_cache_root(
        manifest,
        canonical,
        None,
        output_root,
        arch,
        after_copy,
        before_publish,
    )
}

#[cfg(unix)]
fn materialize_source_only_program_target_with_cache_root<AfterCopy, BeforePublish>(
    manifest: &DepsManifest,
    canonical: &Path,
    canonical_root: Option<&AnchoredDirectory>,
    output_root: &Path,
    arch: TargetArch,
    after_copy: &mut AfterCopy,
    before_publish: &mut BeforePublish,
) -> Result<Vec<MaterializedProgramMemberV1>, String>
where
    AfterCopy: FnMut(&Path),
    BeforePublish: FnMut(&Path) -> Result<(), String>,
{
    if manifest.kind != ManifestKind::Program {
        return Ok(Vec::new());
    }
    let output_root = canonical_real_directory(output_root, "source-only projection output root")?;
    let canonical = canonical_real_directory(canonical, "source-only package cache entry")?;
    let mut prepared = prepare_program_projection(
        manifest,
        &canonical,
        canonical_root,
        &output_root,
        arch,
        after_copy,
    )?;
    let shared_output_root = prepared
        .transaction
        .parent_guard
        .root_anchor
        .try_clone("source-only projection output root")?;
    let subject = manifest.spec();
    let result = with_source_only_projection_lock_guard_from_root(shared_output_root, |lock| {
        publish_owned_entry_transaction(
            &subject,
            &output_root,
            &mut prepared.transaction,
            lock,
            before_publish,
        )
    });
    match result {
        Ok(()) => {
            let mut receipts = prepared
                .members
                .into_iter()
                .map(|member| member.receipt)
                .collect::<Vec<_>>();
            receipts.sort_by(|left, right| {
                (&left.mirror_path, &left.source_artifact)
                    .cmp(&(&right.mirror_path, &right.source_artifact))
            });
            Ok(receipts)
        }
        Err(error) => Err(error),
    }
}

#[cfg(not(unix))]
pub(crate) fn materialize_source_only_program_target(
    _manifest: &DepsManifest,
    _canonical: &Path,
    _output_root: &Path,
    _arch: TargetArch,
) -> Result<Vec<MaterializedProgramMemberV1>, String> {
    Err("source-only program materialization requires Unix no-follow filesystem semantics".to_string())
}

/// Materialized-member descriptors for a SourceOnlyV1 program cache entry,
/// computed purely from the canonical entry + manifest + arch -- WITHOUT the
/// staging/publish side effect `prepare_program_projection` performs.
///
/// This is the declaration/hash loop of `prepare_program_projection` with the
/// output-root mirror transaction removed: for each declared program output
/// and runtime file it opens the artifact under the canonical entry, reads its
/// mode, streams the same bytes to compute size + sha256, and records the same
/// `mirror_path` the projection would (via the pure `output_dest_rel_for` /
/// `runtime_file_dest_rel_for` + `program_projection_destination_relative` +
/// `portable_projection_path` helpers), then applies the identical
/// `(mirror_path, source_artifact)` sort. Because every field is a function of
/// the immutable content-addressed entry rather than the mirror, the members it
/// returns are byte-identical to the ones `materialize_source_only_program_target_with_cache_root`
/// records in the projection-hooks receipt for the same node. Non-`Program`
/// kinds have no program closure and return an empty `Vec`, matching
/// `materialize_source_only_program_target_with_cache_root`.
#[cfg(unix)]
fn canonical_program_members(
    manifest: &DepsManifest,
    canonical: &Path,
    arch: TargetArch,
) -> Result<Vec<MaterializedProgramMemberV1>, String> {
    if manifest.kind != ManifestKind::Program {
        return Ok(Vec::new());
    }
    let mut declarations = Vec::<(String, PathBuf, Option<u32>)>::new();
    for output in &manifest.program_outputs {
        declarations.push((
            output.wasm.clone(),
            manifest.output_dest_rel_for(output),
            None,
        ));
    }
    declarations.extend(manifest.runtime_files.iter().map(|runtime_file| {
        (
            runtime_file.artifact.clone(),
            manifest.runtime_file_dest_rel_for(runtime_file),
            Some(runtime_file.mode),
        )
    }));
    if declarations.is_empty() {
        return Err(format!(
            "{}: program has no declared output/runtime closure to materialize",
            manifest.spec()
        ));
    }

    let mut members = Vec::new();
    for (source_artifact, mirror_relative, declared_mode) in declarations {
        let mut source = StableProjectionSource::open(canonical, &source_artifact)
            .map_err(|error| format!("{}: {error}", manifest.spec()))?;
        let mode = declared_mode.unwrap_or(source.file_snapshot.mode);
        let destination_relative =
            program_projection_destination_relative(manifest, arch, &mirror_relative);
        let mut hash = Sha256::new();
        let mut size = 0u64;
        let mut buffer = [0u8; 64 * 1024];
        loop {
            let count = std::io::Read::read(&mut source.file, &mut buffer).map_err(|error| {
                format!("read program member {}: {error}", source.path.display())
            })?;
            if count == 0 {
                break;
            }
            hash.update(&buffer[..count]);
            size += count as u64;
        }
        source.validate()?;
        let digest: [u8; 32] = hash.finalize().into();
        members.push(MaterializedProgramMemberV1 {
            source_artifact,
            mirror_path: portable_projection_path(
                manifest,
                &destination_relative,
                "source-only output-root mirror path",
            )?,
            mode,
            size,
            sha256: hex(&digest),
        });
    }
    members.sort_by(|left, right| {
        (&left.mirror_path, &left.source_artifact)
            .cmp(&(&right.mirror_path, &right.source_artifact))
    });
    Ok(members)
}

/// Persist the SourceOnlyV1 package receipt sidecar for a freshly built
/// canonical cache entry from `ensure_built_inner`'s own store path -- the
/// path `xtask build-deps resolve` uses (run.sh's node.wasm bootstrap, package
/// build-script dependency resolution), which stamps the wasm but historically
/// wrote no receipt, leaving the Task-7 build-key belt check a permanent no-op
/// for those entries.
///
/// The receipt is assembled from the same primitives the projection-hooks path
/// (`resolve_local_build_package_node_with_projection_hooks` via
/// `capture_source_only_package_authority`) uses, so it is byte-identical to
/// the sidecar that path writes for the same `(canonical, cache_key)`. That
/// identity is required, not merely nice: the trusted fast path reads this
/// sidecar's `cache_receipt_sha256` and finalization compares against it, so a
/// diverging value would spuriously fail the graph path. Every field is
/// derivable from the canonical dir + manifest + arch, with no `output_root`:
/// `manifest_sha256` from the manifest file, `cache_key_sha256` from the
/// in-scope key, `cache_receipt_sha256` from the same cache-entry snapshot, and
/// the members from `canonical_program_members`.
#[cfg(unix)]
fn write_canonical_receipt(
    manifest: &DepsManifest,
    cache_root: &Path,
    canonical: &Path,
    cache_key_sha: &str,
    arch: TargetArch,
    abi_version: u32,
) -> Result<(), String> {
    let manifest_sha256 = stable_package_manifest_sha256(&manifest.dir.join("package.toml"))?;
    let guard = SourceOnlyCacheParentGuard::prepare(cache_root, canonical)?;
    let snapshot = capture_source_only_cache_entry_snapshot(
        manifest,
        &guard,
        canonical,
        arch,
        abi_version,
        cache_key_sha,
    )?;
    let cache_receipt_sha256 = cache_receipt_sha256(&snapshot.receipt)?;
    let materialized_members = canonical_program_members(manifest, canonical, arch)?;
    let receipt = PackageNodeReceiptV1 {
        manifest_sha256,
        cache_key_sha256: cache_key_sha.to_string(),
        cache_receipt_sha256,
        materialized_members,
    };
    write_source_only_cache_receipt(canonical, &receipt)
}

/// Non-Unix stub: source-only receipts require Unix no-follow filesystem
/// semantics (the snapshot/receipt primitives are `#[cfg(unix)]`), and
/// `ensure_built_uncached` is not itself cfg-gated, so it needs a no-op here.
#[cfg(not(unix))]
fn write_canonical_receipt(
    _manifest: &DepsManifest,
    _cache_root: &Path,
    _canonical: &Path,
    _cache_key_sha: &str,
    _arch: TargetArch,
    _abi_version: u32,
) -> Result<(), String> {
    Ok(())
}

fn program_projection_destination_relative(
    manifest: &DepsManifest,
    arch: TargetArch,
    mirror_relative: &Path,
) -> PathBuf {
    if manifest.uses_root_binary_mirror() {
        mirror_relative.to_path_buf()
    } else {
        PathBuf::from("programs")
            .join(arch.as_str())
            .join(mirror_relative)
    }
}

#[cfg(unix)]
struct StableProjectionSource {
    root_path: PathBuf,
    path: PathBuf,
    component_names: Vec<OsString>,
    directories: Vec<std::fs::File>,
    directory_snapshots: Vec<ReceiptMetadataSnapshot>,
    file: std::fs::File,
    file_snapshot: ReceiptMetadataSnapshot,
}

#[cfg(unix)]
impl StableProjectionSource {
    #[cfg(unix)]
    fn open(root: &Path, artifact: &str) -> Result<Self, String> {
        let root = AnchoredDirectory::open_existing(root, "projection source root")?;
        Self::open_from_anchored_root(&root, artifact)
    }

    #[cfg(unix)]
    fn open_from_anchored_root(
        root: &AnchoredDirectory,
        artifact: &str,
    ) -> Result<Self, String> {
        let relative = Path::new(artifact);
        let component_names = relative
            .components()
            .map(|component| match component {
                Component::Normal(name) => Ok(name.to_os_string()),
                _ => Err(format!(
                    "projected source artifact must be a portable relative path: {artifact:?}"
                )),
            })
            .collect::<Result<Vec<_>, _>>()?;
        if component_names.is_empty() {
            return Err("projected source artifact must not be empty".to_string());
        }

        let root_file = root.file.try_clone().map_err(|error| {
            format!(
                "duplicate opened projection source root {}: {error}",
                root.path.display()
            )
        })?;
        let root_snapshot = receipt_metadata_snapshot(&root_file.metadata().map_err(|error| {
            format!("inspect opened projection source root {}: {error}", root.path.display())
        })?)?;
        if root_snapshot.kind != 2 {
            return Err(format!(
                "projection source root must be a real directory: {}",
                root.path.display()
            ));
        }
        let mut directories = vec![root_file];
        let mut directory_snapshots = vec![root_snapshot];
        let mut path = root.path.clone();
        for name in &component_names[..component_names.len() - 1] {
            path.push(name);
            let opened = open_receipt_entry_at(
                directories.last().expect("projection source root descriptor"),
                name,
                &path,
                false,
            )?;
            let snapshot = receipt_metadata_snapshot(&opened.metadata().map_err(|error| {
                format!("inspect opened projection source ancestor {}: {error}", path.display())
            })?)?;
            if snapshot.kind != 2 {
                return Err(format!(
                    "projected source ancestor must be a real nonsymlink directory: {}",
                    path.display()
                ));
            }
            directories.push(opened);
            directory_snapshots.push(snapshot);
        }
        let leaf_name = component_names.last().expect("nonempty component list");
        let leaf_path = root.path.join(relative);
        let file = open_receipt_entry_at(
            directories.last().expect("projection source parent descriptor"),
            leaf_name,
            &leaf_path,
            false,
        )?;
        let file_snapshot = receipt_metadata_snapshot(&file.metadata().map_err(|error| {
            format!("inspect opened projected source {}: {error}", leaf_path.display())
        })?)?;
        if file_snapshot.kind != 1 {
            return Err(format!(
                "projected source must be a regular nonsymlink file: {}",
                leaf_path.display()
            ));
        }
        Ok(Self {
            root_path: root.path.clone(),
            path: leaf_path,
            component_names,
            directories,
            directory_snapshots,
            file,
            file_snapshot,
        })
    }

    #[cfg(not(unix))]
    fn open(_root: &Path, _artifact: &str) -> Result<Self, String> {
        Err("source-only regular projection requires Unix no-follow filesystem semantics".to_string())
    }

    #[cfg(unix)]
    fn validate(&self) -> Result<(), String> {
        if receipt_metadata_snapshot(&self.file.metadata().map_err(|error| {
            format!("reinspect opened projected source {}: {error}", self.path.display())
        })?)? != self.file_snapshot
        {
            return Err(format!(
                "projected source changed while copied: {}",
                self.path.display()
            ));
        }
        let leaf_name = self.component_names.last().expect("nonempty component list");
        let reopened = open_receipt_entry_at(
            self.directories.last().expect("projection source parent descriptor"),
            leaf_name,
            &self.path,
            false,
        )?;
        if receipt_metadata_snapshot(&reopened.metadata().map_err(|error| {
            format!("inspect reopened projected source {}: {error}", self.path.display())
        })?)? != self.file_snapshot
        {
            return Err(format!(
                "projected source pathname changed while copied: {}",
                self.path.display()
            ));
        }
        for index in (1..self.directories.len()).rev() {
            let held = receipt_metadata_snapshot(&self.directories[index].metadata().map_err(|error| {
                format!("reinspect held projection source ancestor {}: {error}", self.path.display())
            })?)?;
            if held != self.directory_snapshots[index] {
                return Err(format!(
                    "projected source ancestor changed while copied: {}",
                    self.path.display()
                ));
            }
            let ancestor_path = self
                .root_path
                .join(self.component_names[..index].iter().collect::<PathBuf>());
            let reopened = open_receipt_entry_at(
                &self.directories[index - 1],
                &self.component_names[index - 1],
                &ancestor_path,
                false,
            )?;
            if receipt_metadata_snapshot(&reopened.metadata().map_err(|error| {
                format!("reinspect projection source ancestor {}: {error}", ancestor_path.display())
            })?)? != self.directory_snapshots[index]
            {
                return Err(format!(
                    "projected source ancestor pathname changed while copied: {}",
                    ancestor_path.display()
                ));
            }
        }
        let reopened_root = open_receipt_root(&self.root_path)?;
        if receipt_metadata_snapshot(&reopened_root.metadata().map_err(|error| {
            format!("reinspect projection source root {}: {error}", self.root_path.display())
        })?)? != self.directory_snapshots[0]
        {
            return Err(format!(
                "projected source root changed while copied: {}",
                self.root_path.display()
            ));
        }
        Ok(())
    }

    #[cfg(not(unix))]
    fn validate(&self) -> Result<(), String> {
        Err("source-only regular projection requires Unix no-follow filesystem semantics".to_string())
    }
}

#[cfg(unix)]
fn projection_stage_file_parent(
    transaction: &OwnedEntryTransaction,
    stage_relative: &Path,
) -> Result<(AnchoredDirectory, OsString, PathBuf), String> {
    if !transaction.package_directory {
        return Ok((
            transaction
                .private_root
                .root
                .try_clone("scalar projection transaction")?,
            OsString::from("stage"),
            transaction.stage.clone(),
        ));
    }
    let file_name = stage_relative
        .file_name()
        .ok_or_else(|| {
            format!(
                "package projection stage member has no filename: {}",
                stage_relative.display()
            )
        })?
        .to_os_string();
    validate_single_path_component(&file_name, "package projection stage member")?;
    let mut parent = transaction
        .stage_anchor
        .as_ref()
        .ok_or_else(|| "package projection transaction has no stage directory".to_string())?
        .try_clone("package projection stage")?;
    for component in stage_relative
        .parent()
        .unwrap_or_else(|| Path::new(""))
        .components()
    {
        let Component::Normal(name) = component else {
            return Err(format!(
                "package projection stage path is not portable: {}",
                stage_relative.display()
            ));
        };
        parent = parent.ensure_child_directory(
            name,
            0o755,
            "package projection stage directory",
        )?;
    }
    let path = transaction.stage.join(stage_relative);
    Ok((parent, file_name, path))
}

#[cfg(unix)]
fn prepare_program_projection<F>(
    manifest: &DepsManifest,
    canonical: &Path,
    canonical_root: Option<&AnchoredDirectory>,
    output_root: &Path,
    arch: TargetArch,
    after_copy: &mut F,
) -> Result<PreparedProgramProjection, String>
where
    F: FnMut(&Path),
{
    #[cfg(not(unix))]
    {
        let _ = (manifest, canonical, canonical_root, output_root, arch, after_copy);
        return Err("source-only regular projection requires Unix permission metadata".to_string());
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mut declarations = Vec::<(String, PathBuf, Option<u32>)>::new();
        for output in &manifest.program_outputs {
            declarations.push((
                output.wasm.clone(),
                manifest.output_dest_rel_for(output),
                None,
            ));
        }
        declarations.extend(manifest.runtime_files.iter().map(|runtime_file| {
            (
                runtime_file.artifact.clone(),
                manifest.runtime_file_dest_rel_for(runtime_file),
                Some(runtime_file.mode),
            )
        }));
        if declarations.is_empty() {
            return Err(format!(
                "{}: program has no declared output/runtime closure to materialize",
                manifest.spec()
            ));
        }

        let is_package = manifest.uses_package_mirror_directory();
        let live_relative = if is_package {
            PathBuf::from("programs")
                .join(arch.as_str())
                .join(&manifest.name)
        } else {
            program_projection_destination_relative(manifest, arch, &declarations[0].1)
        };
        let live = output_root.join(&live_relative);
        let parent_guard = SourceOnlyProjectionParentGuard::prepare(output_root, &live)?;
        let allowed_stage_files = declarations
            .iter()
            .map(|(_, mirror_relative, _)| {
                if is_package {
                    package_owned_relative_path(manifest, mirror_relative).map_err(|error| {
                        format!("{}: invalid package projection path: {error}", manifest.spec())
                    })
                } else {
                    Ok(PathBuf::new())
                }
            })
            .collect::<Result<BTreeSet<_>, _>>()?;
        let mut transaction = OwnedEntryTransaction::reserve(
            parent_guard,
            live,
            is_package,
            &manifest.name,
            allowed_stage_files,
        )?;
        let stage = transaction.stage.clone();

        let mut prepared = Vec::new();
        for (source_artifact, mirror_relative, declared_mode) in declarations {
            let mut source = match canonical_root {
                Some(root) => StableProjectionSource::open_from_anchored_root(
                    root,
                    &source_artifact,
                ),
                None => StableProjectionSource::open(canonical, &source_artifact),
            }
            .map_err(|error| format!("{}: {error}", manifest.spec()))?;
            let mode = declared_mode.unwrap_or(source.file_snapshot.mode);
            let destination_relative =
                program_projection_destination_relative(manifest, arch, &mirror_relative);
            let stage_relative = if is_package {
                package_owned_relative_path(manifest, &mirror_relative).map_err(|error| {
                    format!("{}: invalid package projection path: {error}", manifest.spec())
                })?
            } else {
                PathBuf::new()
            };
            let (stage_parent, stage_name, stage_member) =
                projection_stage_file_parent(&transaction, &stage_relative)?;
            let mut stage_file = stage_parent.create_child_file_new(
                &stage_name,
                0o600,
                "source-only projected stage member",
            )?;
            let created_snapshot = receipt_metadata_snapshot(&stage_file.metadata().map_err(|error| {
                format!("inspect opened projected stage {}: {error}", stage_member.display())
            })?)?;
            if created_snapshot.kind != 1 {
                return Err(format!("projected stage is not a regular file: {}", stage_member.display()));
            }
            let mut hash = Sha256::new();
            let mut size = 0u64;
            let mut buffer = [0u8; 64 * 1024];
            loop {
                let count = std::io::Read::read(&mut source.file, &mut buffer)
                    .map_err(|error| format!("read projected member {}: {error}", source.path.display()))?;
                if count == 0 {
                    break;
                }
                std::io::Write::write_all(&mut stage_file, &buffer[..count])
                    .map_err(|error| format!("write projected stage {}: {error}", stage_member.display()))?;
                hash.update(&buffer[..count]);
                size += count as u64;
            }
            stage_file
                .set_permissions(std::fs::Permissions::from_mode(mode))
                .map_err(|error| format!("set projected stage mode {}: {error}", stage_member.display()))?;
            stage_file
                .sync_all()
                .map_err(|error| format!("sync projected stage {}: {error}", stage_member.display()))?;
            let staged_fd_snapshot = receipt_metadata_snapshot(&stage_file.metadata().map_err(|error| {
                format!("reinspect opened projected stage {}: {error}", stage_member.display())
            })?)?;
            drop(stage_file);
            let digest: [u8; 32] = hash.finalize().into();
            after_copy(&source.path);
            source.validate()?;
            let stage_snapshot = inspect_regular_projection_file_at(
                &stage_parent.file,
                &stage_name,
                &stage_member,
            )?;
            let expected_kind = LocalMirrorEntryKind::Regular {
                len: size,
                sha256: digest,
            };
            if staged_fd_snapshot.identity != stage_snapshot.identity
                || staged_fd_snapshot.mode != mode
                || stage_snapshot.mode != mode
                || stage_snapshot.kind != expected_kind
            {
                return Err(format!(
                    "projected stage changed or differs from copied bytes/mode: {}",
                    stage_member.display()
                ));
            }
            prepared.push(PreparedProgramProjectionMember {
                receipt: MaterializedProgramMemberV1 {
                    source_artifact,
                    mirror_path: portable_projection_path(
                        manifest,
                        &destination_relative,
                        "source-only output-root mirror path",
                    )?,
                    mode,
                    size,
                    sha256: hex(&digest),
                },
                stage_relative,
                stage_snapshot,
            });
        }
        prepared.sort_by(|left, right| {
            (&left.receipt.mirror_path, &left.receipt.source_artifact)
                .cmp(&(&right.receipt.mirror_path, &right.receipt.source_artifact))
        });
        let stage_snapshot = if is_package {
            let tree = inspect_regular_projection_tree_at(
                &transaction.private_root.root,
                OsStr::new("stage"),
                &stage,
            )?;
            if tree.files.len() != prepared.len()
                || prepared.iter().any(|member| {
                    tree.files.get(&member.stage_relative) != Some(&member.stage_snapshot)
                })
            {
                return Err(format!(
                    "staged package projection does not exactly match its declared closure: {}",
                    stage.display()
                ));
            }
            PreparedProjectionSnapshot::PackageDirectory(tree)
        } else {
            PreparedProjectionSnapshot::Scalar(
                prepared
                    .first()
                    .expect("nonempty scalar projection")
                    .stage_snapshot
                    .clone(),
            )
        };
        transaction.set_stage_snapshot(stage_snapshot)?;
        Ok(PreparedProgramProjection {
            transaction,
            members: prepared,
        })
    }
}

#[cfg(unix)]
fn reserve_source_only_projection_transaction(
    parent: &Path,
    package_name: &str,
) -> Result<(PathBuf, PackageMirrorIdentity), String> {
    let parent = canonical_real_directory(parent, "source-only projection transaction parent")?;
    for _ in 0..1024 {
        let sequence = MIRROR_TRANSACTION_COUNTER.fetch_add(1, Ordering::Relaxed);
        let transaction_root = parent.join(format!(
            ".{package_name}.source-only-transaction-{}-{sequence}",
            std::process::id()
        ));
        match create_private_transaction_directory(&transaction_root) {
            Ok(()) => {
                let metadata = std::fs::symlink_metadata(&transaction_root).map_err(|error| {
                    format!(
                        "inspect created source-only projection transaction {}: {error}",
                        transaction_root.display()
                    )
                })?;
                if metadata.file_type().is_symlink() || !metadata.is_dir() {
                    return Err(format!(
                        "created source-only projection transaction is not a real directory: {}",
                        transaction_root.display()
                    ));
                }
                let identity = package_mirror_identity(&metadata)?;
                let canonical = std::fs::canonicalize(&transaction_root).map_err(|error| {
                    format!(
                        "canonicalize source-only projection transaction {}: {error}",
                        transaction_root.display()
                    )
                })?;
                if canonical.parent() != Some(parent.as_path()) || canonical != transaction_root {
                    return Err(format!(
                        "source-only projection transaction escaped its validated parent: {}",
                        transaction_root.display()
                    ));
                }
                return Ok((transaction_root, identity));
            }
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(error) => {
                return Err(format!(
                    "create private source-only projection transaction {}: {error}",
                    transaction_root.display()
                ));
            }
        }
    }
    Err(format!(
        "could not allocate a private source-only projection transaction below {}",
        parent.display()
    ))
}

#[cfg(unix)]
fn validate_source_only_projection_transaction(
    path: &Path,
    expected: &PackageMirrorIdentity,
) -> Result<(), String> {
    let metadata = std::fs::symlink_metadata(path).map_err(|error| {
        format!("inspect source-only projection transaction {}: {error}", path.display())
    })?;
    if metadata.file_type().is_symlink()
        || !metadata.is_dir()
        || package_mirror_identity(&metadata)? != *expected
    {
        return Err(format!(
            "source-only projection transaction identity changed and was preserved: {}",
            path.display()
        ));
    }
    Ok(())
}

#[cfg(unix)]
fn regular_projection_directory_entry(
    metadata: &std::fs::Metadata,
) -> Result<RegularProjectionDirectoryEntry, String> {
    use std::os::unix::fs::PermissionsExt;
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err("regular projection directory must be a real nonsymlink directory".to_string());
    }
    Ok(RegularProjectionDirectoryEntry {
        identity: package_mirror_identity(metadata)?,
        mode: metadata.permissions().mode() & 0o7777,
    })
}

#[cfg(not(unix))]
fn regular_projection_directory_entry(
    _metadata: &std::fs::Metadata,
) -> Result<RegularProjectionDirectoryEntry, String> {
    Err("source-only regular projection requires Unix permission metadata".to_string())
}

#[cfg(unix)]
fn inspect_regular_projection_file_at(
    parent: &std::fs::File,
    name: &std::ffi::OsStr,
    path: &Path,
) -> Result<LocalMirrorEntrySnapshot, String> {
    inspect_regular_projection_file_at_with_limit(parent, name, path, None)
}

#[cfg(unix)]
fn inspect_regular_projection_file_at_with_limit(
    parent: &std::fs::File,
    name: &std::ffi::OsStr,
    path: &Path,
    limit: Option<u64>,
) -> Result<LocalMirrorEntrySnapshot, String> {
    use std::io::Read as _;

    let before = receipt_at_metadata_snapshot(parent, name, path)?;
    if before.kind != 1 {
        return Err(format!(
            "source-only package projection leaf must be a regular nonsymlink file: {}",
            path.display()
        ));
    }
    if limit.is_some_and(|limit| before.len > limit) {
        return Err(format!(
            "source-only projection file exceeds the {}-byte limit: {}",
            limit.unwrap(),
            path.display()
        ));
    }
    let mut file = open_receipt_entry_at(parent, name, path, false)?;
    let opened_metadata = file.metadata().map_err(|error| {
        format!("inspect opened source-only projection file {}: {error}", path.display())
    })?;
    let opened = receipt_metadata_snapshot(&opened_metadata)?;
    if opened.kind != 1 || !receipt_at_matches_opened(&before, &opened_metadata)? {
        return Err(format!(
            "source-only projection file changed while opening: {}",
            path.display()
        ));
    }
    let mut hasher = Sha256::new();
    let copied = match limit {
        Some(limit) => std::io::copy(&mut file.by_ref().take(limit.saturating_add(1)), &mut hasher),
        None => std::io::copy(&mut file, &mut hasher),
    }
    .map_err(|error| format!("hash source-only projection file {}: {error}", path.display()))?;
    if limit.is_some_and(|limit| copied > limit) {
        return Err(format!(
            "source-only projection file exceeds the {}-byte limit: {}",
            limit.unwrap(),
            path.display()
        ));
    }
    let after = receipt_metadata_snapshot(&file.metadata().map_err(|error| {
        format!("reinspect opened source-only projection file {}: {error}", path.display())
    })?)?;
    let reopened = open_receipt_entry_at(parent, name, path, false)?;
    let reopened_snapshot = receipt_metadata_snapshot(&reopened.metadata().map_err(|error| {
        format!("inspect reopened source-only projection file {}: {error}", path.display())
    })?)?;
    if after != opened || reopened_snapshot != opened {
        return Err(format!(
            "source-only projection file changed while hashed: {}",
            path.display()
        ));
    }
    Ok(LocalMirrorEntrySnapshot {
        identity: opened.identity,
        kind: LocalMirrorEntryKind::Regular {
            len: opened.len,
            sha256: hasher.finalize().into(),
        },
        mode: opened.mode,
    })
}

#[cfg(unix)]
fn read_exact_regular_child_at(
    parent: &AnchoredDirectory,
    name: &OsStr,
    path: &Path,
    limit: u64,
    label: &str,
) -> Result<(Vec<u8>, LocalMirrorEntrySnapshot), String> {
    use std::io::Read as _;

    let expected = inspect_regular_projection_file_at(&parent.file, name, path)?;
    let mut file = open_receipt_entry_at(&parent.file, name, path, false)?;
    let opened = receipt_metadata_snapshot(&file.metadata().map_err(|error| {
        format!("inspect opened {label} {}: {error}", path.display())
    })?)?;
    if opened.identity != expected.identity
        || opened.mode != expected.mode
        || !matches!(
            expected.kind,
            LocalMirrorEntryKind::Regular { len, .. } if len == opened.len
        )
    {
        return Err(format!("{label} changed while opening: {}", path.display()));
    }
    let mut bytes = Vec::new();
    file.by_ref()
        .take(limit.saturating_add(1))
        .read_to_end(&mut bytes)
        .map_err(|error| format!("read {label} {}: {error}", path.display()))?;
    if bytes.len() as u64 > limit {
        return Err(format!("{label} exceeds {limit} bytes: {}", path.display()));
    }
    if receipt_metadata_snapshot(&file.metadata().map_err(|error| {
        format!("reinspect opened {label} {}: {error}", path.display())
    })?)? != opened
    {
        return Err(format!("{label} changed while reading: {}", path.display()));
    }
    let final_snapshot = inspect_regular_projection_file_at(&parent.file, name, path)?;
    if final_snapshot != expected {
        return Err(format!("{label} changed while reading: {}", path.display()));
    }
    let digest: [u8; 32] = Sha256::digest(&bytes).into();
    if expected.kind
        != (LocalMirrorEntryKind::Regular {
            len: bytes.len() as u64,
            sha256: digest,
        })
    {
        return Err(format!("{label} bytes changed while reading: {}", path.display()));
    }
    Ok((bytes, expected))
}

fn inspect_regular_projection_tree(path: &Path) -> Result<RegularProjectionTreeSnapshot, String> {
    #[cfg(not(unix))]
    {
        let _ = path;
        return Err("source-only regular projection requires Unix no-follow filesystem semantics".to_string());
    }
    #[cfg(unix)]
    {
        let root_file = open_receipt_root(path)?;
        let root_metadata = root_file.metadata().map_err(|error| {
            format!("inspect opened source-only package projection {}: {error}", path.display())
        })?;
        let root = regular_projection_directory_entry(&root_metadata)?;
        let mut directories = BTreeMap::new();
        let mut files = BTreeMap::new();
        inspect_regular_projection_directory_contents(
            &root_file,
            path,
            Path::new(""),
            &mut directories,
            &mut files,
        )?;
        let reopened = open_receipt_root(path)?;
        if regular_projection_directory_entry(&reopened.metadata().map_err(|error| {
            format!("reinspect opened source-only package projection {}: {error}", path.display())
        })?)? != root
        {
            return Err(format!(
                "source-only package projection root changed while inspected: {}",
                path.display()
            ));
        }
        Ok(RegularProjectionTreeSnapshot {
            root,
            directories,
            files,
        })
    }
}

#[cfg(unix)]
fn inspect_regular_projection_tree_at(
    parent: &AnchoredDirectory,
    name: &OsStr,
    path: &Path,
) -> Result<RegularProjectionTreeSnapshot, String> {
    let before = receipt_at_metadata_snapshot(&parent.file, name, path)?;
    if before.kind != 2 {
        return Err(format!(
            "source-only package projection must be a real nonsymlink directory: {}",
            path.display()
        ));
    }
    let root_anchor = parent.open_child_directory(
        name,
        "source-only package projection",
    )?;
    if root_anchor.identity != before.identity {
        return Err(format!(
            "source-only package projection changed while opening: {}",
            path.display()
        ));
    }
    let root = regular_projection_directory_entry(
        &root_anchor.file.metadata().map_err(|error| {
            format!(
                "inspect opened source-only package projection {}: {error}",
                path.display()
            )
        })?,
    )?;
    let mut directories = BTreeMap::new();
    let mut files = BTreeMap::new();
    inspect_regular_projection_directory_contents(
        &root_anchor.file,
        path,
        Path::new(""),
        &mut directories,
        &mut files,
    )?;
    let after = receipt_at_metadata_snapshot(&parent.file, name, path)?;
    if after != before {
        return Err(format!(
            "source-only package projection changed while inspected: {}",
            path.display()
        ));
    }
    Ok(RegularProjectionTreeSnapshot {
        root,
        directories,
        files,
    })
}

#[cfg(unix)]
fn inspect_projection_child(
    parent: &AnchoredDirectory,
    name: &OsStr,
    path: &Path,
    expected: &PreparedProjectionSnapshot,
) -> Result<PreparedProjectionSnapshot, String> {
    inspect_projection_child_with_limit(parent, name, path, expected, None)
}

#[cfg(unix)]
fn inspect_projection_child_with_limit(
    parent: &AnchoredDirectory,
    name: &OsStr,
    path: &Path,
    expected: &PreparedProjectionSnapshot,
    scalar_read_limit: Option<u64>,
) -> Result<PreparedProjectionSnapshot, String> {
    match expected {
        PreparedProjectionSnapshot::Scalar(_) => inspect_regular_projection_file_at_with_limit(
            &parent.file,
            name,
            path,
            scalar_read_limit,
        )
        .map(PreparedProjectionSnapshot::Scalar),
        PreparedProjectionSnapshot::PackageDirectory(_) => {
            inspect_regular_projection_tree_at(parent, name, path)
                .map(PreparedProjectionSnapshot::PackageDirectory)
        }
    }
}

#[cfg(unix)]
fn inspect_regular_projection_directory_contents(
    directory: &std::fs::File,
    path: &Path,
    relative: &Path,
    directories: &mut BTreeMap<PathBuf, RegularProjectionDirectoryEntry>,
    files: &mut BTreeMap<PathBuf, LocalMirrorEntrySnapshot>,
) -> Result<(), String> {
    let names = stable_receipt_directory_names(directory, path)?;
    for name in &names {
        let child_path = path.join(name);
        let child_relative = relative.join(name);
        let metadata = receipt_at_metadata_snapshot(directory, name, &child_path)?;
        match metadata.kind {
            1 => {
                let snapshot = inspect_regular_projection_file_at(directory, name, &child_path)?;
                files.insert(child_relative, snapshot);
            }
            2 => {
                let child = open_receipt_entry_at(directory, name, &child_path, false)?;
                let child_entry = regular_projection_directory_entry(
                    &child.metadata().map_err(|error| {
                        format!("inspect opened projection directory {}: {error}", child_path.display())
                    })?,
                )?;
                if child_entry.identity != metadata.identity || child_entry.mode != metadata.mode {
                    return Err(format!(
                        "source-only projection directory changed while opening: {}",
                        child_path.display()
                    ));
                }
                directories.insert(child_relative.clone(), child_entry.clone());
                inspect_regular_projection_directory_contents(
                    &child,
                    &child_path,
                    &child_relative,
                    directories,
                    files,
                )?;
                let reopened = open_receipt_entry_at(directory, name, &child_path, false)?;
                if regular_projection_directory_entry(&reopened.metadata().map_err(|error| {
                    format!("reinspect projection directory {}: {error}", child_path.display())
                })?)? != child_entry
                {
                    return Err(format!(
                        "source-only projection directory changed while traversed: {}",
                        child_path.display()
                    ));
                }
            }
            _ => {
                return Err(format!(
                    "source-only package projection contains a symlink or special entry: {}",
                    child_path.display()
                ));
            }
        }
    }
    let reopened_names = {
        let reopened = rustix::fs::openat(
            directory,
            ".",
            rustix::fs::OFlags::RDONLY
                | rustix::fs::OFlags::CLOEXEC
                | rustix::fs::OFlags::NOFOLLOW
                | rustix::fs::OFlags::NONBLOCK,
            rustix::fs::Mode::empty(),
        )
        .map(std::fs::File::from)
        .map_err(|error| format!("reopen projection directory {}: {error}", path.display()))?;
        stable_receipt_directory_names(&reopened, path)?
    };
    if reopened_names != names {
        return Err(format!(
            "source-only projection directory changed while traversed: {}",
            path.display()
        ));
    }
    Ok(())
}

fn projection_snapshots_semantically_equal(
    left: &PreparedProjectionSnapshot,
    right: &PreparedProjectionSnapshot,
) -> bool {
    match (left, right) {
        (PreparedProjectionSnapshot::Scalar(left), PreparedProjectionSnapshot::Scalar(right)) => {
            left.kind == right.kind && left.mode == right.mode
        }
        (
            PreparedProjectionSnapshot::PackageDirectory(left),
            PreparedProjectionSnapshot::PackageDirectory(right),
        ) => {
            left.root.mode == right.root.mode
                && left.directories.len() == right.directories.len()
                && left.files.len() == right.files.len()
                && left.directories.iter().all(|(path, entry)| {
                    right.directories.get(path).is_some_and(|other| other.mode == entry.mode)
                })
                && left.files.iter().all(|(path, entry)| {
                    right.files.get(path).is_some_and(|other| {
                        other.kind == entry.kind && other.mode == entry.mode
                    })
                })
        }
        _ => false,
    }
}

fn inspect_projection_like(
    path: &Path,
    expected: &PreparedProjectionSnapshot,
) -> Result<PreparedProjectionSnapshot, String> {
    match expected {
        PreparedProjectionSnapshot::Scalar(_) => {
            let metadata = std::fs::symlink_metadata(path).map_err(|error| {
                format!("inspect scalar source-only projection {}: {error}", path.display())
            })?;
            if metadata.file_type().is_symlink() || !metadata.is_file() {
                return Err(format!(
                    "source-only projection destination must be a regular nonsymlink file: {}",
                    path.display()
                ));
            }
            inspect_local_mirror_entry(path).map(PreparedProjectionSnapshot::Scalar)
        }
        PreparedProjectionSnapshot::PackageDirectory(_) => {
            inspect_regular_projection_tree(path).map(PreparedProjectionSnapshot::PackageDirectory)
        }
    }
}

fn append_cleanup_error(error: String, cleanup: Result<(), String>) -> String {
    match cleanup {
        Ok(()) => error,
        Err(cleanup) => format!("{error}; private projection cleanup preserved evidence: {cleanup}"),
    }
}

fn ensure_projection_descendant_parents(root: &Path, descendant: &Path) -> Result<(), String> {
    let relative = descendant.strip_prefix(root).map_err(|_| {
        format!("source-only projection path escapes stage/output root: {}", descendant.display())
    })?;
    let mut current = root.to_path_buf();
    for component in relative.parent().unwrap_or_else(|| Path::new("")).components() {
        let Component::Normal(component) = component else {
            return Err(format!("source-only projection path is not portable: {}", relative.display()));
        };
        let next = current.join(component);
        ensure_real_child_directory(&current, &next, "source-only projection directory")?;
        current = next;
    }
    Ok(())
}

#[cfg(unix)]
fn projection_live_snapshot(
    transaction: &OwnedEntryTransaction,
) -> Result<Option<PreparedProjectionSnapshot>, String> {
    let stage_snapshot = transaction.stage_snapshot()?;
    if !transaction.parent_guard.parent_anchor.child_exists(
        &transaction.parent_guard.live_name,
        "source-only projection destination",
    )? {
        return Ok(None);
    }
    transaction.inspect_live(stage_snapshot).map(Some)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[cfg(unix)]
enum OwnedEntryPublishPhase {
    BeforeQuarantineRename,
    Quarantined,
    BeforePublishRename,
    Published,
    BeforePrivateDisposal,
    BeforePrivateContentRemoval,
}

#[cfg(unix)]
fn fail_owned_entry_transaction(
    transaction: &mut OwnedEntryTransaction,
    lock: &SourceOnlyProjectionLock,
    error: String,
) -> Result<(), String> {
    if transaction.stage_published
        && transaction.old_moved
        && !transaction.restore_after_published_failure
    {
        transaction.preserve = true;
        transaction.private_root.preserve = true;
        return Err(format!(
            "{error}; the committed live generation and validated prior generation at {} were preserved",
            transaction.backup.display()
        ));
    }
    if transaction.stage_published && !transaction.old_moved {
        return Err(append_cleanup_error(error, transaction.dispose_private_root()));
    }
    if transaction.old_moved {
        if let Err(authority_error) = transaction
            .parent_guard
            .validate()
            .and_then(|()| lock.validate())
        {
            transaction.preserve = true;
            transaction.private_root.preserve = true;
            return Err(format!(
                "{error}; live-mutation authority was lost ({authority_error}), so the validated prior generation was preserved at {}",
                transaction.backup.display()
            ));
        }
        if !transaction.stage_published
            && transaction.parent_guard.parent_anchor.child_exists(
                &transaction.parent_guard.live_name,
                "source-only projection destination",
            )?
        {
            transaction.preserve = true;
            transaction.private_root.preserve = true;
            return Err(format!(
                "{error}; a live entry and the validated prior generation at {} were both preserved",
                transaction.backup.display()
            ));
        }
        if let Err(restore_error) = transaction.restore_backup(lock) {
            transaction.preserve = true;
            transaction.private_root.preserve = true;
            return Err(format!(
                "{error}; restoring the validated prior generation also failed: {restore_error}"
            ));
        }
    }
    Err(append_cleanup_error(error, transaction.dispose_private_root()))
}

#[cfg(unix)]
fn validate_owned_entry_mutation_authority<F>(
    transaction: &OwnedEntryTransaction,
    lock: &SourceOnlyProjectionLock,
    external_authority: &mut F,
) -> Result<(), String>
where
    F: FnMut(&Path) -> Result<(), String>,
{
    transaction.validate_private_tree(&transaction.transaction_root)?;
    external_authority(&transaction.live)?;
    transaction.parent_guard.validate()?;
    // Lock identity is intentionally the final check after all potentially
    // expensive tree hashing. The following caller performs only its anchored
    // rename before checking again at the next mutation boundary.
    lock.validate()
}

#[cfg(unix)]
fn validate_owned_entry_exchange_authority<F>(
    transaction: &OwnedEntryTransaction,
    lock: &SourceOnlyProjectionLock,
    external_authority: &mut F,
    expected_live: &PreparedProjectionSnapshot,
) -> Result<(), String>
where
    F: FnMut(&Path) -> Result<(), String>,
{
    transaction.validate_private_tree(&transaction.transaction_root)?;
    external_authority(&transaction.live)?;
    if transaction.inspect_live(expected_live)? != *expected_live {
        return Err(format!(
            "source-only projection destination changed at its atomic exchange boundary: {}",
            transaction.live.display()
        ));
    }
    transaction.parent_guard.validate()?;
    // No expensive reads occur between this final lock validation and the
    // immediately following descriptor-relative atomic exchange.
    lock.validate()
}

#[cfg(unix)]
fn publish_owned_entry_transaction<F>(
    subject: &str,
    output_root: &Path,
    transaction: &mut OwnedEntryTransaction,
    lock: &SourceOnlyProjectionLock,
    before_publish: &mut F,
) -> Result<(), String>
where
    F: FnMut(&Path) -> Result<(), String>,
{
    publish_owned_entry_transaction_with_hook(
        subject,
        output_root,
        transaction,
        lock,
        before_publish,
        &mut |_, _| Ok(()),
    )
}

#[cfg(unix)]
fn publish_owned_entry_transaction_with_hook<F, H>(
    subject: &str,
    output_root: &Path,
    transaction: &mut OwnedEntryTransaction,
    lock: &SourceOnlyProjectionLock,
    before_publish: &mut F,
    phase_hook: &mut H,
) -> Result<(), String>
where
    F: FnMut(&Path) -> Result<(), String>,
    H: FnMut(OwnedEntryPublishPhase, &Path) -> Result<(), String>,
{
    if lock.output_root.identity != transaction.parent_guard.root_anchor.identity
        || lock.output_root.path != transaction.parent_guard.root_anchor.path
        || lock.output_root.path != output_root
    {
        transaction.preserve = true;
        transaction.private_root.preserve = true;
        return Err(format!(
            "{}: projection lock and transaction do not share one opened output-root generation",
            subject
        ));
    }
    let disposal_parent_guard = transaction.parent_guard.try_clone()?;
    transaction.parent_guard.validate()?;
    transaction.validate_private_tree(&transaction.transaction_root)?;
    let stage_snapshot = transaction.stage_snapshot()?.clone();
    if transaction.inspect_stage()? != stage_snapshot {
        return Err(format!(
            "{}: source-only projection stage changed before publication: {}",
            subject,
            transaction.stage.display()
        ));
    }
    lock.validate()?;
    let initial_live = projection_live_snapshot(transaction)?;
    if let Err(error) = before_publish(&transaction.live) {
        return fail_owned_entry_transaction(transaction, lock, error);
    }
    lock.validate()?;
    transaction.parent_guard.validate()?;
    transaction.validate_private_tree(&transaction.transaction_root)?;
    if transaction.inspect_stage()? != stage_snapshot {
        return Err(format!(
            "{}: source-only projection stage changed while awaiting publication: {}",
            subject,
            transaction.stage.display()
        ));
    }
    if projection_live_snapshot(transaction)? != initial_live {
        return Err(format!(
            "{}: source-only projection destination changed before its transaction: {}",
            subject,
            transaction.live.display()
        ));
    }
    if initial_live
        .as_ref()
        .is_some_and(|live| projection_snapshots_semantically_equal(live, &stage_snapshot))
    {
        if let Err(error) = phase_hook(
            OwnedEntryPublishPhase::BeforePrivateDisposal,
            &transaction.transaction_root,
        ) {
            return fail_owned_entry_transaction(transaction, lock, error);
        }
        if let Err(error) =
            validate_owned_entry_mutation_authority(transaction, lock, before_publish)
        {
            return fail_owned_entry_transaction(transaction, lock, error);
        }
        transaction.dispose_private_root_with(&mut |path| {
            phase_hook(OwnedEntryPublishPhase::BeforePrivateContentRemoval, path)?;
            before_publish(path)?;
            disposal_parent_guard.validate()?;
            lock.validate()
        })?;
        transaction.parent_guard.parent_anchor.sync(
            "source-only projection parent",
        )?;
        if projection_live_snapshot(transaction)?.as_ref() != initial_live.as_ref() {
            return Err(format!(
                "{}: equal source-only projection changed after private cleanup",
                subject
            ));
        }
        return Ok(());
    }

    let publication = if let Some(live) = initial_live {
        if let Err(error) = phase_hook(
            OwnedEntryPublishPhase::BeforeQuarantineRename,
            &transaction.live,
        ) {
            return fail_owned_entry_transaction(transaction, lock, error);
        }
        if let Err(error) = validate_owned_entry_exchange_authority(
            transaction,
            lock,
            before_publish,
            &live,
        )
        {
            return fail_owned_entry_transaction(transaction, lock, error);
        }
        if let Err(error) = phase_hook(
            OwnedEntryPublishPhase::BeforePublishRename,
            &transaction.live,
        ) {
            return fail_owned_entry_transaction(transaction, lock, error);
        }
        if let Err(error) = validate_owned_entry_exchange_authority(
            transaction,
            lock,
            before_publish,
            &live,
        )
        {
            return fail_owned_entry_transaction(transaction, lock, error);
        }
        match transaction.private_root.root.exchange_child(
            OsStr::new("stage"),
            &transaction.parent_guard.parent_anchor,
            &transaction.parent_guard.live_name,
            "source-only projection publication",
        ) {
            Err(error) => Err(error),
            Ok(()) => {
                // The public namespace changed in one atomic exchange:
                // readers observe either the complete old package directory
                // or the complete new one. The following rename is private.
                transaction.old_moved = true;
                transaction.stage_published = true;
                transaction.preserve = true;
                transaction.private_root.preserve = true;
                if let Err(error) = transaction.private_root.root.rename_child_no_replace(
                    OsStr::new("stage"),
                    &transaction.private_root.root,
                    OsStr::new("backup"),
                    "source-only projection exchanged backup",
                ) {
                    return Err(format!(
                        "{}: the new source-only projection was atomically installed, but its validated prior generation remains preserved at {} after private backup placement failed: {error}",
                        subject,
                        transaction.stage.display(),
                    ));
                }
                transaction.backup_snapshot = Some(live.clone());
                let quarantined = transaction.inspect_backup(&live);
                if quarantined.as_ref() != Ok(&live) {
                    let detail = quarantined.err().unwrap_or_else(|| {
                        "exchanged prior generation changed identity/content/mode".to_string()
                    });
                    return fail_owned_entry_transaction(
                        transaction,
                        lock,
                        format!(
                            "{}: source-only projection changed after atomic exchange: {detail}",
                            subject
                        ),
                    );
                }
                if transaction.inspect_live(&stage_snapshot).as_ref() != Ok(&stage_snapshot) {
                    return fail_owned_entry_transaction(
                        transaction,
                        lock,
                        format!(
                            "{}: atomically published source-only projection differs from its stage",
                            subject
                        ),
                    );
                }
                if let Err(error) = phase_hook(
                    OwnedEntryPublishPhase::Quarantined,
                    &transaction.backup,
                ) {
                    return fail_owned_entry_transaction(transaction, lock, error);
                }
                Ok(())
            }
        }
    } else {
        if let Err(error) = phase_hook(
            OwnedEntryPublishPhase::BeforePublishRename,
            &transaction.live,
        ) {
            return fail_owned_entry_transaction(transaction, lock, error);
        }
        if let Err(error) =
            validate_owned_entry_mutation_authority(transaction, lock, before_publish)
        {
            return fail_owned_entry_transaction(transaction, lock, error);
        }
        transaction.private_root.root.rename_child_no_replace(
            OsStr::new("stage"),
            &transaction.parent_guard.parent_anchor,
            &transaction.parent_guard.live_name,
            "source-only projection publication",
        )
    };

    match publication {
        Ok(()) => {
            transaction.stage_published = true;
            let installed = transaction.inspect_live(&stage_snapshot);
            if installed.as_ref() != Ok(&stage_snapshot) {
                return fail_owned_entry_transaction(
                    transaction,
                    lock,
                    format!(
                        "{}: published source-only projection differs from its exact staged identity/content/mode and was preserved: {}",
                        subject,
                        transaction.live.display()
                    ),
                );
            }
            if let Err(error) = phase_hook(
                OwnedEntryPublishPhase::Published,
                &transaction.live,
            ) {
                return fail_owned_entry_transaction(transaction, lock, error);
            }
            if let Err(error) = lock
                .validate()
                .and_then(|()| transaction.parent_guard.validate())
                .and_then(|()| transaction.validate_private_tree(&transaction.transaction_root))
            {
                return fail_owned_entry_transaction(transaction, lock, error);
            }
            let final_installed = transaction.inspect_live(&stage_snapshot);
            if final_installed.as_ref() != Ok(&stage_snapshot) {
                return fail_owned_entry_transaction(
                    transaction,
                    lock,
                    format!(
                        "{}: published source-only projection changed before validated prior-generation disposal and was preserved: {}",
                        subject,
                        transaction.live.display()
                    ),
                );
            }
            if let Err(error) = phase_hook(
                OwnedEntryPublishPhase::BeforePrivateDisposal,
                &transaction.transaction_root,
            ) {
                return fail_owned_entry_transaction(transaction, lock, error);
            }
            if let Err(error) =
                validate_owned_entry_mutation_authority(transaction, lock, before_publish)
            {
                return fail_owned_entry_transaction(transaction, lock, error);
            }
            match transaction.inspect_live(&stage_snapshot) {
                Ok(current) if current == stage_snapshot => {}
                Ok(_) => {
                    return fail_owned_entry_transaction(
                        transaction,
                        lock,
                        format!(
                            "{}: published source-only projection changed immediately before transaction disposal: {}",
                            subject,
                            transaction.live.display()
                        ),
                    );
                }
                Err(error) => return fail_owned_entry_transaction(transaction, lock, error),
            }
            transaction.preserve = false;
            transaction.dispose_private_root_with(&mut |path| {
                phase_hook(OwnedEntryPublishPhase::BeforePrivateContentRemoval, path)?;
                before_publish(path)?;
                disposal_parent_guard.validate()?;
                lock.validate()
            })?;
            transaction.parent_guard.parent_anchor.sync(
                "source-only projection parent",
            )?;
            if transaction.inspect_live(&stage_snapshot)? != stage_snapshot
            {
                return Err(format!(
                    "{}: published source-only projection changed after transaction cleanup: {}",
                    subject,
                    transaction.live.display()
                ));
            }
            Ok(())
        }
        Err(publish_error) => {
            let winner = match projection_live_snapshot(transaction) {
                Ok(winner) => winner,
                Err(error) => return fail_owned_entry_transaction(transaction, lock, error),
            };
            if let Some(winner) = winner {
                if !transaction.old_moved
                    && projection_snapshots_semantically_equal(&winner, &stage_snapshot)
                {
                    if transaction.inspect_stage()? != stage_snapshot {
                        transaction.preserve = transaction.old_moved;
                        return Err(format!(
                            "{}: equal concurrent source-only projection winner was observed, but the private stage changed and was preserved: {}",
                            subject,
                            transaction.stage.display()
                        ));
                    }
                    if let Err(error) = phase_hook(
                        OwnedEntryPublishPhase::BeforePrivateDisposal,
                        &transaction.transaction_root,
                    ) {
                        return fail_owned_entry_transaction(transaction, lock, error);
                    }
                    if let Err(error) =
                        validate_owned_entry_mutation_authority(transaction, lock, before_publish)
                    {
                        return fail_owned_entry_transaction(transaction, lock, error);
                    }
                    if projection_live_snapshot(transaction)?.as_ref() != Some(&winner) {
                        transaction.preserve = transaction.old_moved;
                        return Err(format!(
                            "{}: equal source-only projection winner changed before prior-generation disposal",
                            subject
                        ));
                    }
                    transaction.dispose_private_root_with(&mut |path| {
                        phase_hook(OwnedEntryPublishPhase::BeforePrivateContentRemoval, path)?;
                        before_publish(path)?;
                        disposal_parent_guard.validate()?;
                        lock.validate()
                    })?;
                    transaction.parent_guard.parent_anchor.sync(
                        "source-only projection parent",
                    )?;
                    if projection_live_snapshot(transaction)?.as_ref() != Some(&winner) {
                        return Err(format!(
                            "{}: equal source-only projection winner changed after private cleanup",
                            subject
                        ));
                    }
                    return Ok(());
                }
                transaction.preserve = transaction.old_moved;
                transaction.private_root.preserve = transaction.old_moved;
                let cleanup = if transaction.old_moved {
                    Ok(())
                } else {
                    transaction.dispose_private_root()
                };
                return Err(append_cleanup_error(
                    format!(
                        "{}: publish source-only projection {} failed ({publish_error}); a differing concurrent winner was preserved{}",
                        subject,
                        transaction.live.display(),
                        if transaction.old_moved {
                            format!(
                                " and the validated prior generation remains quarantined at {}",
                                transaction.backup.display()
                            )
                        } else {
                            String::new()
                        }
                    ),
                    cleanup,
                ));
            }
            fail_owned_entry_transaction(
                transaction,
                lock,
                format!(
                    "{}: publish source-only projection {} without replacement failed: {publish_error}",
                    subject,
                    transaction.live.display()
                ),
            )
        }
    }
}

fn package_manifest_sha256(manifest_path: &Path) -> Result<String, String> {
    let bytes = std::fs::read(manifest_path).map_err(|e| {
        format!(
            "read {} for package identity digest: {e}",
            manifest_path.display()
        )
    })?;
    Ok(hex(&Sha256::digest(bytes)))
}

fn stable_package_manifest_sha256(manifest_path: &Path) -> Result<String, String> {
    stable_package_manifest_sha256_with_after_reopen(manifest_path, &mut |_| {})
}

fn stable_package_manifest_sha256_with_after_reopen<F>(
    manifest_path: &Path,
    after_reopen: &mut F,
) -> Result<String, String>
where
    F: FnMut(&Path),
{
    let snapshot = inspect_local_mirror_entry_with_hooks(
        manifest_path,
        &mut |_| {},
        after_reopen,
    )?;
    match snapshot.kind {
        LocalMirrorEntryKind::Regular { len, sha256 } if len <= 16 * 1024 * 1024 => {
            Ok(hex(&sha256))
        }
        LocalMirrorEntryKind::Regular { len, .. } => Err(format!(
            "package manifest is {len} bytes, exceeding the 16 MiB stable-read bound: {}",
            manifest_path.display()
        )),
        LocalMirrorEntryKind::Symlink { .. } => Err(format!(
            "package manifest must be a regular nonsymlink file: {}",
            manifest_path.display()
        )),
    }
}

fn package_context_cache_keys(
    manifest: &DepsManifest,
    registry: &Registry,
) -> Result<BTreeMap<String, String>, String> {
    package_context_cache_keys_for_policy(
        manifest,
        registry,
        current_abi_version(),
        ResolvePolicy::Default,
    )
}

fn package_context_cache_keys_for_policy(
    manifest: &DepsManifest,
    registry: &Registry,
    abi_version: u32,
    policy: ResolvePolicy,
) -> Result<BTreeMap<String, String>, String> {
    let mut cache_keys = BTreeMap::new();
    let mut memo = BTreeMap::new();
    for arch in PROGRAM_PACKAGE_CONTEXT_ARCHES {
        let cache_key = compute_sha_for_policy(
            manifest,
            registry,
            arch,
            abi_version,
            policy,
            &mut memo,
            &mut Vec::new(),
        )?;
        cache_keys.insert(arch.as_str().to_string(), hex(&cache_key));
    }
    Ok(cache_keys)
}

fn package_context_cache_keys_with_global_toolchain_inputs(
    manifest: &DepsManifest,
    registry: &Registry,
    global_toolchain_inputs: Option<&[BuildInputDigest]>,
) -> Result<BTreeMap<String, String>, String> {
    let mut cache_keys = BTreeMap::new();
    let mut memo = BTreeMap::new();
    for arch in PROGRAM_PACKAGE_CONTEXT_ARCHES {
        let cache_key = compute_sha_with_global_toolchain_inputs(
            manifest,
            registry,
            arch,
            current_abi_version(),
            &mut memo,
            &mut Vec::new(),
            global_toolchain_inputs,
        )?;
        cache_keys.insert(arch.as_str().to_string(), hex(&cache_key));
    }
    Ok(cache_keys)
}

fn require_regular_nonsymlink_file(path: &Path, context: &str) -> Result<(), String> {
    let metadata =
        std::fs::symlink_metadata(path).map_err(|e| format!("inspect {}: {e}", path.display()))?;
    if !metadata.is_file() || metadata.file_type().is_symlink() {
        return Err(format!(
            "{context} must be a regular non-symlink file: {}",
            path.display()
        ));
    }
    Ok(())
}

fn collect_program_dependency_identities(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    identities: &mut BTreeMap<String, ProgramDependencyIdentity>,
    visiting: &mut Vec<String>,
    memo: &mut BTreeMap<String, [u8; 32]>,
    abi_version: u32,
    policy: ResolvePolicy,
) -> Result<(), String> {
    if visiting.iter().any(|name| name == &target.name) {
        return Err(format!(
            "cycle in projected dependency graph: {} -> {}",
            visiting.join(" -> "),
            target.name
        ));
    }
    visiting.push(target.name.clone());

    for dependency_ref in &target.depends_on {
        if visiting.iter().any(|name| name == &dependency_ref.name) {
            return Err(format!(
                "cycle in projected dependency graph: {} -> {}",
                visiting.join(" -> "),
                dependency_ref.name
            ));
        }
        let manifest_path = registry.find(&dependency_ref.name).ok_or_else(|| {
            format!(
                "{} depends on {}@{}, but that package is absent from the selected registry roots",
                target.spec(),
                dependency_ref.name,
                dependency_ref.version
            )
        })?;
        let dependency = registry.load(&dependency_ref.name)?;
        if dependency.version != dependency_ref.version {
            return Err(format!(
                "{} depends on {}@{}, but registry has {}",
                target.spec(),
                dependency_ref.name,
                dependency_ref.version,
                dependency.spec()
            ));
        }
        // Program-package v2 identities are contextual to the selected
        // program architecture. They describe the dependency identity under
        // that context; they do not claim the architecture of the concrete
        // scheduler/materialization node after fallback.
        let cache_key = hex(&compute_sha_for_policy(
            &dependency,
            registry,
            arch,
            abi_version,
            policy,
            memo,
            &mut Vec::new(),
        )?);
        let identity = ProgramDependencyIdentity {
            package_name: dependency.name.clone(),
            manifest_sha256: match policy {
                ResolvePolicy::Default => package_manifest_sha256(&manifest_path)?,
                ResolvePolicy::SourceOnlyV1 => {
                    stable_package_manifest_sha256(&manifest_path)?
                }
            },
            cache_key,
        };
        let should_recurse = match identities.get(&dependency.name) {
            Some(previous) if previous != &identity => {
                return Err(format!(
                    "{} resolves dependency {:?} to conflicting identities while projecting {}",
                    target.spec(),
                    dependency.name,
                    arch.as_str()
                ));
            }
            Some(_) => false,
            None => {
                identities.insert(dependency.name.clone(), identity);
                true
            }
        };
        if should_recurse {
            collect_program_dependency_identities(
                &dependency,
                registry,
                arch,
                identities,
                visiting,
                memo,
                abi_version,
                policy,
            )?;
        }
    }

    visiting.pop();
    Ok(())
}

fn program_dependency_closure(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
) -> Result<Vec<ProgramDependencyIdentity>, String> {
    program_dependency_closure_for_policy(
        target,
        registry,
        arch,
        current_abi_version(),
        ResolvePolicy::Default,
    )
}

fn program_dependency_closure_for_policy(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    abi_version: u32,
    policy: ResolvePolicy,
) -> Result<Vec<ProgramDependencyIdentity>, String> {
    let mut identities = BTreeMap::new();
    collect_program_dependency_identities(
        target,
        registry,
        arch,
        &mut identities,
        &mut Vec::new(),
        &mut BTreeMap::new(),
        abi_version,
        policy,
    )?;
    Ok(identities.into_values().collect())
}

fn program_package_index_for_root_once(
    root: &Path,
    registry: &Registry,
) -> Result<ProgramPackageIndex, String> {
    let canonical_root = std::fs::canonicalize(root)
        .map_err(|e| format!("resolve program registry root {}: {e}", root.display()))?;
    let mut first_existing_root = None;
    for candidate in &registry.roots {
        match std::fs::metadata(candidate) {
            Ok(metadata) => {
                first_existing_root = Some((candidate, metadata));
                break;
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
            Err(error) => {
                return Err(format!(
                    "inspect configured program registry root {}: {error}",
                    candidate.display()
                ));
            }
        }
    }
    let (first_existing_root, first_existing_metadata) = first_existing_root.ok_or_else(|| {
        format!(
            "{}: no configured program registry root exists",
            root.display()
        )
    })?;
    if !first_existing_metadata.is_dir() {
        return Err(format!(
            "configured program registry root is not a directory: {}",
            first_existing_root.display()
        ));
    }
    let canonical_first = std::fs::canonicalize(first_existing_root).map_err(|e| {
        format!(
            "resolve configured program registry root {}: {e}",
            first_existing_root.display()
        )
    })?;
    if canonical_root != canonical_first {
        return Err(format!(
            "{} is not the highest-priority existing configured registry root {}; generate each index with its owning root first in the ordered registry context",
            root.display(),
            first_existing_root.display(),
        ));
    }

    // The first generated index in an ordered registry path is the
    // authoritative view of that complete first-hit context. Include both
    // identities and program projections from lower roots: a dependency-only
    // override can change a lower program's cache key without changing that
    // program's physical manifest or members. Lower suffix indexes remain
    // self-contained fallbacks when their root becomes the first existing one.
    let selected_manifests = registry.walk_all()?;
    let mut identities = BTreeMap::new();
    for (selected_name, manifest) in &selected_manifests {
        if &manifest.name != selected_name {
            return Err(format!(
                "{}: selected registry key {:?} does not match manifest package name {:?}",
                root.display(),
                selected_name,
                manifest.name
            ));
        }
        let manifest_path = manifest.dir.join("package.toml");
        let identity = ProgramPackageIdentity {
            manifest_sha256: package_manifest_sha256(&manifest_path)?,
            cache_keys: package_context_cache_keys(&manifest, registry)?,
        };
        if identities.insert(manifest.name.clone(), identity).is_some() {
            return Err(format!(
                "{}: duplicate selected package identity {:?}",
                root.display(),
                manifest.name
            ));
        }
    }

    let mut packages = BTreeMap::new();
    let mut resolver_paths: Vec<(String, String, String)> = Vec::new();
    for (selected_name, manifest) in &selected_manifests {
        let directory_name = manifest
            .dir
            .file_name()
            .and_then(|name| name.to_str())
            .ok_or_else(|| {
                format!(
                    "program registry package directory is not valid UTF-8: {}",
                    manifest.dir.display()
                )
            })?;
        let manifest_path = manifest.dir.join("package.toml");
        if manifest.name != directory_name || &manifest.name != selected_name {
            return Err(format!(
                "{}: package name {:?} does not match registry directory {:?}",
                manifest_path.display(),
                manifest.name,
                directory_name
            ));
        }
        let manifest_sha256 = package_manifest_sha256(&manifest_path)?;
        let identity = identities.get(&manifest.name).ok_or_else(|| {
            format!(
                "{}: package {:?} is not selected by the configured ordered registry roots; generate this index with its owning root first",
                manifest_path.display(),
                manifest.name
            )
        })?;
        if identity.manifest_sha256 != manifest_sha256 {
            return Err(format!(
                "{}: selected package {:?} does not match its authoritative first-hit identity",
                manifest_path.display(),
                manifest.name,
            ));
        }
        if !matches!(manifest.kind, ManifestKind::Program) {
            continue;
        }
        // The kernel is published as a root boot artifact
        // (`binaries/kernel.wasm`), not as an architecture-scoped guest
        // program. It therefore does not belong in the program-mirror
        // projection.
        if manifest.uses_root_binary_mirror() {
            continue;
        }

        let mut members = Vec::new();
        let mut source_artifacts = BTreeSet::new();
        let mut mirror_paths = BTreeSet::new();
        for output in &manifest.program_outputs {
            let mirror_path = portable_projection_path(
                &manifest,
                &manifest.output_dest_rel_for(output),
                "output mirror path",
            )?;
            insert_projection_identity(
                &manifest,
                &output.wasm,
                &mirror_path,
                &mut source_artifacts,
                &mut mirror_paths,
            )?;
            members.push(ProgramPackageProjectionMember {
                kind: "output",
                source_artifact: output.wasm.clone(),
                mirror_path,
                output_name: Some(output.name.clone()),
                fork_instrumentation: Some(output.fork_instrumentation.as_str().to_string()),
                guest_path: None,
                mode: None,
            });
        }
        for runtime_file in &manifest.runtime_files {
            let mirror_path = portable_projection_path(
                &manifest,
                &manifest.runtime_file_dest_rel_for(runtime_file),
                "runtime-file mirror path",
            )?;
            insert_projection_identity(
                &manifest,
                &runtime_file.artifact,
                &mirror_path,
                &mut source_artifacts,
                &mut mirror_paths,
            )?;
            members.push(ProgramPackageProjectionMember {
                kind: "runtime-file",
                source_artifact: runtime_file.artifact.clone(),
                mirror_path,
                output_name: None,
                fork_instrumentation: None,
                guest_path: Some(runtime_file.guest_path.clone()),
                mode: Some(runtime_file.mode),
            });
        }
        if members.is_empty() {
            return Err(format!(
                "{}: program package has no projected members",
                manifest.spec()
            ));
        }
        if members.len() != manifest.program_closure_member_count() {
            return Err(format!(
                "{}: projected member count does not match the manifest closure",
                manifest.spec()
            ));
        }

        let mut cache_keys = BTreeMap::new();
        let mut dependency_closures = BTreeMap::new();
        for arch in &manifest.target_arches {
            cache_keys.insert(
                arch.as_str().to_string(),
                identity.cache_keys[arch.as_str()].clone(),
            );
            dependency_closures.insert(
                arch.as_str().to_string(),
                program_dependency_closure(&manifest, registry, *arch)?,
            );
        }
        let projection = ProgramPackageProjection {
            manifest_sha256,
            arches: manifest
                .target_arches
                .iter()
                .map(|arch| arch.as_str().to_string())
                .collect(),
            cache_keys,
            dependency_closures,
            members,
        };
        for arch in &projection.arches {
            for member in &projection.members {
                for (previous_arch, previous_path, previous_package) in &resolver_paths {
                    if previous_arch == arch
                        && file_paths_conflict(previous_path, &member.mirror_path)
                    {
                        return Err(format!(
                            "{}: resolver paths programs/{}/{} and programs/{}/{} conflict between packages {:?} and {:?}",
                            root.display(),
                            previous_arch,
                            previous_path,
                            arch,
                            member.mirror_path,
                            previous_package,
                            manifest.name
                        ));
                    }
                }
                resolver_paths.push((
                    arch.clone(),
                    member.mirror_path.clone(),
                    manifest.name.clone(),
                ));
            }
        }
        if packages.insert(manifest.name.clone(), projection).is_some() {
            return Err(format!(
                "{}: duplicate program package name {:?}",
                root.display(),
                manifest.name
            ));
        }
    }

    Ok(ProgramPackageIndex {
        format: PROGRAM_PACKAGE_INDEX_FORMAT,
        identities,
        packages,
    })
}

fn program_package_index_for_root(
    root: &Path,
    registry: &Registry,
) -> Result<ProgramPackageIndex, String> {
    let mut after_first = || {};
    program_package_index_for_root_with(root, registry, &mut after_first)
}

/// Build the bounded v2 policy projection for the exact program nodes that a
/// source-only run materialized. This is intentionally separate from the
/// checked-in Default projection: callers supply both the node set and ABI,
/// and every cache identity is computed under SourceOnlyV1.
pub(crate) fn source_only_program_package_index_for_nodes(
    root: &Path,
    registry: &Registry,
    selected_nodes: &BTreeSet<ResolvedDependencyNode>,
    abi_version: u32,
) -> Result<ProgramPackageIndex, String> {
    let canonical_root = std::fs::canonicalize(root)
        .map_err(|error| format!("resolve selected program registry root {}: {error}", root.display()))?;
    let first_existing = registry
        .roots
        .iter()
        .find(|candidate| candidate.exists())
        .ok_or_else(|| format!("{}: no configured program registry root exists", root.display()))?;
    if std::fs::canonicalize(first_existing).map_err(|error| {
        format!("resolve configured program registry root {}: {error}", first_existing.display())
    })? != canonical_root
    {
        return Err(format!(
            "{} is not the highest-priority existing configured registry root {}",
            root.display(),
            first_existing.display()
        ));
    }

    let mut packages = BTreeMap::<String, ProgramPackageProjection>::new();
    let mut required_identities = BTreeSet::new();
    let mut resolver_paths = Vec::<(String, String, String)>::new();
    for node in selected_nodes {
        let manifest = registry.load(&node.package_name)?;
        if !manifest.target_arches.contains(&node.target_arch) {
            return Err(format!(
                "selected source-only node {} ({}) is not declared by {}",
                node.package_name,
                node.target_arch.as_str(),
                manifest.spec()
            ));
        }
        if manifest.kind != ManifestKind::Program || manifest.uses_root_binary_mirror() {
            continue;
        }
        required_identities.insert(manifest.name.clone());
        let dependency_closure = program_dependency_closure_for_policy(
            &manifest,
            registry,
            node.target_arch,
            abi_version,
            ResolvePolicy::SourceOnlyV1,
        )?;
        required_identities.extend(
            dependency_closure
                .iter()
                .map(|identity| identity.package_name.clone()),
        );
        let identity_keys = package_context_cache_keys_for_policy(
            &manifest,
            registry,
            abi_version,
            ResolvePolicy::SourceOnlyV1,
        )?;
        let selected_key = identity_keys
            .get(node.target_arch.as_str())
            .cloned()
            .ok_or_else(|| {
                format!(
                    "{}: source-only v2 identity omitted {}",
                    manifest.spec(),
                    node.target_arch.as_str()
                )
            })?;
        let members = program_projection_members(&manifest)?;
        for member in &members {
            for (previous_arch, previous_path, previous_package) in &resolver_paths {
                if previous_arch == node.target_arch.as_str()
                    && file_paths_conflict(previous_path, &member.mirror_path)
                    && previous_package != &manifest.name
                {
                    return Err(format!(
                        "{}: selected resolver paths programs/{}/{} conflict between packages {:?} and {:?}",
                        root.display(),
                        previous_arch,
                        member.mirror_path,
                        previous_package,
                        manifest.name
                    ));
                }
            }
            resolver_paths.push((
                node.target_arch.as_str().to_string(),
                member.mirror_path.clone(),
                manifest.name.clone(),
            ));
        }
        let manifest_sha256 = stable_package_manifest_sha256(&manifest.dir.join("package.toml"))?;
        let projection = packages
            .entry(manifest.name.clone())
            .or_insert_with(|| ProgramPackageProjection {
                manifest_sha256,
                arches: Vec::new(),
                cache_keys: BTreeMap::new(),
                dependency_closures: BTreeMap::new(),
                members: members.clone(),
            });
        if projection.members != members {
            return Err(format!(
                "{}: selected source-only program members changed across architecture rows",
                manifest.spec()
            ));
        }
        let arch_name = node.target_arch.as_str().to_string();
        if projection.cache_keys.insert(arch_name.clone(), selected_key).is_some()
            || projection
                .dependency_closures
                .insert(arch_name.clone(), dependency_closure)
                .is_some()
        {
            return Err(format!(
                "selected source-only node appears more than once: {} ({})",
                manifest.name, arch_name
            ));
        }
        projection.arches.push(arch_name);
        projection.arches.sort();
    }

    let mut identities = BTreeMap::new();
    for package_name in required_identities {
        let manifest = registry.load(&package_name)?;
        identities.insert(
            package_name,
            ProgramPackageIdentity {
                manifest_sha256: stable_package_manifest_sha256(
                    &manifest.dir.join("package.toml"),
                )?,
                cache_keys: package_context_cache_keys_for_policy(
                    &manifest,
                    registry,
                    abi_version,
                    ResolvePolicy::SourceOnlyV1,
                )?,
            },
        );
    }
    Ok(ProgramPackageIndex {
        format: PROGRAM_PACKAGE_INDEX_FORMAT,
        identities,
        packages,
    })
}

fn program_projection_members(
    manifest: &DepsManifest,
) -> Result<Vec<ProgramPackageProjectionMember>, String> {
    let mut members = Vec::new();
    let mut source_artifacts = BTreeSet::new();
    let mut mirror_paths = BTreeSet::new();
    for output in &manifest.program_outputs {
        let mirror_path = portable_projection_path(
            manifest,
            &manifest.output_dest_rel_for(output),
            "output mirror path",
        )?;
        insert_projection_identity(
            manifest,
            &output.wasm,
            &mirror_path,
            &mut source_artifacts,
            &mut mirror_paths,
        )?;
        members.push(ProgramPackageProjectionMember {
            kind: "output",
            source_artifact: output.wasm.clone(),
            mirror_path,
            output_name: Some(output.name.clone()),
            fork_instrumentation: Some(output.fork_instrumentation.as_str().to_string()),
            guest_path: None,
            mode: None,
        });
    }
    for runtime_file in &manifest.runtime_files {
        let mirror_path = portable_projection_path(
            manifest,
            &manifest.runtime_file_dest_rel_for(runtime_file),
            "runtime-file mirror path",
        )?;
        insert_projection_identity(
            manifest,
            &runtime_file.artifact,
            &mirror_path,
            &mut source_artifacts,
            &mut mirror_paths,
        )?;
        members.push(ProgramPackageProjectionMember {
            kind: "runtime-file",
            source_artifact: runtime_file.artifact.clone(),
            mirror_path,
            output_name: None,
            fork_instrumentation: None,
            guest_path: Some(runtime_file.guest_path.clone()),
            mode: Some(runtime_file.mode),
        });
    }
    if members.is_empty() {
        return Err(format!(
            "{}: program package has no projected members",
            manifest.spec()
        ));
    }
    Ok(members)
}

fn program_package_index_for_root_with<F>(
    root: &Path,
    registry: &Registry,
    after_first: &mut F,
) -> Result<ProgramPackageIndex, String>
where
    F: FnMut(),
{
    let first = program_package_index_for_root_once(root, registry)?;
    let first_snapshot =
        serde_json::to_vec(&first).map_err(|e| format!("snapshot program package index: {e}"))?;
    after_first();
    let second = program_package_index_for_root_once(root, registry)?;
    let second_snapshot = serde_json::to_vec(&second)
        .map_err(|e| format!("resnapshot program package index: {e}"))?;
    if first_snapshot != second_snapshot {
        return Err(format!(
            "{}: package registry changed while generating program-packages.json; retry from one stable registry snapshot",
            root.display(),
        ));
    }
    Ok(second)
}

fn portable_projection_path(
    manifest: &DepsManifest,
    path: &Path,
    field: &str,
) -> Result<String, String> {
    let mut components = Vec::new();
    for component in path.components() {
        match component {
            Component::Normal(value) => {
                let value = value.to_str().ok_or_else(|| {
                    format!(
                        "{}: {field} is not valid UTF-8: {}",
                        manifest.spec(),
                        path.display()
                    )
                })?;
                components.push(value);
            }
            _ => {
                return Err(format!(
                    "{}: {field} must be a normalized relative path: {}",
                    manifest.spec(),
                    path.display()
                ));
            }
        }
    }
    if components.is_empty() {
        return Err(format!("{}: {field} may not be empty", manifest.spec()));
    }
    Ok(components.join("/"))
}

fn insert_projection_identity(
    manifest: &DepsManifest,
    source_artifact: &str,
    mirror_path: &str,
    source_artifacts: &mut BTreeSet<String>,
    mirror_paths: &mut BTreeSet<String>,
) -> Result<(), String> {
    if !source_artifacts.insert(source_artifact.to_string()) {
        return Err(format!(
            "{}: declared source artifact {:?} appears more than once in the program closure",
            manifest.spec(),
            source_artifact
        ));
    }
    if !mirror_paths.insert(mirror_path.to_string()) {
        return Err(format!(
            "{}: resolver mirror path {:?} appears more than once in the program closure",
            manifest.spec(),
            mirror_path
        ));
    }
    Ok(())
}

fn serialize_program_package_index(root: &Path, registry: &Registry) -> Result<String, String> {
    let mut json = serde_json::to_string_pretty(&program_package_index_for_root(root, registry)?)
        .map_err(|e| format!("serialize program package index: {e}"))?;
    json.push('\n');
    Ok(json)
}

fn cmd_program_package_index(
    root: &Path,
    output: &Path,
    registry: &Registry,
) -> Result<(), String> {
    let json = serialize_program_package_index(root, registry)?;
    let mut refresh_source =
        || serialize_program_package_index(root, registry).map(String::into_bytes);
    let mut replace = |from: &Path, to: &Path| std::fs::rename(from, to);
    write_program_package_index_atomically_with_source(
        output,
        json.as_bytes(),
        &mut refresh_source,
        &mut replace,
    )
}

#[cfg(test)]
fn write_program_package_index_atomically(output: &Path, bytes: &[u8]) -> Result<(), String> {
    let expected = bytes.to_vec();
    let mut refresh_source = || Ok(expected.clone());
    let mut replace = |from: &Path, to: &Path| std::fs::rename(from, to);
    write_program_package_index_atomically_with_source(
        output,
        bytes,
        &mut refresh_source,
        &mut replace,
    )
}

#[cfg(test)]
fn write_program_package_index_atomically_with<F>(
    output: &Path,
    bytes: &[u8],
    replace: &mut F,
) -> Result<(), String>
where
    F: FnMut(&Path, &Path) -> std::io::Result<()>,
{
    let expected = bytes.to_vec();
    let mut refresh_source = || Ok(expected.clone());
    write_program_package_index_atomically_with_source(output, bytes, &mut refresh_source, replace)
}

fn write_program_package_index_atomically_with_source<F, R>(
    output: &Path,
    bytes: &[u8],
    refresh_source: &mut R,
    replace: &mut F,
) -> Result<(), String>
where
    F: FnMut(&Path, &Path) -> std::io::Result<()>,
    R: FnMut() -> Result<Vec<u8>, String>,
{
    let parent = output
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."));
    let parent = canonical_real_directory(parent, "program package index parent")?;
    let file_name = output.file_name().ok_or_else(|| {
        format!(
            "program package index path has no file name: {}",
            output.display()
        )
    })?;
    let output = parent.join(file_name);
    let target_snapshot = inspect_program_package_index_target(&output)?;
    let existing_permissions = target_snapshot.permissions.clone();
    let (transaction_root, stage, mut stage_file, stage_identity) =
        reserve_program_package_index_transaction(&parent, file_name)?;

    let publish = (|| {
        std::io::Write::write_all(&mut stage_file, bytes).map_err(|e| {
            format!(
                "write staged program package index {}: {e}",
                stage.display()
            )
        })?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let permissions = existing_permissions
                .clone()
                .unwrap_or_else(|| std::fs::Permissions::from_mode(0o644));
            std::fs::set_permissions(&stage, permissions).map_err(|e| {
                format!(
                    "set staged program package index permissions {}: {e}",
                    stage.display()
                )
            })?;
        }
        #[cfg(not(unix))]
        if let Some(permissions) = existing_permissions.clone() {
            std::fs::set_permissions(&stage, permissions).map_err(|e| {
                format!(
                    "set staged program package index permissions {}: {e}",
                    stage.display()
                )
            })?;
        }
        stage_file
            .sync_all()
            .map_err(|e| format!("sync staged program package index {}: {e}", stage.display()))?;
        drop(stage_file);

        // The target snapshot check and overwriting rename are not a compare-
        // and-swap by themselves: another generator could replace the target
        // after validation and then be overwritten by this writer. All xtask
        // index publishers coordinate through one durable lock inode. Keep the
        // lock through source refresh, target validation, replacement, and the
        // parent-directory sync so an older cooperating writer can never land
        // after a newer one in that gap.
        let _publication_lock = lock_program_package_index_publication(&parent, file_name)?;

        // Recompute the complete registry projection at the publication
        // boundary. A writer that staged an older registry snapshot must not
        // overwrite an index generated after the recipe graph changed.
        let refreshed = refresh_source()
            .map_err(|e| format!("refresh program package index before publication: {e}"))?;
        if refreshed != bytes {
            return Err(
                "package registry changed after the program package index was staged; retry"
                    .to_string(),
            );
        }

        // Refuse when another writer changed the old target after our initial
        // snapshot. This is a cooperative compare-and-swap boundary: writers
        // over unchanged source stage byte-identical content, while stale
        // writers fail either this check or the source refresh above.
        validate_program_package_index_target_snapshot(&output, &target_snapshot)?;
        replace(&stage, &output).map_err(|e| {
            format!(
                "atomically publish program package index {} -> {}: {e}",
                stage.display(),
                output.display()
            )
        })?;

        #[cfg(unix)]
        std::fs::File::open(&parent)
            .and_then(|directory| directory.sync_all())
            .map_err(|e| {
                format!(
                    "sync program package index parent {}: {e}",
                    parent.display()
                )
            })?;
        std::fs::remove_dir(&transaction_root).map_err(|e| {
            format!(
                "remove empty program package index transaction {}: {e}",
                transaction_root.display()
            )
        })
    })();

    if let Err(error) = publish {
        let cleanup =
            cleanup_program_package_index_transaction(&transaction_root, &stage, &stage_identity);
        return match cleanup {
            Ok(()) => Err(error),
            Err(cleanup_error) => Err(format!(
                "{error}; additionally failed to clean private index transaction: {cleanup_error}"
            )),
        };
    }
    Ok(())
}

fn program_package_index_lock_path(parent: &Path, file_name: &std::ffi::OsStr) -> PathBuf {
    let mut lock_name = std::ffi::OsString::from(".");
    lock_name.push(file_name);
    lock_name.push(".kandelo-index.lock");
    parent.join(lock_name)
}

fn lock_program_package_index_publication(
    parent: &Path,
    file_name: &std::ffi::OsStr,
) -> Result<std::fs::File, String> {
    let lock_path = program_package_index_lock_path(parent, file_name);
    let mut options = std::fs::OpenOptions::new();
    options.read(true).write(true).create(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(0o600);
    }
    let lock = options.open(&lock_path).map_err(|e| {
        format!(
            "open program package index publication lock {}: {e}",
            lock_path.display()
        )
    })?;
    lock.lock().map_err(|e| {
        format!(
            "lock program package index publication {}: {e}",
            lock_path.display()
        )
    })?;

    let opened_metadata = lock.metadata().map_err(|e| {
        format!(
            "inspect opened program package index publication lock {}: {e}",
            lock_path.display()
        )
    })?;
    let path_metadata = std::fs::symlink_metadata(&lock_path).map_err(|e| {
        format!(
            "inspect program package index publication lock path {}: {e}",
            lock_path.display()
        )
    })?;
    if !opened_metadata.is_file()
        || opened_metadata.file_type().is_symlink()
        || opened_metadata.len() != 0
        || !path_metadata.is_file()
        || path_metadata.file_type().is_symlink()
        || path_metadata.len() != 0
        || package_mirror_identity(&opened_metadata)? != package_mirror_identity(&path_metadata)?
    {
        let _ = lock.unlock();
        return Err(format!(
            "program package index publication lock must remain one empty regular non-symlink file: {}",
            lock_path.display()
        ));
    }
    Ok(lock)
}

#[cfg(unix)]
fn projection_lock_has_exact_mode(metadata: &std::fs::Metadata) -> bool {
    use std::os::unix::fs::PermissionsExt;
    metadata.permissions().mode() & 0o7777 == 0o600
}

#[cfg(not(unix))]
fn projection_lock_has_exact_mode(_metadata: &std::fs::Metadata) -> bool {
    false
}

struct ProgramPackageIndexTargetSnapshot {
    entry: Option<LocalMirrorEntrySnapshot>,
    permissions: Option<std::fs::Permissions>,
}

fn inspect_program_package_index_target(
    output: &Path,
) -> Result<ProgramPackageIndexTargetSnapshot, String> {
    match std::fs::symlink_metadata(output) {
        Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_file() => Err(format!(
            "refusing to replace non-regular program package index: {}",
            output.display()
        )),
        Ok(metadata) => {
            let identity = package_mirror_identity(&metadata)?;
            let entry = inspect_local_mirror_entry(output)?;
            if entry.identity != identity
                || !matches!(&entry.kind, LocalMirrorEntryKind::Regular { .. })
            {
                return Err(format!(
                    "program package index changed while it was inspected: {}",
                    output.display()
                ));
            }
            Ok(ProgramPackageIndexTargetSnapshot {
                entry: Some(entry),
                permissions: Some(metadata.permissions()),
            })
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            Ok(ProgramPackageIndexTargetSnapshot {
                entry: None,
                permissions: None,
            })
        }
        Err(e) => Err(format!(
            "inspect program package index {}: {e}",
            output.display()
        )),
    }
}

fn validate_program_package_index_target_snapshot(
    output: &Path,
    expected: &ProgramPackageIndexTargetSnapshot,
) -> Result<(), String> {
    match &expected.entry {
        Some(entry) => validate_local_mirror_entry(output, entry)
            .map_err(|e| format!("program package index target changed before publication: {e}")),
        None if path_entry_exists(output)? => Err(format!(
            "program package index target appeared before publication: {}",
            output.display()
        )),
        None => Ok(()),
    }
}

fn reserve_program_package_index_transaction(
    parent: &Path,
    file_name: &std::ffi::OsStr,
) -> Result<(PathBuf, PathBuf, std::fs::File, PackageMirrorIdentity), String> {
    for _ in 0..1024 {
        let sequence = MIRROR_TRANSACTION_COUNTER.fetch_add(1, Ordering::Relaxed);
        let transaction_root = parent.join(format!(
            ".{}.index-transaction-{}-{sequence}",
            file_name.to_string_lossy(),
            std::process::id()
        ));
        match create_private_transaction_directory(&transaction_root) {
            Ok(()) => {
                let stage = transaction_root.join("index");
                match std::fs::OpenOptions::new()
                    .write(true)
                    .create_new(true)
                    .open(&stage)
                {
                    Ok(file) => {
                        let metadata = file.metadata().map_err(|e| {
                            format!(
                                "inspect staged program package index {}: {e}",
                                stage.display()
                            )
                        })?;
                        let identity = package_mirror_identity(&metadata)?;
                        return Ok((transaction_root, stage, file, identity));
                    }
                    Err(e) => {
                        let _ = std::fs::remove_dir(&transaction_root);
                        return Err(format!(
                            "create staged program package index {}: {e}",
                            stage.display()
                        ));
                    }
                }
            }
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(e) => {
                return Err(format!(
                    "reserve program package index transaction {}: {e}",
                    transaction_root.display()
                ));
            }
        }
    }
    Err(format!(
        "could not allocate a unique program package index transaction below {}",
        parent.display()
    ))
}

fn cleanup_program_package_index_transaction(
    transaction_root: &Path,
    stage: &Path,
    expected_identity: &PackageMirrorIdentity,
) -> Result<(), String> {
    match std::fs::symlink_metadata(stage) {
        Ok(metadata)
            if metadata.is_file()
                && !metadata.file_type().is_symlink()
                && &package_mirror_identity(&metadata)? == expected_identity =>
        {
            std::fs::remove_file(stage).map_err(|e| {
                format!(
                    "remove staged program package index {}: {e}",
                    stage.display()
                )
            })?;
        }
        Ok(_) => {
            return Err(format!(
                "refusing to remove changed staged program package index {}",
                stage.display()
            ));
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
        Err(e) => {
            return Err(format!(
                "inspect staged program package index {}: {e}",
                stage.display()
            ));
        }
    }
    match std::fs::remove_dir(transaction_root) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(e) => Err(format!(
            "remove program package index transaction {}: {e}",
            transaction_root.display()
        )),
    }
}

fn cmd_check_program_package_index(
    root: &Path,
    index: &Path,
    registry: &Registry,
) -> Result<(), String> {
    let expected = serialize_program_package_index(root, registry)?;
    let actual = std::fs::read_to_string(index)
        .map_err(|e| format!("read program package index {}: {e}", index.display()))?;
    if actual != expected {
        return Err(format!(
            "{} is stale; regenerate it with `cargo run -p xtask -- build-deps program-index --source-repo-root {} {} {}`",
            index.display(),
            repo_root().display(),
            root.display(),
            index.display()
        ));
    }
    Ok(())
}

/// Validate every program-package projection in the same ordered suffix
/// context that owns it.
///
/// A source resolver needs a complete projection for each existing configured
/// registry root: when a higher-priority external root disappears, the next
/// root becomes authoritative. The broader `build-deps check` command retains
/// its historical behavior of validating indexes that are present, while the
/// runtime boundary uses `require_every_index = true` so an absent projection
/// cannot silently disable exact source-freshness validation.
fn check_program_package_indexes_in_context(
    registry: &Registry,
    require_every_index: bool,
) -> Result<(), String> {
    for (root_index, root) in registry.roots.iter().enumerate() {
        let root_metadata = match std::fs::metadata(root) {
            Ok(metadata) => metadata,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
            Err(error) => {
                return Err(format!(
                    "inspect configured package registry root {}: {error}",
                    root.display()
                ));
            }
        };
        if !root_metadata.is_dir() {
            return Err(format!(
                "configured package registry root is not a directory: {}",
                root.display()
            ));
        }

        let index = root.join("program-packages.json");
        if !index.is_file() {
            if require_every_index {
                return Err(format!(
                    "configured package registry root {} is missing {}; generate it in its ordered registry context before resolving source packages",
                    root.display(),
                    index.display()
                ));
            }
            continue;
        }

        // Each physical root owns an index for the ordered registry context
        // beginning at that root. Higher-priority roots may add identities for
        // the complete combined context, but must not make a lower root's
        // committed suffix-context index appear stale.
        let suffix_registry = Registry {
            roots: registry.roots[root_index..].to_vec(),
        };
        cmd_check_program_package_index(root, &index, &suffix_registry)?;
    }
    Ok(())
}

/// Ensure every program-package projection is present and current in its
/// ordered suffix context by regenerating it when missing or drifted.
///
/// The derived counterpart to `check_program_package_indexes_in_context`. The
/// program index is a generated artifact (gitignored), not a committed one, so
/// there is no baseline for it to be "stale" against: a source build or source
/// resolver keeps it fresh by writing it from the authenticated source registry
/// rather than failing. Each physical root owns the index for the ordered
/// registry context beginning at that root, exactly as the check variant
/// validates. Writes only when the freshly serialized projection differs from
/// what is on disk, so an already-current index is left untouched (no mtime
/// churn that would disturb source-build content caches).
pub(crate) fn ensure_program_package_indexes_in_context(
    registry: &Registry,
) -> Result<(), String> {
    for (root_index, root) in registry.roots.iter().enumerate() {
        let root_metadata = match std::fs::metadata(root) {
            Ok(metadata) => metadata,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
            Err(error) => {
                return Err(format!(
                    "inspect configured package registry root {}: {error}",
                    root.display()
                ));
            }
        };
        if !root_metadata.is_dir() {
            return Err(format!(
                "configured package registry root is not a directory: {}",
                root.display()
            ));
        }

        let index = root.join("program-packages.json");
        let suffix_registry = Registry {
            roots: registry.roots[root_index..].to_vec(),
        };
        let expected = serialize_program_package_index(root, &suffix_registry)?;
        let current = std::fs::read_to_string(&index).ok();
        if current.as_deref() != Some(expected.as_str()) {
            cmd_program_package_index(root, &index, &suffix_registry)?;
        }
    }
    Ok(())
}

fn parse_selected_program_package_names(value: &str) -> Result<Vec<String>, String> {
    if value.is_empty() {
        return Err("selected program package list may not be empty".to_string());
    }
    let mut selected = Vec::new();
    let mut seen = BTreeSet::new();
    for name in value.split(',') {
        let mut bytes = name.bytes();
        let valid = bytes
            .next()
            .is_some_and(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit())
            && bytes.all(|byte| {
                byte.is_ascii_lowercase()
                    || byte.is_ascii_digit()
                    || matches!(byte, b'.' | b'_' | b'-')
            });
        if !valid {
            return Err(format!(
                "selected program package list contains an invalid package name: {name:?}"
            ));
        }
        if !seen.insert(name.to_string()) {
            return Err(format!(
                "selected program package list repeats package {name:?}"
            ));
        }
        selected.push(name.to_string());
    }
    Ok(selected)
}

/// Project only the program-package closure a sealed consumer will materialize.
///
/// The checked-in index is the repository-wide policy and must remain fresh,
/// but the isolated Formula-test runtime does not need authority over all of
/// it. A Formula test must bind every package it fetches, and every identity
/// named by those packages' dependency closures, to the exact current source
/// checkout. Emitting this bounded projection preserves that fail-closed
/// boundary while giving the sealed runtime only the policy it consumes.
fn selected_program_package_index_for_root(
    root: &Path,
    registry: &Registry,
    selected: &[String],
) -> Result<ProgramPackageIndex, String> {
    let complete = program_package_index_for_root(root, registry)?;
    let mut packages = BTreeMap::new();
    let mut required_identities = BTreeSet::new();
    for package_name in selected {
        let projection = complete.packages.get(package_name).ok_or_else(|| {
            format!(
                "selected Formula-test package {package_name:?} is not a projected program package"
            )
        })?;
        packages.insert(package_name.clone(), projection.clone());
        required_identities.insert(package_name.clone());
        for closure in projection.dependency_closures.values() {
            required_identities
                .extend(closure.iter().map(|identity| identity.package_name.clone()));
        }
    }
    let mut identities = BTreeMap::new();
    for package_name in required_identities {
        let identity = complete.identities.get(&package_name).ok_or_else(|| {
            format!("selected Formula-test closure lacks contextual identity {package_name:?}")
        })?;
        identities.insert(package_name, identity.clone());
    }
    Ok(ProgramPackageIndex {
        format: PROGRAM_PACKAGE_INDEX_FORMAT,
        identities,
        packages,
    })
}

fn serialize_selected_program_package_index(
    root: &Path,
    registry: &Registry,
    selected: &[String],
) -> Result<String, String> {
    let mut json = serde_json::to_string_pretty(&selected_program_package_index_for_root(
        root, registry, selected,
    )?)
    .map_err(|error| format!("serialize selected program package index: {error}"))?;
    json.push('\n');
    Ok(json)
}

fn cmd_selected_program_package_index(
    output: &Path,
    registry: &Registry,
    selected: &[String],
) -> Result<(), String> {
    let root = registry
        .roots
        .iter()
        .find_map(|root| match std::fs::metadata(root) {
            Ok(metadata) => Some(Ok((root, metadata))),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => None,
            Err(error) => Some(Err(format!(
                "inspect configured package registry root {}: {error}",
                root.display()
            ))),
        })
        .transpose()?
        .ok_or_else(|| "no configured program registry root exists".to_string())?;
    if !root.1.is_dir() {
        return Err(format!(
            "configured program registry root is not a directory: {}",
            root.0.display()
        ));
    }
    let json = serialize_selected_program_package_index(root.0, registry, selected)?;
    let mut refresh_source = || {
        serialize_selected_program_package_index(root.0, registry, selected).map(String::into_bytes)
    };
    let mut replace = |from: &Path, to: &Path| std::fs::rename(from, to);
    write_program_package_index_atomically_with_source(
        output,
        json.as_bytes(),
        &mut refresh_source,
        &mut replace,
    )
}

/// Subset of [`Registry::walk_all`] containing only `kind = "program"`
/// manifests. Used by `bundle-program` and `archive-stage` to look
/// up source + license decoration for release artifacts.
pub fn programs_by_name(registry: &Registry) -> Result<BTreeMap<String, DepsManifest>, String> {
    Ok(registry
        .walk_all()?
        .into_iter()
        .filter(|(_, m)| matches!(m.kind, ManifestKind::Program))
        .collect())
}

fn expand_tilde(s: &str) -> PathBuf {
    if let Some(rest) = s.strip_prefix("~/") {
        if let Some(home) = std::env::var_os("HOME") {
            return PathBuf::from(home).join(rest);
        }
    }
    PathBuf::from(s)
}

fn resolve_registry_root(repo: &Path, value: &str) -> PathBuf {
    let expanded = expand_tilde(value);
    if expanded.is_absolute() {
        expanded
    } else {
        repo.join(expanded)
    }
}

/// Cache-key sha for a manifest. Recursively hashes transitive deps
/// so any change in the tree invalidates every downstream consumer.
/// The hash domain and inputs differ by manifest kind:
///
/// Library / program kind (arch- and ABI-specific artifacts):
///   domain `"wasm-posix-pkg\n"`, then
///   `name`, `version`, `revision`, `target_arch`, `abi_version`,
///   `source.url`, `source.sha256`, declared build input content
///   digests, global package build/toolchain content digests, optional
///   fork-instrument tool content digests for program outputs that use
///   that post-processor, then for each dep (sorted by name):
///   `dep.name`, `dep.version`, hex(dep_sha).
///
/// Source kind (raw upstream archive, arch- and ABI-agnostic):
///   domain `"wasm-posix-pkg-source\n"`, then
///   `name`, `version`, `revision`, `source.url`, `source.sha256`,
///   declared build input content digests, then the same per-dep
///   tail. `target_arch` and `abi_version` are intentionally omitted
///   — a source tarball does not change when the kernel ABI bumps or
///   when we cross-compile for a new arch.
///
/// ABI-bump propagation: a kernel ABI bump shifts every library and
/// program leaf sha (because `abi_version` is in their input set),
/// and those shifts ripple up to their consumers via the per-dep
/// `hex(dep_sha)` tail. Source-kind leaf shas stay stable, but a
/// library or program that consumes a source-kind dep still
/// invalidates correctly because its own `abi_version` input changes.
///
/// Note: the `abi_version` parameter here is the **consumer's** target
/// ABI. Archives separately advertise a `Vec<u32>` of compatible ABIs
/// via `[compatibility].abi_versions`; Task A.9 verifies the
/// consumer's value is in that set during remote-fetch.
///
/// Cycle detection via `chain`: a manifest may not transitively
/// depend on itself.
pub fn compute_sha(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    abi_version: u32,
    memo: &mut BTreeMap<String, [u8; 32]>,
    chain: &mut Vec<String>,
) -> Result<[u8; 32], String> {
    compute_sha_for_policy(
        target,
        registry,
        arch,
        abi_version,
        ResolvePolicy::Default,
        memo,
        chain,
    )
}

pub(crate) fn compute_sha_for_policy(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    abi_version: u32,
    policy: ResolvePolicy,
    memo: &mut BTreeMap<String, [u8; 32]>,
    chain: &mut Vec<String>,
) -> Result<[u8; 32], String> {
    compute_sha_with_global_toolchain_inputs_for_policy(
        target,
        registry,
        arch,
        abi_version,
        policy,
        memo,
        chain,
        None,
    )
}

fn compute_sha_with_global_toolchain_inputs(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    abi_version: u32,
    memo: &mut BTreeMap<String, [u8; 32]>,
    chain: &mut Vec<String>,
    global_toolchain_inputs_override: Option<&[BuildInputDigest]>,
) -> Result<[u8; 32], String> {
    compute_sha_with_global_toolchain_inputs_for_policy(
        target,
        registry,
        arch,
        abi_version,
        ResolvePolicy::Default,
        memo,
        chain,
        global_toolchain_inputs_override,
    )
}

fn compute_sha_with_global_toolchain_inputs_for_policy(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    abi_version: u32,
    policy: ResolvePolicy,
    memo: &mut BTreeMap<String, [u8; 32]>,
    chain: &mut Vec<String>,
    global_toolchain_inputs_override: Option<&[BuildInputDigest]>,
) -> Result<[u8; 32], String> {
    let main_repo_root = repo_root();
    compute_sha_with_identity_context(
        target,
        registry,
        arch,
        abi_version,
        policy,
        memo,
        chain,
        global_toolchain_inputs_override,
        &main_repo_root,
        None,
    )
}

fn compute_sha_with_identity_context(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    abi_version: u32,
    policy: ResolvePolicy,
    memo: &mut BTreeMap<String, [u8; 32]>,
    chain: &mut Vec<String>,
    global_toolchain_inputs_override: Option<&[BuildInputDigest]>,
    main_repo_root: &Path,
    fork_instrument_tool_inputs_override: Option<&[BuildInputDigest]>,
) -> Result<[u8; 32], String> {
    compute_sha_with_identity_context_for_platform(
        target,
        registry,
        arch,
        abi_version,
        policy,
        memo,
        chain,
        global_toolchain_inputs_override,
        main_repo_root,
        fork_instrument_tool_inputs_override,
        cfg!(unix),
    )
}

fn compute_sha_with_identity_context_for_platform(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    abi_version: u32,
    policy: ResolvePolicy,
    memo: &mut BTreeMap<String, [u8; 32]>,
    chain: &mut Vec<String>,
    global_toolchain_inputs_override: Option<&[BuildInputDigest]>,
    main_repo_root: &Path,
    fork_instrument_tool_inputs_override: Option<&[BuildInputDigest]>,
    is_unix: bool,
) -> Result<[u8; 32], String> {
    source_only_strict_input_platform(policy, target.source.provider, is_unix)?;

    if chain.iter().any(|s| s == &target.name) {
        return Err(format!(
            "cycle in dep graph: {} -> {}",
            chain.join(" -> "),
            target.name
        ));
    }
    // Memo key MUST include arch + abi: a single resolve chain can
    // legitimately need the same package at multiple arches (e.g. a
    // wasm64 program that transitively pulls a wasm32-only sibling
    // via the wasm32-fallback path) and at multiple ABIs (rare today
    // but the field is part of the sha input). Without these, a
    // memo'd wasm64 sha bleeds into a later wasm32 lookup, producing
    // a canonical cache path with wasm32 in the dir but the wasm64
    // sha in the suffix — which then can't possibly be satisfied by
    // either archive.
    let memo_key = format!(
        "{}|{}|{}|{:?}",
        target.spec(),
        arch.as_str(),
        abi_version,
        policy
    );
    if let Some(cached) = memo.get(&memo_key) {
        return Ok(*cached);
    }

    chain.push(target.name.clone());

    // Resolve deps first; sort by name so iteration order is stable.
    let mut dep_shas: Vec<(DepRef, [u8; 32])> = Vec::with_capacity(target.depends_on.len());
    for dref in &target.depends_on {
        let child = registry.load(&dref.name)?;
        if child.version != dref.version {
            return Err(format!(
                "{} depends on {}@{}, but registry has {}",
                target.spec(),
                dref.name,
                dref.version,
                child.spec()
            ));
        }
        let child_sha = compute_sha_with_identity_context_for_platform(
            &child,
            registry,
            arch,
            abi_version,
            policy,
            memo,
            chain,
            global_toolchain_inputs_override,
            main_repo_root,
            fork_instrument_tool_inputs_override,
            is_unix,
        )?;
        dep_shas.push((dref.clone(), child_sha));
    }
    dep_shas.sort_by(|a, b| a.0.name.cmp(&b.0.name));

    chain.pop();

    let build_inputs = build_input_digests_from_repo(target, registry, main_repo_root, policy)?;
    let global_toolchain_inputs = match target.kind {
        ManifestKind::Library | ManifestKind::Program => match global_toolchain_inputs_override {
            Some(inputs) => inputs.to_vec(),
            None => global_package_toolchain_digests()?,
        },
        ManifestKind::Source => Vec::new(),
    };
    let fork_instrument_tool_inputs = if package_uses_fork_instrument_tool(target) {
        match fork_instrument_tool_inputs_override {
            Some(inputs) => inputs.to_vec(),
            None => fork_instrument_tool_digests()?,
        }
    } else {
        Vec::new()
    };

    let mut h = Sha256::new();
    if let Some(domain_separator) = policy.domain_separator() {
        h.update(domain_separator);
    }
    if policy == ResolvePolicy::SourceOnlyV1 {
        h.update(b"kandelo-source-provider-v1\0");
        h.update(target.source.provider.as_str().as_bytes());
        h.update(b"\0");
        if target.source.provider == SourceProvider::DevShell {
            h.update(dev_shell_source_identity(target)?);
        }
        if target.source.provider == SourceProvider::Archive
            && !target.source.extract_exclude_members.is_empty()
        {
            h.update(b"kandelo-source-extract-exclusions-v1\0");
            h.update(
                u64::try_from(target.source.extract_exclude_members.len())
                    .map_err(|_| "too many source extraction exclusions".to_string())?
                    .to_le_bytes(),
            );
            for member in &target.source.extract_exclude_members {
                h.update(
                    u64::try_from(member.len())
                        .map_err(|_| "source extraction exclusion is too long".to_string())?
                        .to_le_bytes(),
                );
                h.update(member.as_bytes());
            }
        }
    }
    match target.kind {
        ManifestKind::Source => {
            h.update(b"wasm-posix-pkg-source\n");
            h.update(target.name.as_bytes());
            h.update(b"\n");
            h.update(target.version.as_bytes());
            h.update(b"\n");
            h.update(target.revision.to_le_bytes());
            h.update(b"\n");
            // No target_arch, no abi_version — sources are arch/ABI-agnostic.
            h.update(target.source.url.as_bytes());
            h.update(b"\n");
            h.update(target.source.sha256.as_bytes());
            h.update(b"\n");
        }
        ManifestKind::Library | ManifestKind::Program => {
            h.update(b"wasm-posix-pkg\n");
            h.update(target.name.as_bytes());
            h.update(b"\n");
            h.update(target.version.as_bytes());
            h.update(b"\n");
            h.update(target.revision.to_le_bytes());
            h.update(b"\n");
            h.update(arch.as_str().as_bytes());
            h.update(b"\n");
            h.update(abi_version.to_le_bytes());
            h.update(b"\n");
            h.update(target.source.url.as_bytes());
            h.update(b"\n");
            h.update(target.source.sha256.as_bytes());
            h.update(b"\n");
            // Fold in declared outputs so changing what a build is
            // expected to produce invalidates the cache. Without this,
            // renaming a program's `wasm = "..."` (or any library
            // libs/headers/pkgconfig/files path) leaves cache_key_sha
            // unchanged — the resolver then serves a canonical
            // directory that doesn't match the new declaration and
            // archive-stage packs broken archives. Bug discovered in
            // PR #384 (lamp.vfs → lamp.vfs.zst).
            //
            // Ordering: hashed in authored Vec order (no sort). That
            // matches how consumers like `mirror_program_outputs`
            // iterate, and re-ordering is a real semantic change
            // worth invalidating on. `b"|"` separators keep
            // adjacent strings unambiguous (e.g. lib `"a"` + `"bc"` ≠
            // lib `"ab"` + `"c"`). A section tag (`"libs:"`, etc.)
            // before each list prevents cross-section collisions.
            h.update(b"outputs.libs:\n");
            for s in &target.outputs.libs {
                h.update(s.as_bytes());
                h.update(b"|");
            }
            h.update(b"\n");
            h.update(b"outputs.headers:\n");
            for s in &target.outputs.headers {
                h.update(s.as_bytes());
                h.update(b"|");
            }
            h.update(b"\n");
            h.update(b"outputs.pkgconfig:\n");
            for s in &target.outputs.pkgconfig {
                h.update(s.as_bytes());
                h.update(b"|");
            }
            h.update(b"\n");
            // Preserve every existing package's cache key: the additive files
            // field participates only when authored. A universally empty
            // section would invalidate the entire package registry merely for
            // learning a new output kind.
            if !target.outputs.files.is_empty() {
                h.update(b"outputs.files:v1\n");
                for s in &target.outputs.files {
                    h.update((s.len() as u64).to_le_bytes());
                    h.update(s.as_bytes());
                }
            }
            h.update(b"program_outputs:\n");
            for out in &target.program_outputs {
                h.update(out.name.as_bytes());
                h.update(b"|");
                h.update(out.wasm.as_bytes());
                if out.fork_instrumentation != ForkInstrumentationPolicy::Auto {
                    h.update(b"|fork_instrumentation=");
                    h.update(out.fork_instrumentation.as_str().as_bytes());
                }
                h.update(b"\n");
            }
            // Additive program runtime closure. Keep the section absent for
            // existing manifests so learning this schema does not invalidate
            // every historical package cache key.
            if !target.runtime_files.is_empty() {
                h.update(b"runtime_files:v1\n");
                for runtime_file in &target.runtime_files {
                    for field in [
                        runtime_file.artifact.as_bytes(),
                        runtime_file.guest_path.as_bytes(),
                    ] {
                        h.update((field.len() as u64).to_le_bytes());
                        h.update(field);
                    }
                    h.update(runtime_file.mode.to_le_bytes());
                }
            }
        }
    }
    if !build_inputs.is_empty() {
        h.update(b"build-inputs:\n");
        for input in &build_inputs {
            h.update(input.label.as_bytes());
            h.update(b"\n");
            h.update(input.digest);
            h.update(b"\n");
        }
    }
    if !global_toolchain_inputs.is_empty() {
        h.update(b"global-toolchain-inputs:\n");
        for input in &global_toolchain_inputs {
            h.update(input.label.as_bytes());
            h.update(b"\n");
            h.update(input.digest);
            h.update(b"\n");
        }
    }
    if !fork_instrument_tool_inputs.is_empty() {
        h.update(b"fork-instrument-tool-inputs:\n");
        for input in &fork_instrument_tool_inputs {
            h.update(input.label.as_bytes());
            h.update(b"\n");
            h.update(input.digest);
            h.update(b"\n");
        }
    }
    if policy == ResolvePolicy::SourceOnlyV1
        && matches!(target.kind, ManifestKind::Library | ManifestKind::Program)
    {
        let abi_contract = crate::local_abi_identity::local_abi_contract_digest(
            main_repo_root,
            abi_version,
        )?;
        h.update(b"local-abi-contract:v1\0");
        h.update(abi_contract);
    }
    for (dref, dsha) in &dep_shas {
        h.update(dref.name.as_bytes());
        h.update(b"@");
        h.update(dref.version.as_bytes());
        h.update(b":");
        h.update(hex(dsha).as_bytes());
        h.update(b"\n");
    }

    let out: [u8; 32] = h.finalize().into();
    memo.insert(memo_key, out);
    Ok(out)
}

#[derive(Clone, Debug)]
struct BuildInputDigest {
    label: String,
    digest: [u8; 32],
}

const GLOBAL_PACKAGE_TOOLCHAIN_INPUTS: &[&str] = &[
    "flake.nix",
    "flake.lock",
    "rust-toolchain.toml",
    "scripts/dev-shell.sh",
    "scripts/run-local-build.sh",
    "scripts/install-local-binary.sh",
    "scripts/wasm-artifact-guards.sh",
    "scripts/build-musl.sh",
    "scripts/install-overlay-headers.sh",
    ".github/actions/package-archive-build",
    ".github/actions/package-toolchain",
    ".github/actions/fetch-submodules",
    ".github/actions/download-run-artifacts",
    "libc/glue",
    "libc/musl-overlay",
    "libc/musl",
    "sdk/activate.sh",
    "sdk/bin",
    "sdk/config.site",
    "sdk/package.json",
    "sdk/package-lock.json",
    "sdk/src",
];

/// The full input closure of the wasm-fork-instrument tool: the crate's
/// cargo-derived workspace source closure (crates/fork-instrument, its
/// workspace path-deps, and .cargo/config.toml) plus the explicit non-crate
/// tail. Single source of truth shared by the cache-key digest and the
/// drift-guard test that keeps scripts/fork-instrument-tool-input-hash.sh
/// from silently diverging. The tail is genuinely non-crate (lockfile/manifest/
/// toolchain + the build/run/hash harness scripts) and cannot be derived from
/// cargo.
fn fork_instrument_tool_input_paths(root: &Path) -> Result<Vec<String>, String> {
    let mut paths = crate::cargo_closure::cargo_closure_paths(root, "fork-instrument")?;
    for tail in [
        "Cargo.toml",
        "Cargo.lock",
        "rust-toolchain.toml",
        "scripts/build-fork-instrument-tool.sh",
        "scripts/run-wasm-fork-instrument.sh",
        "scripts/fork-instrument-tool-input-hash.sh",
    ] {
        paths.push(tail.to_string());
    }
    paths.sort();
    paths.dedup();
    Ok(paths)
}

type RootDigestCache = OnceLock<Mutex<BTreeMap<PathBuf, Result<Vec<BuildInputDigest>, String>>>>;

static GLOBAL_PACKAGE_TOOLCHAIN_DIGESTS: RootDigestCache = OnceLock::new();
static FORK_INSTRUMENT_TOOL_DIGESTS: RootDigestCache = OnceLock::new();

fn root_scoped_build_input_digests(
    cache: &RootDigestCache,
    root: &Path,
    compute: impl FnOnce(&Path) -> Result<Vec<BuildInputDigest>, String>,
) -> Result<Vec<BuildInputDigest>, String> {
    // WHY: a rootless OnceLock could reuse compile-checkout digests after the
    // command selects a different protected alias. Same-path memoization is
    // safe at the publisher boundary because the alias is read-only and each
    // checker invocation is a fresh process.
    let cached = cache.get_or_init(|| Mutex::new(BTreeMap::new()));
    if let Some(result) = cached
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .get(root)
        .cloned()
    {
        return result;
    }

    let computed = compute(root);
    cached
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .entry(root.to_path_buf())
        .or_insert_with(|| computed.clone())
        .clone()
}

fn global_package_toolchain_digests() -> Result<Vec<BuildInputDigest>, String> {
    let root = repo_root();
    root_scoped_build_input_digests(&GLOBAL_PACKAGE_TOOLCHAIN_DIGESTS, &root, |root| {
        global_package_build_input_digests_for(root, GLOBAL_PACKAGE_TOOLCHAIN_INPUTS)
    })
}

fn fork_instrument_tool_digests() -> Result<Vec<BuildInputDigest>, String> {
    let root = repo_root();
    root_scoped_build_input_digests(&FORK_INSTRUMENT_TOOL_DIGESTS, &root, |root| {
        let paths = fork_instrument_tool_input_paths(root)?;
        let refs: Vec<&str> = paths.iter().map(String::as_str).collect();
        let mut digests = global_package_build_input_digests_for(root, &refs)?;
        digests.push(BuildInputDigest {
            label: "cargo-metadata:fork-instrument-build-deps".to_string(),
            digest: fork_instrument_cargo_dependency_digest(root)?,
        });
        Ok(digests)
    })
}

fn package_uses_fork_instrument_tool(target: &DepsManifest) -> bool {
    matches!(target.kind, ManifestKind::Program)
        && target
            .program_outputs
            .iter()
            .any(|out| out.fork_instrumentation != ForkInstrumentationPolicy::Disabled)
}

#[derive(Debug, serde::Deserialize)]
struct CargoLock {
    #[serde(default)]
    package: Vec<CargoLockPackage>,
}

#[derive(Debug, serde::Deserialize)]
struct CargoLockPackage {
    name: String,
    version: String,
    source: Option<String>,
    checksum: Option<String>,
}

const FORK_INSTRUMENT_CARGO_METADATA_ARGS: &[&str] =
    &["metadata", "--format-version=1", "--locked"];

fn fork_instrument_cargo_dependency_digest(root: &Path) -> Result<[u8; 32], String> {
    // WHY: program cache paths have no build-host dimension. Filtering this
    // graph through the current macOS or Linux host made one source tree
    // compute different identities. Cargo's unfiltered graph is the stable
    // union, so any dependency that can build the instrumenter invalidates the
    // shared generation without making the key host-specific.
    let output = Command::new("cargo")
        .args(FORK_INSTRUMENT_CARGO_METADATA_ARGS)
        .current_dir(root)
        .output()
        .map_err(|e| format!("run cargo metadata for fork-instrument cache key: {e}"))?;
    fork_instrument_cargo_dependency_digest_from_output(root, output, None)
}

fn fork_instrument_cargo_dependency_digest_from_output(
    root: &Path,
    output: std::process::Output,
    inert_source_root: Option<&Path>,
) -> Result<[u8; 32], String> {
    if !output.status.success() {
        return Err(format!(
            "cargo metadata for fork-instrument cache key failed: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        ));
    }

    let metadata: serde_json::Value = serde_json::from_slice(&output.stdout)
        .map_err(|e| format!("parse cargo metadata for fork-instrument cache key: {e}"))?;
    if let Some(source_root) = inert_source_root {
        validate_inert_source_cargo_metadata(source_root, &metadata)?;
    }
    let lock_text = std::fs::read_to_string(root.join("Cargo.lock"))
        .map_err(|e| format!("read Cargo.lock for fork-instrument cache key: {e}"))?;
    let lock: CargoLock = toml::from_str(&lock_text)
        .map_err(|e| format!("parse Cargo.lock for fork-instrument cache key: {e}"))?;
    fork_instrument_cargo_dependency_digest_from_metadata(root, &metadata, &lock)
}

fn validate_inert_source_cargo_metadata(
    source_root: &Path,
    metadata: &serde_json::Value,
) -> Result<(), String> {
    let canonical_root = std::fs::canonicalize(source_root).map_err(|e| {
        format!(
            "canonicalize inert source root {}: {e}",
            source_root.display()
        )
    })?;
    let canonical_fork_manifest = canonical_root.join("crates/fork-instrument/Cargo.toml");
    let mut found_fork_manifest = false;
    for package in metadata_array(metadata, "packages")? {
        if package
            .get("source")
            .is_some_and(|source| !source.is_null())
        {
            continue;
        }
        let manifest_path = PathBuf::from(metadata_str(package, "manifest_path")?);
        let canonical_manifest = std::fs::canonicalize(&manifest_path).map_err(|e| {
            format!(
                "canonicalize inert source Cargo manifest {}: {e}",
                manifest_path.display()
            )
        })?;
        if !canonical_manifest.starts_with(&canonical_root) {
            return Err(format!(
                "inert source Cargo metadata contains a local package outside the producer checkout: {}",
                manifest_path.display()
            ));
        }
        require_path_beneath_without_symlinks(
            &canonical_root,
            &canonical_manifest,
            "inert source Cargo package manifest",
        )?;
        if metadata_str(package, "name")? == "fork-instrument" {
            if canonical_manifest != canonical_fork_manifest {
                return Err(format!(
                    "inert source fork-instrument manifest must be exactly {}",
                    canonical_fork_manifest.display()
                ));
            }
            found_fork_manifest = true;
        }
    }
    if !found_fork_manifest {
        return Err(format!(
            "inert source Cargo metadata is missing exact fork-instrument manifest {}",
            canonical_fork_manifest.display()
        ));
    }
    Ok(())
}

fn require_path_beneath_without_symlinks(
    root: &Path,
    path: &Path,
    context: &str,
) -> Result<(), String> {
    let relative = path
        .strip_prefix(root)
        .map_err(|_| format!("{context} escapes {}", root.display()))?;
    let mut current = root.to_path_buf();
    for component in relative.components() {
        current.push(component);
        let metadata = std::fs::symlink_metadata(&current)
            .map_err(|e| format!("inspect {context} {}: {e}", current.display()))?;
        if metadata.file_type().is_symlink() {
            return Err(format!(
                "{context} must not traverse a symlink: {}",
                current.display()
            ));
        }
    }
    require_regular_nonsymlink_file(path, context)
}

fn fork_instrument_cargo_dependency_digest_from_metadata(
    root: &Path,
    metadata: &serde_json::Value,
    lock: &CargoLock,
) -> Result<[u8; 32], String> {
    let packages = metadata_array(metadata, "packages")?;
    let nodes = metadata
        .get("resolve")
        .and_then(|resolve| resolve.get("nodes"))
        .and_then(|nodes| nodes.as_array())
        .ok_or_else(|| "cargo metadata missing resolve.nodes".to_string())?;

    let mut packages_by_id: BTreeMap<String, &serde_json::Value> = BTreeMap::new();
    let mut root_package_id: Option<String> = None;
    for package in packages {
        let id = metadata_str(package, "id")?.to_string();
        let name = metadata_str(package, "name")?;
        let manifest_path = metadata_str(package, "manifest_path")?;
        if name == "fork-instrument"
            && manifest_path.ends_with("/crates/fork-instrument/Cargo.toml")
        {
            root_package_id = Some(id.clone());
        }
        packages_by_id.insert(id, package);
    }

    let root_package_id = root_package_id
        .ok_or_else(|| "cargo metadata missing fork-instrument package".to_string())?;
    let mut nodes_by_id: BTreeMap<String, &serde_json::Value> = BTreeMap::new();
    for node in nodes {
        nodes_by_id.insert(metadata_str(node, "id")?.to_string(), node);
    }

    let mut closure = BTreeSet::new();
    let mut stack = vec![root_package_id.clone()];
    while let Some(package_id) = stack.pop() {
        if !closure.insert(package_id.clone()) {
            continue;
        }
        let node = nodes_by_id
            .get(&package_id)
            .ok_or_else(|| format!("cargo metadata missing resolve node for {package_id}"))?;
        for dep in selected_cargo_metadata_deps(node)? {
            stack.push(dep);
        }
    }

    let lock_checksums = cargo_lock_checksums(lock);
    let mut entries = Vec::with_capacity(closure.len());
    for package_id in closure {
        let package = packages_by_id
            .get(&package_id)
            .ok_or_else(|| format!("cargo metadata missing package for {package_id}"))?;
        let node = nodes_by_id
            .get(&package_id)
            .ok_or_else(|| format!("cargo metadata missing resolve node for {package_id}"))?;
        let stable_id = stable_cargo_package_id(root, package)?;
        let features = sorted_string_array(node, "features")?;
        let deps = selected_cargo_metadata_deps(node)?
            .into_iter()
            .map(|dep_id| {
                let dep_package = packages_by_id
                    .get(&dep_id)
                    .ok_or_else(|| format!("cargo metadata missing package for {dep_id}"))?;
                stable_cargo_package_id(root, dep_package)
            })
            .collect::<Result<BTreeSet<_>, _>>()?;
        let lock_key = cargo_lock_key(package)?;
        let checksum = lock_checksums.get(&lock_key).cloned().unwrap_or_default();
        entries.push((stable_id, features, deps, checksum));
    }
    entries.sort_by(|a, b| a.0.cmp(&b.0));

    let mut h = Sha256::new();
    h.update(b"fork-instrument-cargo-build-deps-v2-host-union\n");
    for (stable_id, features, deps, checksum) in entries {
        h.update(b"package\0");
        h.update(stable_id.as_bytes());
        h.update(b"\0checksum\0");
        h.update(checksum.as_bytes());
        h.update(b"\0features\0");
        for feature in features {
            h.update(feature.as_bytes());
            h.update(b"\0");
        }
        h.update(b"deps\0");
        for dep in deps {
            h.update(dep.as_bytes());
            h.update(b"\0");
        }
        h.update(b"\n");
    }
    Ok(h.finalize().into())
}

fn selected_cargo_metadata_deps(node: &serde_json::Value) -> Result<Vec<String>, String> {
    let deps = match node.get("deps").and_then(|deps| deps.as_array()) {
        Some(deps) => deps,
        None => return Ok(Vec::new()),
    };
    let mut out = Vec::new();
    for dep in deps {
        if !cargo_metadata_dep_is_build_input(dep)? {
            continue;
        }
        out.push(metadata_str(dep, "pkg")?.to_string());
    }
    out.sort();
    out.dedup();
    Ok(out)
}

fn cargo_metadata_dep_is_build_input(dep: &serde_json::Value) -> Result<bool, String> {
    let dep_kinds = dep
        .get("dep_kinds")
        .and_then(|dep_kinds| dep_kinds.as_array())
        .ok_or_else(|| "cargo metadata dependency missing dep_kinds".to_string())?;
    Ok(dep_kinds.iter().any(|kind| {
        kind.get("kind")
            .and_then(|kind| kind.as_str())
            .map(|kind| kind == "build")
            .unwrap_or(true)
    }))
}

fn stable_cargo_package_id(root: &Path, package: &serde_json::Value) -> Result<String, String> {
    let name = metadata_str(package, "name")?;
    let version = metadata_str(package, "version")?;
    let source = package.get("source").and_then(|source| source.as_str());
    if let Some(source) = source {
        return Ok(format!("{source}#{name}@{version}"));
    }

    let manifest_path = PathBuf::from(metadata_str(package, "manifest_path")?);
    let rel_manifest = manifest_path.strip_prefix(root).unwrap_or(&manifest_path);
    Ok(format!(
        "path:{}#{name}@{version}",
        rel_manifest.to_string_lossy()
    ))
}

fn cargo_lock_key(package: &serde_json::Value) -> Result<(String, String, String), String> {
    Ok((
        metadata_str(package, "name")?.to_string(),
        metadata_str(package, "version")?.to_string(),
        package
            .get("source")
            .and_then(|source| source.as_str())
            .unwrap_or("")
            .to_string(),
    ))
}

fn cargo_lock_checksums(lock: &CargoLock) -> BTreeMap<(String, String, String), String> {
    lock.package
        .iter()
        .filter_map(|package| {
            package.checksum.as_ref().map(|checksum| {
                (
                    (
                        package.name.clone(),
                        package.version.clone(),
                        package.source.clone().unwrap_or_default(),
                    ),
                    checksum.clone(),
                )
            })
        })
        .collect()
}

fn metadata_array<'a>(
    value: &'a serde_json::Value,
    field: &str,
) -> Result<&'a Vec<serde_json::Value>, String> {
    value
        .get(field)
        .and_then(|value| value.as_array())
        .ok_or_else(|| format!("cargo metadata missing {field} array"))
}

fn metadata_str<'a>(value: &'a serde_json::Value, field: &str) -> Result<&'a str, String> {
    value
        .get(field)
        .and_then(|value| value.as_str())
        .ok_or_else(|| format!("cargo metadata missing {field} string"))
}

fn sorted_string_array(value: &serde_json::Value, field: &str) -> Result<Vec<String>, String> {
    let mut out = value
        .get(field)
        .and_then(|value| value.as_array())
        .ok_or_else(|| format!("cargo metadata missing {field} array"))?
        .iter()
        .map(|value| {
            value
                .as_str()
                .map(str::to_string)
                .ok_or_else(|| format!("cargo metadata {field} array contains a non-string"))
        })
        .collect::<Result<Vec<_>, _>>()?;
    out.sort();
    Ok(out)
}

fn global_package_build_input_digests_for(
    root: &Path,
    inputs: &[&str],
) -> Result<Vec<BuildInputDigest>, String> {
    let mut out = Vec::with_capacity(inputs.len());
    for input in inputs {
        let path = root.join(input);
        if !path.exists() {
            return Err(format!(
                "global package build input {:?} not found at {}",
                input,
                path.display()
            ));
        }
        out.push(BuildInputDigest {
            label: (*input).to_string(),
            digest: hash_global_package_build_input(root, input, &path)?,
        });
    }
    Ok(out)
}

fn hash_global_package_build_input(
    root: &Path,
    input: &str,
    path: &Path,
) -> Result<[u8; 32], String> {
    if input == "libc/musl" {
        if let Some(digest) = hash_gitlink_input(root, input)? {
            return Ok(digest);
        }
    }
    hash_build_input(path)
}

fn gitlink_index_command(root: &Path, input: &str) -> Command {
    let mut safe_directory = std::ffi::OsString::from("safe.directory=");
    safe_directory.push(root.as_os_str());

    let mut command = Command::new("git");
    command
        .arg("-c")
        .arg(safe_directory)
        .arg("-C")
        .arg(root)
        .arg("ls-files")
        .arg("--stage")
        .arg("--")
        .arg(input);
    command
}

fn hash_gitlink_input(root: &Path, input: &str) -> Result<Option<[u8; 32]>, String> {
    // The index is the checkout's content selector: it represents the gitlink
    // actually selected for this build without importing the current branch or
    // HEAD into artifact identity. Keep the trust exception scoped to this one
    // command and directory for protected cross-user source aliases.
    let output = match gitlink_index_command(root, input).output() {
        Ok(output) => output,
        Err(_) => return Ok(None),
    };
    if !output.status.success() {
        return Ok(None);
    }
    let stdout = String::from_utf8_lossy(&output.stdout);
    let Some(line) = stdout.lines().next() else {
        return Ok(None);
    };
    let Some(rest) = line.strip_prefix("160000 ") else {
        return Ok(None);
    };
    let Some((object_id, stage_and_path)) = rest.split_once(' ') else {
        return Err(format!("unexpected gitlink entry for {input:?}: {line:?}"));
    };
    let Some((stage, indexed_path)) = stage_and_path.split_once('\t') else {
        return Err(format!("unexpected gitlink entry for {input:?}: {line:?}"));
    };
    if stage != "0" || indexed_path != input {
        return Err(format!("unexpected gitlink entry for {input:?}: {line:?}"));
    }

    let mut h = Sha256::new();
    h.update(b"gitlink\0");
    h.update(input.as_bytes());
    h.update(b"\0");
    h.update(object_id.as_bytes());
    h.update(b"\0");
    Ok(Some(h.finalize().into()))
}

#[cfg(test)]
fn build_input_digests(
    target: &DepsManifest,
    registry: &Registry,
) -> Result<Vec<BuildInputDigest>, String> {
    build_input_digests_from_repo(target, registry, &repo_root(), ResolvePolicy::Default)
}

fn build_input_digests_from_repo(
    target: &DepsManifest,
    registry: &Registry,
    main_repo_root: &Path,
    policy: ResolvePolicy,
) -> Result<Vec<BuildInputDigest>, String> {
    // Defense in depth for direct helper callers. This pure selector runs
    // before this helper reads build metadata; identity construction already
    // selects the same error before memo or dependency traversal.
    source_only_strict_input_platform(policy, target.source.provider, cfg!(unix))?;
    let requires_declared_source_inputs = policy == ResolvePolicy::SourceOnlyV1
        && matches!(
            target.source.provider,
            SourceProvider::Repository | SourceProvider::DevShell
        );
    if !target.dir.join("build.toml").exists() {
        if requires_declared_source_inputs {
            return Err(format!(
                "{}: source.provider = {:?} requires build.toml with non-empty inputs",
                target.spec(),
                target.source.provider.as_str(),
            ));
        }
        return Ok(Vec::new());
    }
    let build = BuildToml::load(&target.dir)?;
    let validate_declared_source_inputs = policy == ResolvePolicy::SourceOnlyV1
        && matches!(
            target.source.provider,
            SourceProvider::Repository | SourceProvider::DevShell
        );
    if requires_declared_source_inputs && build.inputs.is_empty() {
        return Err(format!(
            "{}: source.provider = {:?} requires non-empty build.toml.inputs",
            target.spec(),
            target.source.provider.as_str(),
        ));
    }
    let mut out = Vec::with_capacity(build.inputs.len() + build.git_inputs.len());
    let mut source_input_labels = BTreeSet::new();
    for input in &build.inputs {
        if validate_declared_source_inputs {
            validate_repository_build_input_label(input)?;
            if !source_input_labels.insert(input.as_str()) {
                return Err(format!(
                    "{}: source-only build input labels must be unique; duplicate {input:?}",
                    target.spec()
                ));
            }
        }
        if let Some(crate_name) = input.strip_prefix(crate::cargo_closure::CARGO_INPUT_PREFIX) {
            let crate_name = crate_name.trim();
            if crate_name.is_empty() {
                return Err(format!(
                    "{}: build.toml input `{input}` has an empty crate name",
                    target.spec()
                ));
            }
            for rel in crate::cargo_closure::cargo_closure_paths(main_repo_root, crate_name)? {
                let path = resolve_build_input_path_from_repo(target, registry, &rel, main_repo_root)?;
                let digest = if validate_declared_source_inputs {
                    let authority_root =
                        repository_source_authority_root(&path, registry, main_repo_root)?;
                    strict_source_build_input_digest(&authority_root, &path)?
                } else {
                    hash_build_input(&path)?
                };
                out.push(BuildInputDigest {
                    label: format!("{input}::{rel}"),
                    digest,
                });
            }
            continue;
        }
        let path = resolve_build_input_path_from_repo(target, registry, input, main_repo_root)?;
        let digest = if validate_declared_source_inputs {
            let authority_root = repository_source_authority_root(&path, registry, main_repo_root)?;
            strict_source_build_input_digest(&authority_root, &path)?
        } else {
            hash_build_input(&path)?
        };
        out.push(BuildInputDigest {
            label: input.clone(),
            digest,
        });
    }
    // External Git inputs are content-addressed before any network access.
    // Preserve authored order and length-prefix every field so distinct
    // tuples cannot collide through concatenation. Adding this section is
    // intentionally additive: packages without git_inputs retain their
    // existing cache keys.
    for (index, input) in build.git_inputs.iter().enumerate() {
        let mut h = Sha256::new();
        let extended_identity = input.tree.is_some() || input.allow_uninitialized_gitlinks;
        h.update(if extended_identity {
            b"wasm-posix-build-git-input-v2\0" as &[u8]
        } else {
            b"wasm-posix-build-git-input-v1\0" as &[u8]
        });
        for field in [
            input.name.as_bytes(),
            input.repository.as_bytes(),
            input.commit.as_bytes(),
        ] {
            h.update((field.len() as u64).to_le_bytes());
            h.update(field);
        }
        if extended_identity {
            let tree = input.tree.as_deref().unwrap_or_default().as_bytes();
            h.update((tree.len() as u64).to_le_bytes());
            h.update(tree);
            h.update([u8::from(input.allow_uninitialized_gitlinks)]);
        }
        out.push(BuildInputDigest {
            label: format!("git-input:{index}:{}", input.name),
            digest: h.finalize().into(),
        });
    }
    Ok(out)
}

const SOURCE_ONLY_NATIVE_NON_UNIX_INPUT_ERROR: &str = "source-only Repository/DevShell build inputs require Unix descriptor-relative validation; native non-Unix hosts are unsupported in this release (Nix or WSL Unix environments remain supported)";

fn source_only_strict_input_platform(
    policy: ResolvePolicy,
    provider: SourceProvider,
    is_unix: bool,
) -> Result<(), String> {
    if policy == ResolvePolicy::SourceOnlyV1
        && matches!(
            provider,
            SourceProvider::Repository | SourceProvider::DevShell
        )
        && !is_unix
    {
        return Err(SOURCE_ONLY_NATIVE_NON_UNIX_INPUT_ERROR.to_string());
    }
    Ok(())
}

fn validate_repository_build_input_label(input: &str) -> Result<(), String> {
    let invalid_prefix_alias = input.starts_with("//")
        || input
            .as_bytes()
            .get(1)
            .is_some_and(|byte| *byte == b':' && input.as_bytes()[0].is_ascii_alphabetic());
    if input.is_empty()
        || input.contains('\0')
        || input.contains('\\')
        || input.starts_with('/')
        || invalid_prefix_alias
        || input
            .split('/')
            .any(|component| component.is_empty() || matches!(component, "." | ".."))
        || Path::new(input).is_absolute()
        || Path::new(input)
            .components()
            .any(|component| !matches!(component, Component::Normal(_)))
    {
        return Err(format!(
            "repository build input must use its canonical repository-relative '/'-separated spelling: {input:?}"
        ));
    }
    let canonical_label = Path::new(input)
        .components()
        .map(|component| match component {
            Component::Normal(value) => value.to_string_lossy().into_owned(),
            _ => unreachable!("non-normal component rejected above"),
        })
        .collect::<Vec<_>>()
        .join("/");
    if canonical_label != input {
        return Err(format!(
            "repository build input must use its canonical repository-relative spelling: {input:?}"
        ));
    }
    Ok(())
}

fn repository_source_authority_root(
    input: &Path,
    registry: &Registry,
    main_repo_root: &Path,
) -> Result<PathBuf, String> {
    let mut candidates = registry
        .roots
        .iter()
        .map(PathBuf::as_path)
        .chain(std::iter::once(main_repo_root))
        .filter(|root| input.starts_with(root))
        .collect::<Vec<_>>();
    candidates.sort_by_key(|root| std::cmp::Reverse(root.components().count()));
    let root = candidates.first().ok_or_else(|| {
        format!(
            "repository build input {} is outside every configured repository authority",
            input.display()
        )
    })?;
    std::fs::canonicalize(root).map_err(|error| {
        format!(
            "canonicalize repository source authority {}: {error}",
            root.display()
        )
    })
}

#[cfg(unix)]
fn strict_source_build_input_digest(root: &Path, input: &Path) -> Result<[u8; 32], String> {
    strict_source_build_input_digest_with(root, input, &mut |_| {})
}

#[cfg(not(unix))]
fn strict_source_build_input_digest(_root: &Path, _input: &Path) -> Result<[u8; 32], String> {
    Err(SOURCE_ONLY_NATIVE_NON_UNIX_INPUT_ERROR.to_string())
}

#[cfg(unix)]
fn strict_source_build_input_digest_with<BeforeRead>(
    root: &Path,
    input: &Path,
    before_read: &mut BeforeRead,
) -> Result<[u8; 32], String>
where
    BeforeRead: FnMut(&Path),
{
    let root_metadata = std::fs::symlink_metadata(root)
        .map_err(|error| format!("inspect repository source root {}: {error}", root.display()))?;
    if root_metadata.file_type().is_symlink() || !root_metadata.is_dir() {
        return Err(format!(
            "repository source root must be a real nonsymlink directory: {}",
            root.display()
        ));
    }
    let canonical_root = std::fs::canonicalize(root).map_err(|error| {
        format!(
            "canonicalize repository source root {}: {error}",
            root.display()
        )
    })?;
    if canonical_root != root {
        return Err(format!(
            "repository source root must use its canonical spelling: {} (canonical {})",
            root.display(),
            canonical_root.display()
        ));
    }
    let relative = input.strip_prefix(root).map_err(|_| {
        format!(
            "repository build input {} escapes source root {}",
            input.display(),
            root.display()
        )
    })?;
    if relative.as_os_str().is_empty()
        || relative
            .components()
            .any(|component| !matches!(component, Component::Normal(_)))
    {
        return Err(format!(
            "repository build input must name a descendant of {}: {}",
            root.display(),
            input.display()
        ));
    }

    strict_source_build_input_digest_unix(
        &canonical_root,
        relative,
        input,
        &root_metadata,
        before_read,
    )
}

#[cfg(unix)]
fn source_input_metadata_matches(
    expected: &std::fs::Metadata,
    actual: &std::fs::Metadata,
) -> Result<bool, String> {
    Ok(package_mirror_identity(expected)? == package_mirror_identity(actual)?
        && expected.is_file() == actual.is_file()
        && expected.is_dir() == actual.is_dir()
        && expected.len() == actual.len()
        && expected.modified().ok() == actual.modified().ok())
}

#[cfg(unix)]
fn require_unchanged_source_input(
    expected: &std::fs::Metadata,
    actual: &std::fs::Metadata,
    path: &Path,
) -> Result<(), String> {
    if !source_input_metadata_matches(expected, actual)? {
        return Err(format!(
            "source-only build input changed while it was validated and digested: {}",
            path.display()
        ));
    }
    Ok(())
}

#[cfg(unix)]
fn strict_source_open_at(
    parent: &std::fs::File,
    name: &std::ffi::OsStr,
    path: &Path,
    phase: &str,
) -> Result<std::fs::File, String> {
    let descriptor = rustix::fs::openat(
        parent,
        name,
        rustix::fs::OFlags::RDONLY
            | rustix::fs::OFlags::CLOEXEC
            | rustix::fs::OFlags::NOFOLLOW
            | rustix::fs::OFlags::NONBLOCK,
        rustix::fs::Mode::empty(),
    )
    .map_err(|error| {
        format!(
            "{phase} source-only build input (missing, unreadable, or symlink) {}: {error}",
            path.display()
        )
    })?;
    Ok(std::fs::File::from(descriptor))
}

#[cfg(unix)]
fn strict_source_reopen_unchanged(
    parent: &std::fs::File,
    name: &std::ffi::OsStr,
    expected: &std::fs::Metadata,
    path: &Path,
) -> Result<(), String> {
    let reopened = strict_source_open_at(parent, name, path, "reopen changed")?;
    let metadata = reopened
        .metadata()
        .map_err(|error| format!("inspect reopened source input {}: {error}", path.display()))?;
    require_unchanged_source_input(expected, &metadata, path)
}

#[cfg(unix)]
fn strict_source_build_input_digest_unix<BeforeRead>(
    root: &Path,
    relative: &Path,
    input: &Path,
    root_metadata: &std::fs::Metadata,
    before_read: &mut BeforeRead,
) -> Result<[u8; 32], String>
where
    BeforeRead: FnMut(&Path),
{
    let root_descriptor = rustix::fs::open(
        root,
        rustix::fs::OFlags::RDONLY
            | rustix::fs::OFlags::CLOEXEC
            | rustix::fs::OFlags::NOFOLLOW
            | rustix::fs::OFlags::NONBLOCK,
        rustix::fs::Mode::empty(),
    )
    .map(std::fs::File::from)
    .map_err(|error| format!("open repository source root {}: {error}", root.display()))?;
    let opened_root_metadata = root_descriptor
        .metadata()
        .map_err(|error| format!("inspect opened source root {}: {error}", root.display()))?;
    require_unchanged_source_input(root_metadata, &opened_root_metadata, root)?;

    let components = relative
        .components()
        .map(|component| match component {
            Component::Normal(name) => Ok(name),
            _ => Err(format!(
                "repository build input has a non-normal component: {}",
                input.display()
            )),
        })
        .collect::<Result<Vec<_>, _>>()?;
    let (name, ancestors) = components
        .split_last()
        .ok_or_else(|| format!("repository build input is empty: {}", input.display()))?;
    let mut descriptors = vec![root_descriptor];
    let mut ancestor_names = Vec::with_capacity(ancestors.len());
    let mut ancestor_metadata = Vec::with_capacity(ancestors.len());
    let mut ancestor_paths = Vec::with_capacity(ancestors.len());
    let mut current_path = root.to_path_buf();
    for ancestor in ancestors {
        current_path.push(ancestor);
        let parent = descriptors
            .last()
            .expect("source root descriptor starts the ancestor chain");
        let opened = strict_source_open_at(parent, ancestor, &current_path, "open ancestor")?;
        let metadata = opened.metadata().map_err(|error| {
            format!("inspect source input ancestor {}: {error}", current_path.display())
        })?;
        if !metadata.is_dir() {
            return Err(format!(
                "source-only build input ancestor must be a real directory: {}",
                current_path.display()
            ));
        }
        before_read(&current_path);
        strict_source_reopen_unchanged(parent, ancestor, &metadata, &current_path)?;
        descriptors.push(opened);
        ancestor_names.push(ancestor.to_os_string());
        ancestor_metadata.push(metadata);
        ancestor_paths.push(current_path.clone());
    }

    let mut hasher = Sha256::new();
    strict_source_hash_entry_unix(
        &mut hasher,
        descriptors
            .last()
            .expect("source root descriptor starts the ancestor chain"),
        name,
        input,
        Path::new(""),
        before_read,
    )?;
    for index in 0..ancestor_names.len() {
        let held_metadata = descriptors[index + 1].metadata().map_err(|error| {
            format!(
                "reinspect opened source input ancestor {}: {error}",
                ancestor_paths[index].display()
            )
        })?;
        require_unchanged_source_input(
            &ancestor_metadata[index],
            &held_metadata,
            &ancestor_paths[index],
        )?;
        strict_source_reopen_unchanged(
            &descriptors[index],
            &ancestor_names[index],
            &ancestor_metadata[index],
            &ancestor_paths[index],
        )?;
    }
    require_unchanged_source_input(
        root_metadata,
        &descriptors[0]
            .metadata()
            .map_err(|error| format!("reinspect opened source root {}: {error}", root.display()))?,
        root,
    )?;
    let reopened_root = rustix::fs::open(
        root,
        rustix::fs::OFlags::RDONLY
            | rustix::fs::OFlags::CLOEXEC
            | rustix::fs::OFlags::NOFOLLOW
            | rustix::fs::OFlags::NONBLOCK,
        rustix::fs::Mode::empty(),
    )
    .map(std::fs::File::from)
    .map_err(|error| format!("reopen changed repository source root {}: {error}", root.display()))?;
    require_unchanged_source_input(
        root_metadata,
        &reopened_root
            .metadata()
            .map_err(|error| format!("reinspect source root {}: {error}", root.display()))?,
        root,
    )?;
    Ok(hasher.finalize().into())
}

#[cfg(unix)]
fn strict_source_hash_entry_unix<BeforeRead>(
    hasher: &mut Sha256,
    parent: &std::fs::File,
    name: &std::ffi::OsStr,
    path: &Path,
    relative: &Path,
    before_read: &mut BeforeRead,
) -> Result<(), String>
where
    BeforeRead: FnMut(&Path),
{
    use std::os::unix::ffi::OsStringExt;

    let mut opened = strict_source_open_at(parent, name, path, "open")?;
    let initial = opened
        .metadata()
        .map_err(|error| format!("inspect opened source input {}: {error}", path.display()))?;
    if !initial.is_file() && !initial.is_dir() {
        return Err(format!(
            "source-only build input must be a regular file or real directory: {}",
            path.display()
        ));
    }
    before_read(path);
    strict_source_reopen_unchanged(parent, name, &initial, path)?;
    let relative_text = relative.to_string_lossy();
    if initial.is_file() {
        let mut bytes = Vec::new();
        std::io::Read::read_to_end(&mut opened, &mut bytes)
            .map_err(|error| format!("read source-only build input {}: {error}", path.display()))?;
        hasher.update(b"file\0");
        hasher.update(relative_text.as_bytes());
        hasher.update(b"\0");
        hasher.update((bytes.len() as u64).to_le_bytes());
        hasher.update(b"\0");
        hasher.update(bytes);
        hasher.update(b"\0");
    } else {
        hasher.update(b"dir\0");
        hasher.update(relative_text.as_bytes());
        hasher.update(b"\0");
        let mut directory = rustix::fs::Dir::read_from(&opened).map_err(|error| {
            format!("read source-only build input directory {}: {error}", path.display())
        })?;
        let mut entries = Vec::new();
        for entry in &mut directory {
            let entry = entry.map_err(|error| {
                format!("read source-only build input entry below {}: {error}", path.display())
            })?;
            let bytes = entry.file_name().to_bytes();
            if matches!(bytes, b"." | b"..") {
                continue;
            }
            entries.push(OsString::from_vec(bytes.to_vec()));
        }
        entries.sort();
        for child in entries {
            strict_source_hash_entry_unix(
                hasher,
                &opened,
                &child,
                &path.join(&child),
                &relative.join(&child),
                before_read,
            )?;
        }
    }
    let opened_after = opened
        .metadata()
        .map_err(|error| format!("reinspect opened source input {}: {error}", path.display()))?;
    require_unchanged_source_input(&initial, &opened_after, path)?;
    strict_source_reopen_unchanged(parent, name, &initial, path)
}

const DEV_SHELL_COMPILER_OUTPUT_LIMIT: usize = 64 * 1024;

struct CompilerVersionProbe {
    success: bool,
    status: String,
    stdout: Vec<u8>,
    stderr: Vec<u8>,
}

fn dev_shell_source_identity(target: &DepsManifest) -> Result<[u8; 32], String> {
    let environment = [
        "LLVM_VERSION",
        "LLVM_PREFIX",
        "WASM_POSIX_LLVM_LIBCXX_SOURCE",
        "WASM_POSIX_LLVM_LIBUNWIND_SOURCE",
    ]
    .into_iter()
    .filter_map(|name| std::env::var_os(name).map(|value| (name.to_string(), value)))
    .collect::<BTreeMap<String, OsString>>();
    dev_shell_source_identity_with_environment(target, &environment, Path::new("/nix/store"))
}

fn dev_shell_source_identity_with_environment(
    target: &DepsManifest,
    environment: &BTreeMap<String, OsString>,
    nix_store_root: &Path,
) -> Result<[u8; 32], String> {
    dev_shell_source_identity_with_inputs(target, environment, nix_store_root, |compiler| {
        bounded_compiler_version_probe(compiler)
    })
}

fn dev_shell_source_identity_with_inputs<Probe>(
    target: &DepsManifest,
    environment: &BTreeMap<String, OsString>,
    nix_store_root: &Path,
    probe: Probe,
) -> Result<[u8; 32], String>
where
    Probe: FnOnce(&Path) -> Result<CompilerVersionProbe, String>,
{
    if target.source.provider != SourceProvider::DevShell {
        return Err(format!(
            "{}: dev-shell source identity requires source.provider = \"dev-shell\"",
            target.spec()
        ));
    }
    if target.version != "21.1.7" {
        return Err(format!(
            "{}: dev-shell libcxx identity supports exact LLVM version 21.1.7",
            target.spec()
        ));
    }
    let value = |name: &str| -> Result<&str, String> {
        environment
            .get(name)
            .ok_or_else(|| {
                format!(
                    "{}: required dev-shell variable {name} is unset",
                    target.spec()
                )
            })?
            .to_str()
            .ok_or_else(|| format!("{}: dev-shell variable {name} must be UTF-8", target.spec()))
    };
    let llvm_version = value("LLVM_VERSION")?;
    if llvm_version != target.version {
        return Err(format!(
            "{}: LLVM_VERSION {llvm_version:?} must exactly match package version {:?}",
            target.spec(),
            target.version
        ));
    }

    let llvm_prefix =
        validate_canonical_dev_shell_directory(Path::new(value("LLVM_PREFIX")?), "LLVM_PREFIX")?;
    let nix_store_root = validate_canonical_dev_shell_directory(nix_store_root, "Nix store root")?;
    let libcxx_source = validate_nix_source_root(
        Path::new(value("WASM_POSIX_LLVM_LIBCXX_SOURCE")?),
        &nix_store_root,
        "WASM_POSIX_LLVM_LIBCXX_SOURCE",
    )?;
    let libunwind_source = validate_nix_source_root(
        Path::new(value("WASM_POSIX_LLVM_LIBUNWIND_SOURCE")?),
        &nix_store_root,
        "WASM_POSIX_LLVM_LIBUNWIND_SOURCE",
    )?;
    require_dev_shell_regular_file(
        &libcxx_source.join("runtimes/CMakeLists.txt"),
        "libcxx runtimes/CMakeLists.txt",
    )?;
    require_dev_shell_real_directory(&libcxx_source.join("libcxx"), "libcxx source directory")?;
    require_dev_shell_real_directory(
        &libcxx_source.join("libcxxabi"),
        "libcxxabi source directory",
    )?;
    require_dev_shell_real_directory(
        &libunwind_source.join("libunwind"),
        "libunwind source directory",
    )?;

    let compiler = llvm_prefix.join("bin/clang");
    let output = probe(&compiler)?;
    if output.stdout.len().saturating_add(output.stderr.len()) > DEV_SHELL_COMPILER_OUTPUT_LIMIT {
        return Err(format!(
            "compiler probe {} --version output exceeds the combined 64 KiB limit",
            compiler.display()
        ));
    }
    let stdout = String::from_utf8(output.stdout).map_err(|_| {
        format!(
            "compiler probe stdout from {} must be UTF-8",
            compiler.display()
        )
    })?;
    let stderr = String::from_utf8(output.stderr).map_err(|_| {
        format!(
            "compiler probe stderr from {} must be UTF-8",
            compiler.display()
        )
    })?;
    if !output.success {
        return Err(format!(
            "compiler probe {} --version failed with {}: {}",
            compiler.display(),
            output.status,
            stderr.trim()
        ));
    }
    if !compiler_output_contains_exact_version(&stdout, &stderr, llvm_version) {
        return Err(format!(
            "compiler probe {} --version output does not contain exact version token {llvm_version:?}",
            compiler.display()
        ));
    }

    let mut hasher = Sha256::new();
    hasher.update(b"kandelo-dev-shell-source-v1\0");
    for field in [
        llvm_version.as_bytes(),
        llvm_prefix.as_os_str().as_encoded_bytes(),
        stdout.as_bytes(),
        stderr.as_bytes(),
        libcxx_source.as_os_str().as_encoded_bytes(),
        libunwind_source.as_os_str().as_encoded_bytes(),
    ] {
        hasher.update((field.len() as u64).to_le_bytes());
        hasher.update(field);
    }
    Ok(hasher.finalize().into())
}

fn validate_canonical_dev_shell_directory(path: &Path, label: &str) -> Result<PathBuf, String> {
    if !path.is_absolute()
        || path
            .components()
            .any(|component| matches!(component, Component::CurDir | Component::ParentDir))
    {
        return Err(format!(
            "{label} must be an absolute lexically normalized path: {}",
            path.display()
        ));
    }
    let metadata = std::fs::symlink_metadata(path)
        .map_err(|error| format!("inspect {label} {}: {error}", path.display()))?;
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err(format!(
            "{label} must be a real nonsymlink directory: {}",
            path.display()
        ));
    }
    let canonical = std::fs::canonicalize(path)
        .map_err(|error| format!("canonicalize {label} {}: {error}", path.display()))?;
    if canonical.as_os_str() != path.as_os_str() {
        return Err(format!(
            "{label} must use its canonical absolute spelling: {} (canonical {})",
            path.display(),
            canonical.display()
        ));
    }
    Ok(canonical)
}

fn validate_nix_source_root(path: &Path, store: &Path, label: &str) -> Result<PathBuf, String> {
    let canonical = validate_canonical_dev_shell_directory(path, label)?;
    if canonical == store || !canonical.starts_with(store) {
        return Err(format!(
            "{label} must be a Nix store path below {}: {}",
            store.display(),
            canonical.display()
        ));
    }
    Ok(canonical)
}

fn require_dev_shell_real_directory(path: &Path, label: &str) -> Result<(), String> {
    let metadata = std::fs::symlink_metadata(path)
        .map_err(|error| format!("inspect {label} {}: {error}", path.display()))?;
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err(format!(
            "{label} must be a real nonsymlink directory: {}",
            path.display()
        ));
    }
    Ok(())
}

fn require_dev_shell_regular_file(path: &Path, label: &str) -> Result<(), String> {
    let metadata = std::fs::symlink_metadata(path)
        .map_err(|error| format!("inspect {label} {}: {error}", path.display()))?;
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        return Err(format!(
            "{label} must be a regular nonsymlink file: {}",
            path.display()
        ));
    }
    std::fs::File::open(path)
        .map_err(|error| format!("open {label} {}: {error}", path.display()))?;
    Ok(())
}

fn bounded_compiler_version_probe(compiler: &Path) -> Result<CompilerVersionProbe, String> {
    let mut child = Command::new(compiler)
        .arg("--version")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|error| {
            format!(
                "run compiler probe {} --version: {error}",
                compiler.display()
            )
        })?;
    let stdout = child.stdout.take().expect("piped compiler stdout");
    let stderr = child.stderr.take().expect("piped compiler stderr");
    let reader = |mut stream: Box<dyn std::io::Read + Send>| {
        std::thread::spawn(move || -> Result<(Vec<u8>, usize), String> {
            let mut saved = Vec::new();
            let mut total = 0usize;
            let mut buffer = [0u8; 8192];
            loop {
                let count = stream
                    .read(&mut buffer)
                    .map_err(|error| format!("read compiler probe output: {error}"))?;
                if count == 0 {
                    break;
                }
                total = total.saturating_add(count);
                let remaining = (DEV_SHELL_COMPILER_OUTPUT_LIMIT + 1).saturating_sub(saved.len());
                saved.extend_from_slice(&buffer[..count.min(remaining)]);
            }
            Ok((saved, total))
        })
    };
    let stdout_reader = reader(Box::new(stdout));
    let stderr_reader = reader(Box::new(stderr));
    let status = child
        .wait()
        .map_err(|error| format!("wait for compiler probe {}: {error}", compiler.display()))?;
    let (stdout, stdout_total) = stdout_reader
        .join()
        .map_err(|_| "compiler stdout reader panicked".to_string())??;
    let (stderr, stderr_total) = stderr_reader
        .join()
        .map_err(|_| "compiler stderr reader panicked".to_string())??;
    if stdout_total.saturating_add(stderr_total) > DEV_SHELL_COMPILER_OUTPUT_LIMIT {
        return Err(format!(
            "compiler probe {} --version output exceeds the combined 64 KiB limit",
            compiler.display()
        ));
    }
    Ok(CompilerVersionProbe {
        success: status.success(),
        status: status.to_string(),
        stdout,
        stderr,
    })
}

fn compiler_output_contains_exact_version(stdout: &str, stderr: &str, version: &str) -> bool {
    stdout
        .split(|character: char| {
            !(character.is_ascii_alphanumeric() || matches!(character, '.' | '-' | '_'))
        })
        .chain(stderr.split(|character: char| {
            !(character.is_ascii_alphanumeric() || matches!(character, '.' | '-' | '_'))
        }))
        .any(|token| token == version)
}

fn resolve_build_input_path_from_repo(
    target: &DepsManifest,
    registry: &Registry,
    input: &str,
    main_repo_root: &Path,
) -> Result<PathBuf, String> {
    // Canonical Kandelo build inputs are authored relative to the repository
    // (`packages/registry/<package>/...`). Registry priority is package-level,
    // not file-level: once a first-hit package.toml selects an external
    // package, every declared input below that package must exist there. Never
    // fill a missing file from a lower package generation.
    if let Ok(registry_relative) = Path::new(input).strip_prefix("packages/registry") {
        let (package_name, package_relative) =
            split_registry_build_input(registry_relative, input)?;
        if let Some(selected) =
            selected_registry_package_dir(registry, main_repo_root, package_name)
        {
            return require_selected_registry_build_input(
                target,
                input,
                package_name,
                &selected,
                package_relative,
            );
        }

        // Some first-party helper trees under packages/registry (currently
        // npm and node-compat) deliberately are not packages. They remain
        // main-checkout inputs; an unclaimed directory in a higher registry
        // root must not shadow them.
        let main_candidate = main_repo_root.join(input);
        if main_candidate.exists() {
            return Ok(main_candidate);
        }
        return Err(format!(
            "{} build input {:?} does not name a selected registry package and was not found at {}",
            target.spec(),
            input,
            main_candidate.display(),
        ));
    }

    let main_candidate = main_repo_root.join(input);
    if main_candidate.exists() {
        return Ok(main_candidate);
    }

    // Preserve the historical registry-relative input form
    // (`<package>/build.sh`) for third-party registries that use it, with the
    // same package-level first-hit rule as canonical inputs.
    let input_path = Path::new(input);
    let mut legacy_components = input_path.components();
    if let Some(first_component) = legacy_components.next() {
        if let std::path::Component::Normal(package_component) = first_component {
            let package_name = package_component.to_str().ok_or_else(|| {
                format!(
                    "{} build input {:?} has a non-UTF-8 registry package name",
                    target.spec(),
                    input,
                )
            })?;
            let package_relative = legacy_components.as_path();
            if let Some(selected) =
                selected_registry_package_dir(registry, main_repo_root, package_name)
            {
                return require_selected_registry_build_input(
                    target,
                    input,
                    package_name,
                    &selected,
                    package_relative,
                );
            }
        }
    }

    let main_registry_candidate = main_repo_root.join("packages/registry").join(input);
    if main_registry_candidate.exists() {
        return Ok(main_registry_candidate);
    }
    let package_relative_candidate = target.dir.join(input);
    if package_relative_candidate.exists() {
        return Ok(package_relative_candidate);
    }

    Err(format!(
        "{} build input {:?} not found (tried: {}, {}, {})",
        target.spec(),
        input,
        main_candidate.display(),
        main_registry_candidate.display(),
        package_relative_candidate.display(),
    ))
}

fn split_registry_build_input<'a>(
    registry_relative: &'a Path,
    authored_input: &str,
) -> Result<(&'a str, &'a Path), String> {
    let mut components = registry_relative.components();
    let package_component = match components.next() {
        Some(std::path::Component::Normal(component)) => component,
        _ => {
            return Err(format!(
                "canonical registry build input must name a package below packages/registry: {authored_input:?}",
            ));
        }
    };
    let package_name = package_component.to_str().ok_or_else(|| {
        format!("canonical registry build input has a non-UTF-8 package name: {authored_input:?}",)
    })?;
    Ok((package_name, components.as_path()))
}

fn selected_registry_package_dir(
    registry: &Registry,
    main_repo_root: &Path,
    package_name: &str,
) -> Option<PathBuf> {
    if let Some(manifest) = registry.find(package_name) {
        return manifest.parent().map(Path::to_path_buf);
    }
    let main_package = main_repo_root.join("packages/registry").join(package_name);
    main_package
        .join("package.toml")
        .is_file()
        .then_some(main_package)
}

fn require_selected_registry_build_input(
    target: &DepsManifest,
    authored_input: &str,
    package_name: &str,
    selected_package_dir: &Path,
    package_relative: &Path,
) -> Result<PathBuf, String> {
    let candidate = selected_package_dir.join(package_relative);
    if candidate.exists() {
        return Ok(candidate);
    }
    Err(format!(
        "{} build input {:?} is missing from first-hit registry package {:?} at {}; lower-priority package roots were not consulted",
        target.spec(),
        authored_input,
        package_name,
        selected_package_dir.display(),
    ))
}

fn hash_build_input(path: &Path) -> Result<[u8; 32], String> {
    let mut h = Sha256::new();
    hash_build_input_entry(&mut h, path, path)?;
    Ok(h.finalize().into())
}

fn hash_build_input_entry(h: &mut Sha256, root: &Path, path: &Path) -> Result<(), String> {
    let meta =
        std::fs::symlink_metadata(path).map_err(|e| format!("stat {}: {e}", path.display()))?;
    let rel = path.strip_prefix(root).unwrap_or(path);
    let rel = rel.to_string_lossy();

    if meta.file_type().is_symlink() {
        let target =
            std::fs::read_link(path).map_err(|e| format!("readlink {}: {e}", path.display()))?;
        h.update(b"symlink\0");
        h.update(rel.as_bytes());
        h.update(b"\0");
        h.update(target.to_string_lossy().as_bytes());
        h.update(b"\0");
        return Ok(());
    }

    if meta.is_file() {
        let bytes = std::fs::read(path).map_err(|e| format!("read {}: {e}", path.display()))?;
        h.update(b"file\0");
        h.update(rel.as_bytes());
        h.update(b"\0");
        h.update((bytes.len() as u64).to_le_bytes());
        h.update(b"\0");
        h.update(bytes);
        h.update(b"\0");
        return Ok(());
    }

    if meta.is_dir() {
        h.update(b"dir\0");
        h.update(rel.as_bytes());
        h.update(b"\0");
        let mut entries = std::fs::read_dir(path)
            .map_err(|e| format!("read_dir {}: {e}", path.display()))?
            .collect::<Result<Vec<_>, _>>()
            .map_err(|e| format!("read_dir {}: {e}", path.display()))?;
        entries.sort_by_key(|entry| entry.path());
        for entry in entries {
            hash_build_input_entry(h, root, &entry.path())?;
        }
        return Ok(());
    }

    Err(format!(
        "build input {} is not a file, directory, or symlink",
        path.display()
    ))
}

/// Canonical cache directory for a resolved manifest.
///
/// Layout:
///   libs/programs: `<cache_root>/libs/<name>-<version>-rev<revision>-<arch>-<cache-key-sha>/`
///   sources:       `<cache_root>/sources/<name>-<version>-rev<revision>-<cache-key-sha>/`
///
/// The directory suffix is the complete 64-character cache-key SHA-256. Archive
/// filenames may use an eight-character transport label, but canonical local
/// cache identity must not collapse distinct keys that share that prefix. Cache
/// entries created by older resolvers with a short suffix become unused and are
/// rebuilt under the full-key path; they are not migrated or trusted in place.
///
/// For libs and programs, `arch` is part of the path so a single user
/// can host wasm32 and wasm64 builds of the same artifact side-by-side.
/// The cache-key sha already incorporates `arch` as of Task A.5, so the
/// full cache identity disambiguates — but a visible arch segment makes the
/// cache layout self-explanatory at a glance.
///
/// For source-kind manifests, the layout omits the arch segment per
/// design decision 6: source artifacts are arch-agnostic, so a single
/// cache entry serves both wasm32 and wasm64 consumers.
pub fn canonical_path(
    cache_root: &Path,
    m: &DepsManifest,
    arch: TargetArch,
    sha: &[u8; 32],
) -> PathBuf {
    let kind_subdir = match m.kind {
        ManifestKind::Library => "libs",
        ManifestKind::Program => "programs",
        ManifestKind::Source => "sources",
    };
    let basename = match m.kind {
        ManifestKind::Source => format!("{}-{}-rev{}-{}", m.name, m.version, m.revision, hex(sha)),
        ManifestKind::Library | ManifestKind::Program => format!(
            "{}-{}-rev{}-{}-{}",
            m.name,
            m.version,
            m.revision,
            arch.as_str(),
            hex(sha)
        ),
    };
    cache_root.join(kind_subdir).join(basename)
}

use crate::util::{hex, hex_to_32};

// ---------------------------------------------------------------------
// Build + cache-install
// ---------------------------------------------------------------------

/// Options controlling where the resolver reads from and writes to.
/// Kept as a struct so tests can pass tempdirs without reaching into
/// `$HOME` / `$XDG_CACHE_HOME`.
pub struct ResolveOpts<'a> {
    /// Resolution policy is part of both branch eligibility and cache identity.
    pub policy: ResolvePolicy,
    /// Canonical SourceOnlyV1 cache base. Default resolution requires this to
    /// remain absent; SourceOnlyV1 validates it as the exact owner of
    /// `cache_root` before doing any graph or cache work.
    pub source_cache_root: Option<&'a Path>,
    /// Authoritative root for this resolution. Source-build children receive
    /// its canonical absolute spelling as `WASM_POSIX_BINARY_CACHE_ROOT`, so
    /// nested resolvers cannot drift back to an unrelated ambient default.
    pub cache_root: &'a Path,
    /// Optional `local-libs/` directory. When a `<name>/build/`
    /// subdirectory exists under this root, it wins over the cache
    /// and the build script is not run.
    pub local_libs: Option<&'a Path>,
    /// Manifest names that must be source-built unconditionally, even
    /// on a cache hit. Used by the manual `force-rebuild` workflow to
    /// refresh a cache entry whose cache key is suspected stale.
    /// `None` means "no force rebuild" (the default for every consumer
    /// other than the manual workflow). `local_libs` still wins over
    /// force_source_build (a hand-patched override is always honored).
    /// A force rebuild assumes no concurrent resolver invocation for
    /// the same package -- see `build_into_cache`'s atomic-install comment.
    pub force_source_build: Option<&'a BTreeSet<String>>,
    /// Repo root used to resolve `[build].script_path` (which is
    /// repo-relative as of Phase A-bis Task 2). `None` means "use
    /// `crate::repo_root()`", which is the production default.
    /// Tests use this to point the resolver at a tempdir.
    pub repo_root: Option<&'a Path>,
    /// When `Some`, the resolver places `binaries/programs/<arch>/...`
    /// symlinks for every program manifest in the dep graph (target +
    /// transitive program deps). Required so a consumer's build
    /// script can find sibling-package binaries via `tryResolveBinary`
    /// after a `xtask build-deps resolve <name>` invocation. `None`
    /// disables symlink placement (test fixtures, library-only
    /// resolves, etc.).
    pub binaries_dir: Option<&'a Path>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum LocalBuildDisposition {
    Cached,
    Published,
    RebuiltEquivalent,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct LocalBuildNodeOutput {
    pub(crate) canonical: Option<PathBuf>,
    pub(crate) disposition: LocalBuildDisposition,
    pub(crate) package_receipt: Option<PackageNodeReceiptV1>,
}

fn exact_canonical_real_directory(path: &Path, label: &str) -> Result<PathBuf, String> {
    if !path.is_absolute() {
        return Err(format!(
            "{label} must be an absolute path: {}",
            path.display()
        ));
    }
    let metadata = std::fs::symlink_metadata(path)
        .map_err(|error| format!("inspect {label} {}: {error}", path.display()))?;
    if metadata.file_type().is_symlink() || !metadata.file_type().is_dir() {
        return Err(format!(
            "{label} must be an existing real directory: {}",
            path.display()
        ));
    }
    let canonical = std::fs::canonicalize(path)
        .map_err(|error| format!("canonicalize {label} {}: {error}", path.display()))?;
    if canonical.as_os_str() != path.as_os_str() {
        return Err(format!(
            "{label} must use its exact canonical spelling {}; got {}",
            canonical.display(),
            path.display(),
        ));
    }
    Ok(canonical)
}

pub(crate) fn validate_resolve_cache_pair(
    opts: &ResolveOpts<'_>,
) -> Result<Option<SourceOnlyCacheRoots>, String> {
    match opts.policy {
        ResolvePolicy::Default => {
            if opts.source_cache_root.is_some() {
                return Err("default resolution must not receive a source-cache base".to_string());
            }
            Ok(None)
        }
        ResolvePolicy::SourceOnlyV1 => {
            let base = opts.source_cache_root.ok_or_else(|| {
                "source-only resolution requires an explicit canonical source-cache base"
                    .to_string()
            })?;
            let base = exact_canonical_real_directory(base, "source-only source-cache base")?;
            let compiled =
                exact_canonical_real_directory(opts.cache_root, "source-only compiled cache root")?;
            let expected = base.join("source-only-v1/compiled");
            if compiled != expected {
                return Err(format!(
                    "source-only compiled cache must be exactly {}; got {}",
                    expected.display(),
                    compiled.display(),
                ));
            }
            Ok(Some(SourceOnlyCacheRoots { base, compiled }))
        }
    }
}

#[cfg(unix)]
struct SourceOnlyPackageAuthority {
    manifest: DepsManifest,
    manifest_sha256: String,
    cache_key_sha256: String,
    /// Digest of the entry's content-addressed receipt. In `--verify-cache`
    /// mode this is recomputed from a freshly hashed `cache_snapshot`; on the
    /// trusted path it is read from the persisted receipt sidecar (or computed
    /// once when that sidecar is absent for a pre-existing entry).
    cache_receipt_sha256: String,
    /// Present only when the entry was fully re-hashed this run
    /// (`--verify-cache`); `None` on the trusted path, which skips the
    /// whole-tree hash while still enforcing declared-output/wasm/provenance
    /// correctness.
    cache_snapshot: Option<CacheEntrySnapshot>,
    cache_root: AnchoredDirectory,
}

#[cfg(unix)]
fn capture_source_only_package_authority(
    target: &DepsManifest,
    registry: &Registry,
    canonical: &Path,
    roots: &SourceOnlyCacheRoots,
    arch: TargetArch,
    abi_version: u32,
    verify_cache: bool,
) -> Result<SourceOnlyPackageAuthority, String> {
    let manifest_path = target.dir.join("package.toml");
    let manifest_before = stable_package_manifest_sha256(&manifest_path)?;
    let manifest = registry.load(&target.name).map_err(|error| {
        format!("{}: reload source-only package authority: {error}", target.spec())
    })?;
    if manifest.dir != target.dir {
        return Err(format!(
            "{}: registry authority moved from {} to {} while resolving the selected node",
            target.spec(),
            target.dir.display(),
            manifest.dir.display()
        ));
    }
    let cache_key = compute_sha_for_policy(
        &manifest,
        registry,
        arch,
        abi_version,
        ResolvePolicy::SourceOnlyV1,
        &mut BTreeMap::new(),
        &mut Vec::new(),
    )?;
    let cache_key_sha256 = hex(&cache_key);
    let expected_canonical = canonical_path(&roots.compiled, &manifest, arch, &cache_key);
    if canonical != expected_canonical {
        return Err(format!(
            "{}: resolved source-only cache path {} does not equal expected canonical {}",
            target.spec(),
            canonical.display(),
            expected_canonical.display(),
        ));
    }
    let parent_guard = SourceOnlyCacheParentGuard::prepare(&roots.compiled, canonical)?;
    parent_guard.validate()?;
    let (cache_snapshot, cache_receipt_sha256): (Option<CacheEntrySnapshot>, String) = if verify_cache
    {
        let snapshot = capture_source_only_cache_entry_snapshot(
            &manifest,
            &parent_guard,
            canonical,
            arch,
            abi_version,
            &cache_key_sha256,
        )
        .map_err(|error| {
            format!(
                "{}: resolved source-only cache entry failed stable admission and was preserved at {}: {error}",
                target.spec(),
                canonical.display(),
            )
        })?;
        let sha = cache_receipt_sha256(&snapshot.receipt)?;
        (Some(snapshot), sha)
    } else {
        // Trusted path: enforce declared-output/wasm/provenance correctness
        // without the whole-tree content re-hash, and take the receipt digest
        // from the persisted sidecar. A pre-existing entry with no sidecar is
        // hashed once here so later runs are cheap.
        if !source_only_cache_entry_is_trusted(
            &manifest,
            canonical,
            arch,
            abi_version,
            &cache_key_sha256,
        )? {
            return Err(format!(
                "{}: trusted source-only cache entry vanished before capture at {}",
                target.spec(),
                canonical.display(),
            ));
        }
        match read_source_only_cache_receipt(canonical, &cache_key_sha256)? {
            Some(receipt) => (None, receipt.cache_receipt_sha256),
            None => {
                let snapshot = capture_source_only_cache_entry_snapshot(
                    &manifest,
                    &parent_guard,
                    canonical,
                    arch,
                    abi_version,
                    &cache_key_sha256,
                )
                .map_err(|error| {
                    format!(
                        "{}: resolved source-only cache entry failed stable admission and was preserved at {}: {error}",
                        target.spec(),
                        canonical.display(),
                    )
                })?;
                let sha = cache_receipt_sha256(&snapshot.receipt)?;
                (None, sha)
            }
        }
    };
    parent_guard.validate()?;
    let (_, cache_root, root_at) = parent_guard.open_canonical_entry(canonical)?;
    if let Some(snapshot) = &cache_snapshot {
        if cache_root.identity != snapshot.identity || root_at.identity != snapshot.identity {
            return Err(format!(
                "{}: canonical cache generation changed after stable admission",
                target.spec()
            ));
        }
    }
    let manifest_after = stable_package_manifest_sha256(&manifest_path)?;
    let reloaded = registry.load(&target.name).map_err(|error| {
        format!("{}: recheck source-only package authority: {error}", target.spec())
    })?;
    let key_after = compute_sha_for_policy(
        &reloaded,
        registry,
        arch,
        abi_version,
        ResolvePolicy::SourceOnlyV1,
        &mut BTreeMap::new(),
        &mut Vec::new(),
    )?;
    if manifest_before != manifest_after
        || reloaded.dir != manifest.dir
        || key_after != cache_key
    {
        return Err(format!(
            "{}: package manifest/cache identity changed while source-only authority was captured",
            target.spec()
        ));
    }
    Ok(SourceOnlyPackageAuthority {
        manifest,
        manifest_sha256: manifest_before,
        cache_key_sha256,
        cache_receipt_sha256,
        cache_snapshot,
        cache_root,
    })
}

#[cfg(unix)]
fn require_same_source_only_package_authority(
    target: &DepsManifest,
    expected: &SourceOnlyPackageAuthority,
    actual: &SourceOnlyPackageAuthority,
    phase: &str,
) -> Result<(), String> {
    if actual.manifest_sha256 != expected.manifest_sha256
        || actual.cache_key_sha256 != expected.cache_key_sha256
        || actual.cache_receipt_sha256 != expected.cache_receipt_sha256
        || actual.cache_snapshot != expected.cache_snapshot
        || actual.cache_root.identity != expected.cache_root.identity
        || actual.cache_root.path != expected.cache_root.path
    {
        return Err(format!(
            "{}: source-only package/cache generation changed {phase}; refusing an incoherent package receipt",
            target.spec()
        ));
    }
    Ok(())
}

/// Cheap SourceOnlyV1 cache-hit trust check for the default (no `--verify-cache`)
/// path. Confirms the canonical entry exists (no-follow) and its provenance
/// marker matches the expected identity, without hashing any artifact bytes.
///
/// Returns `Ok(false)` for a plain cache miss (an absent entry, which must be
/// built) and an error only when an existing entry's provenance is corrupt or
/// mismatched. It never reports a trusted hit it did not verify: the content
/// address (the canonical directory name) already binds every declared input,
/// so a changed input yields a different key and a different, absent path.
#[cfg(unix)]
pub(crate) fn source_only_cache_entry_is_trusted(
    target: &DepsManifest,
    canonical: &Path,
    arch: TargetArch,
    abi_version: u32,
    cache_key_sha: &str,
) -> Result<bool, String> {
    if !path_entry_exists(canonical)? {
        return Ok(false);
    }
    // Preserve the real correctness guarantees the full snapshot would enforce
    // (declared-output shape and the wasm/fork-instrumentation/ABI policy that
    // rejects stale asyncify or legacy fork exports, plus provenance identity)
    // while skipping only the O(output-bytes) whole-tree content re-hash.
    validate_cache_entry(target, canonical, arch, abi_version, cache_key_sha)?;
    Ok(true)
}

/// Resolver-owned sidecar recording the full package receipt of a materialized
/// SourceOnlyV1 cache entry, stored beside (never inside) the entry like the
/// provenance marker. The trusted local-build fast path reads its
/// `cache_receipt_sha256` instead of re-hashing the whole entry tree, and the
/// scheduler reads the whole receipt to skip launching a child for an unchanged
/// node; `--verify-cache` recomputes and rewrites it. Entries built before this
/// record existed simply lack it, so the trusted path recomputes and persists
/// it once. The receipt's `materialized_members` are a deterministic function
/// of the content-addressed entry, so a persisted receipt describes the same
/// projection any rebuild would produce.
const SOURCE_ONLY_CACHE_RECEIPT_SCHEMA: u32 = 2;

#[derive(serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct SourceOnlyCacheReceiptMarker {
    schema: u32,
    receipt: PackageNodeReceiptV1,
}

#[cfg(unix)]
pub(crate) fn source_only_cache_receipt_path(
    canonical: &Path,
    cache_key_sha: &str,
) -> Result<PathBuf, String> {
    let parent = canonical.parent().ok_or_else(|| {
        format!(
            "canonical cache path has no parent for receipt: {}",
            canonical.display()
        )
    })?;
    let basename = canonical
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| {
            format!(
                "canonical cache path has no UTF-8 name: {}",
                canonical.display()
            )
        })?;
    if !basename.ends_with(&format!("-{cache_key_sha}")) {
        return Err(format!(
            "canonical cache path {} does not end in its full cache key {cache_key_sha}",
            canonical.display()
        ));
    }
    Ok(parent.join(format!(".{basename}.kandelo-receipt.json")))
}

#[cfg(unix)]
pub(crate) fn write_source_only_cache_receipt(
    canonical: &Path,
    receipt: &PackageNodeReceiptV1,
) -> Result<(), String> {
    let path = source_only_cache_receipt_path(canonical, &receipt.cache_key_sha256)?;
    let marker = SourceOnlyCacheReceiptMarker {
        schema: SOURCE_ONLY_CACHE_RECEIPT_SCHEMA,
        receipt: receipt.clone(),
    };
    let body = serde_json::to_vec(&marker)
        .map_err(|error| format!("serialize source-only cache receipt marker: {error}"))?;
    let parent = path.parent().ok_or_else(|| {
        format!(
            "source-only cache receipt path has no parent: {}",
            path.display()
        )
    })?;
    let temp = parent.join(format!(".kandelo-receipt-tmp-{}", std::process::id()));
    std::fs::write(&temp, &body).map_err(|error| {
        format!(
            "write source-only cache receipt {}: {error}",
            temp.display()
        )
    })?;
    std::fs::rename(&temp, &path).map_err(|error| {
        let _ = std::fs::remove_file(&temp);
        format!(
            "publish source-only cache receipt {}: {error}",
            path.display()
        )
    })?;
    Ok(())
}

#[cfg(unix)]
pub(crate) fn read_source_only_cache_receipt(
    canonical: &Path,
    cache_key_sha: &str,
) -> Result<Option<PackageNodeReceiptV1>, String> {
    let path = source_only_cache_receipt_path(canonical, cache_key_sha)?;
    let body = match std::fs::read(&path) {
        Ok(body) => body,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => {
            return Err(format!(
                "read source-only cache receipt {}: {error}",
                path.display()
            ));
        }
    };
    let marker: SourceOnlyCacheReceiptMarker = serde_json::from_slice(&body).map_err(|error| {
        format!(
            "parse source-only cache receipt {}: {error}",
            path.display()
        )
    })?;
    if marker.schema != SOURCE_ONLY_CACHE_RECEIPT_SCHEMA {
        return Err(format!(
            "source-only cache receipt {} has unsupported schema {}",
            path.display(),
            marker.schema
        ));
    }
    if marker.receipt.cache_key_sha256 != cache_key_sha {
        return Err(format!(
            "source-only cache receipt {} records cache key {} but {cache_key_sha} was requested",
            path.display(),
            marker.receipt.cache_key_sha256,
        ));
    }
    Ok(Some(marker.receipt))
}

/// If a compiled SourceOnlyV1 node is unchanged, return its persisted receipt so
/// the scheduler can report it `Cached` without launching a child process.
///
/// "Unchanged" is decided entirely by the content-addressed cache key (which
/// folds every declared input, including transitive dependency keys): a changed
/// input yields a different key and a different, absent canonical path. The node
/// qualifies only when its entry is present and passes the trusted validation
/// (declared-output shape + wasm/fork/ABI policy + provenance, no whole-tree
/// re-hash), its receipt sidecar is present, and every projected member the
/// receipt claims is present in `output_root`. Any uncertainty — a missing
/// entry, absent or unreadable sidecar, corrupt provenance, or a missing
/// projected file — returns `None` so the authoritative child path runs. It
/// therefore never reports a node cached that a build would have changed.
#[cfg(unix)]
pub(crate) fn source_only_skip_receipt_if_clean(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    abi_version: u32,
    roots: &SourceOnlyCacheRoots,
    output_root: &Path,
    memo: &mut BTreeMap<String, [u8; 32]>,
) -> Option<PackageNodeReceiptV1> {
    if target.kind == ManifestKind::Source {
        return None;
    }
    let sha = compute_sha_for_policy(
        target,
        registry,
        arch,
        abi_version,
        ResolvePolicy::SourceOnlyV1,
        memo,
        &mut Vec::new(),
    )
    .ok()?;
    let cache_key_sha256 = hex(&sha);
    let canonical = canonical_path(&roots.compiled, target, arch, &sha);
    // Cheap identity check only: the entry exists and its provenance marker
    // matches. Deliberately NOT the full `validate_cache_entry` (which reads and
    // parses every declared wasm) — this pre-pass runs serially over the whole
    // graph, so re-parsing wasms here would cost more than the parallel children
    // it replaces. A present entry with a present receipt sidecar was already
    // fully validated when built, and its content-addressed key means the bytes
    // (and thus the wasm-policy result) cannot have changed without the key
    // changing; `--verify-cache` re-runs the full check.
    if !path_entry_exists(&canonical).unwrap_or(false) {
        return None;
    }
    if validate_cache_provenance(target, &canonical, arch, abi_version, &cache_key_sha256).is_err() {
        return None;
    }
    let receipt = read_source_only_cache_receipt(&canonical, &cache_key_sha256)
        .ok()
        .flatten()?;
    for member in &receipt.materialized_members {
        let projected = output_root.join(&member.mirror_path);
        let metadata = match std::fs::symlink_metadata(&projected) {
            Ok(meta) if meta.is_file() => meta,
            _ => return None,
        };
        // A present file at the mirror path is not proof it holds THIS
        // generation's bytes: this skip fast path runs before any per-node
        // child launches, so it is the only gate standing between a stale
        // projection and a "Cached" disposition. A file can already sit at
        // `mirror_path` from a DIFFERENT cache-key generation that once
        // occupied the same output path -- e.g. a source edit that changed
        // the package's cache key, got projected here, and was later
        // reverted so the current tree resolves back to an OLDER key whose
        // canonical cache entry still exists but whose mirrored copy was
        // never re-materialized. Matching file size is not sufficient (two
        // generations of the same wasm can be byte-for-byte the same length
        // while differing only in embedded content), so re-hash the file
        // and compare against the receipt's recorded digest -- the same
        // digest `materialize_source_only_program_target_with_cache_root`
        // computed when it wrote this member. Only an exact content match
        // proves the mirror is this generation's output; anything else
        // falls back to the real per-node resolve, which unconditionally
        // re-projects from the canonical cache entry.
        if metadata.len() != member.size {
            return None;
        }
        let bytes = std::fs::read(&projected).ok()?;
        let actual_sha256 = hex(&Sha256::digest(&bytes));
        if actual_sha256 != member.sha256 {
            return None;
        }
    }
    Some(receipt)
}

/// Resolve exactly one scheduler-selected node under SourceOnlyV1. Compiled
/// dependencies are admission checks only: a missing prerequisite is a
/// scheduler invariant violation, never permission to recursively build it.
#[cfg(unix)]
pub(crate) fn resolve_local_build_package_node(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    abi_version: u32,
    roots: &SourceOnlyCacheRoots,
    repo_root: &Path,
    output_root: &Path,
    rebuild: bool,
    before_projection: &mut dyn FnMut() -> Result<(), String>,
) -> Result<LocalBuildNodeOutput, String> {
    resolve_local_build_package_node_with_projection_hooks(
        target,
        registry,
        arch,
        abi_version,
        roots,
        repo_root,
        output_root,
        rebuild,
        true,
        before_projection,
        &mut |_| {},
    )
}

/// Resolve one scheduler-selected node under SourceOnlyV1, choosing whether to
/// re-verify an existing cache entry by re-hashing its contents (`verify_cache`)
/// or to trust the content-addressed key plus provenance and skip the redundant
/// re-captures. The trusted path is the local-build default; `--verify-cache`
/// opts back into full per-run re-verification.
#[cfg(unix)]
pub(crate) fn resolve_local_build_package_node_with_cache_policy(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    abi_version: u32,
    roots: &SourceOnlyCacheRoots,
    repo_root: &Path,
    output_root: &Path,
    rebuild: bool,
    verify_cache: bool,
    before_projection: &mut dyn FnMut() -> Result<(), String>,
) -> Result<LocalBuildNodeOutput, String> {
    resolve_local_build_package_node_with_projection_hooks(
        target,
        registry,
        arch,
        abi_version,
        roots,
        repo_root,
        output_root,
        rebuild,
        verify_cache,
        before_projection,
        &mut |_| {},
    )
}

#[cfg(unix)]
fn resolve_local_build_package_node_with_projection_hooks<AfterCopy>(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    abi_version: u32,
    roots: &SourceOnlyCacheRoots,
    repo_root: &Path,
    output_root: &Path,
    rebuild: bool,
    verify_cache: bool,
    before_projection: &mut dyn FnMut() -> Result<(), String>,
    after_copy: &mut AfterCopy,
) -> Result<LocalBuildNodeOutput, String>
where
    AfterCopy: FnMut(&Path),
{
    // Source nodes materialize verified upstream archives rather than compiled
    // package generations. `rebuild` therefore has no eligibility or
    // disposition meaning for them: a second lookup of the same verified
    // archive is a cache hit even when the aggregate invocation requested a
    // compiled rebuild.
    let forced = (rebuild && target.kind != ManifestKind::Source)
        .then(|| BTreeSet::from([target.name.clone()]));
    let opts = ResolveOpts {
        policy: ResolvePolicy::SourceOnlyV1,
        source_cache_root: Some(&roots.base),
        cache_root: &roots.compiled,
        local_libs: None,
        force_source_build: forced.as_ref(),
        repo_root: Some(repo_root),
        binaries_dir: None,
    };
    validate_resolve_cache_pair(&opts)?;
    let canonical_repo = exact_canonical_real_directory(repo_root, "local-build repository root")?;
    let _repo_root_override = if crate::repo_root() == canonical_repo {
        None
    } else {
        Some(crate::install_repo_root_override(canonical_repo.clone())?)
    };

    let permission = BuildPermission::TargetOnly {
        package_name: target.name.clone(),
        target_arch: arch,
    };
    let resolved = ensure_built_inner(
        target,
        registry,
        arch,
        abi_version,
        &opts,
        &mut BTreeMap::new(),
        &mut Vec::new(),
        &permission,
        verify_cache,
    )?;
    let canonical = match &resolved.materialization {
        NodeMaterialization::VerifiedSourceArchive {
            archive,
            source_url,
            sha256,
            ..
        } => {
            before_projection().map_err(|error| {
                format!(
                    "{}: post-source-work admission failed before reporting success: {error}",
                    target.spec()
                )
            })?;
            let reverified = source_archive_cache::require_verified_archive_hit(
                &roots.base,
                source_url,
                sha256,
                archive,
            )
            .map_err(|error| {
                format!(
                    "{}: verified source archive changed after post-work admission: {error}",
                    target.spec()
                )
            })?;
            if &reverified != archive {
                return Err(format!(
                    "{}: verified source archive changed canonical payload after post-work admission: {} != {}",
                    target.spec(),
                    archive.display(),
                    reverified.display()
                ));
            }
            return Ok(LocalBuildNodeOutput {
                canonical: None,
                disposition: resolved.disposition,
                package_receipt: None,
            });
        }
        NodeMaterialization::CompiledDir(path) => path.clone(),
    };
    let authority = capture_source_only_package_authority(
        target,
        registry,
        &canonical,
        roots,
        arch,
        abi_version,
        verify_cache,
    )?;
    before_projection().map_err(|error| {
        format!(
            "{}: post-build admission failed before source-only projection: {error}",
            target.spec()
        )
    })?;
    // The content-addressed cache key already binds every declared input, so a
    // changed input yields a different key and a different, absent canonical
    // path. The before/during/after re-captures below re-hash the same immutable
    // cache entry solely to detect an out-of-band mutation of the cache while a
    // projection is in flight. That per-run re-hash dominates the cost of an
    // otherwise all-cached build, so the trusted default skips it and
    // `--verify-cache` restores it.
    if verify_cache {
        let after_callback = capture_source_only_package_authority(
            target,
            registry,
            &canonical,
            roots,
            arch,
            abi_version,
            verify_cache,
        )?;
        require_same_source_only_package_authority(
            target,
            &authority,
            &after_callback,
            "before projection",
        )?;
    }
    let materialized_members = materialize_source_only_program_target_with_cache_root(
        &authority.manifest,
        &canonical,
        Some(&authority.cache_root),
        output_root,
        arch,
        after_copy,
        &mut |_| {
            if !verify_cache {
                return Ok(());
            }
            let current = capture_source_only_package_authority(
                target,
                registry,
                &canonical,
                roots,
                arch,
                abi_version,
                verify_cache,
            )?;
            require_same_source_only_package_authority(
                target,
                &authority,
                &current,
                "at the live projection boundary",
            )
        },
    )?;
    if verify_cache {
        let after_projection = capture_source_only_package_authority(
            target,
            registry,
            &canonical,
            roots,
            arch,
            abi_version,
            verify_cache,
        )?;
        require_same_source_only_package_authority(
            target,
            &authority,
            &after_projection,
            "during projection",
        )?;
    }
    let package_receipt = PackageNodeReceiptV1 {
        manifest_sha256: authority.manifest_sha256,
        cache_key_sha256: authority.cache_key_sha256,
        cache_receipt_sha256: authority.cache_receipt_sha256,
        materialized_members,
    };
    // Persist the receipt digest beside the entry so the trusted fast path can
    // read it next run instead of re-hashing the whole tree. Best-effort: a
    // failure here only forces the next run to recompute, never a wrong result.
    if let Err(error) = write_source_only_cache_receipt(&canonical, &package_receipt) {
        eprintln!(
            "{}: warning: persist source-only cache receipt: {error}",
            target.spec()
        );
    }
    let receipt_size = serde_json::to_vec(&package_receipt)
        .map_err(|error| format!("serialize package node receipt: {error}"))?
        .len();
    if receipt_size >= 64 * 1024 {
        return Err(format!(
            "{}: package node receipt is {receipt_size} bytes, exceeding the 64 KiB child-result budget",
            target.spec()
        ));
    }
    Ok(LocalBuildNodeOutput {
        canonical: Some(canonical),
        disposition: resolved.disposition,
        package_receipt: Some(package_receipt),
    })
}

#[cfg(not(unix))]
pub(crate) fn resolve_local_build_package_node(
    _target: &DepsManifest,
    _registry: &Registry,
    _arch: TargetArch,
    _abi_version: u32,
    _roots: &SourceOnlyCacheRoots,
    _repo_root: &Path,
    _output_root: &Path,
    _rebuild: bool,
    _before_projection: &mut dyn FnMut() -> Result<(), String>,
) -> Result<LocalBuildNodeOutput, String> {
    Err("source-only local package execution requires Unix no-follow filesystem semantics".to_string())
}

#[cfg(not(unix))]
#[allow(clippy::too_many_arguments)]
pub(crate) fn resolve_local_build_package_node_with_cache_policy(
    _target: &DepsManifest,
    _registry: &Registry,
    _arch: TargetArch,
    _abi_version: u32,
    _roots: &SourceOnlyCacheRoots,
    _repo_root: &Path,
    _output_root: &Path,
    _rebuild: bool,
    _verify_cache: bool,
    _before_projection: &mut dyn FnMut() -> Result<(), String>,
) -> Result<LocalBuildNodeOutput, String> {
    Err("source-only local package execution requires Unix no-follow filesystem semantics".to_string())
}

/// Resolve a library to a concrete on-disk path with the artifacts
/// declared in its `package.toml`. Ensures dependencies are resolved
/// first (depth-first), then runs the build script if neither a
/// `local-libs/` override nor a cache hit is available.
///
/// Returns the path the consumer should point `CPPFLAGS=-I<p>/include
/// LDFLAGS=-L<p>/lib` at.
pub fn ensure_built(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    abi_version: u32,
    opts: &ResolveOpts<'_>,
) -> Result<PathBuf, String> {
    validate_resolve_cache_pair(opts)?;
    if opts.policy == ResolvePolicy::SourceOnlyV1 && target.kind == ManifestKind::Source {
        return Err(format!(
            "{}: source nodes are dependency inputs and have no durable extracted output",
            target.spec(),
        ));
    }
    let mut memo: BTreeMap<String, [u8; 32]> = BTreeMap::new();
    let mut building: Vec<String> = Vec::new();
    let resolved = ensure_built_inner(
        target,
        registry,
        arch,
        abi_version,
        opts,
        &mut memo,
        &mut building,
        &BuildPermission::Recursive,
        true,
    )?;
    require_compiled_dir(&resolved, &target.name, "public resolver output").map(Path::to_path_buf)
}

/// One package in a dependency graph after architecture fallback is applied.
///
/// Package name plus resolved target architecture is the canonical node
/// identity. Manifest kind is graph metadata rather than part of identity.
#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
pub(crate) struct ResolvedDependencyNode {
    pub(crate) package_name: String,
    pub(crate) target_arch: TargetArch,
}

/// The complete resolved dependency graph for one package/architecture root.
///
/// Direct edges are stored as `(dependency, dependent)` so consumers can feed
/// them directly into dependency-first topological scheduling. Source-kind
/// nodes remain present even though they are not compiled package nodes.
#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct ResolvedDependencyGraph {
    pub(crate) nodes: BTreeMap<ResolvedDependencyNode, ManifestKind>,
    pub(crate) direct_edges: BTreeSet<(ResolvedDependencyNode, ResolvedDependencyNode)>,
}

/// Resolve through an already parsed fixed-registry snapshot. This keeps graph
/// planning on the exact bytes admitted by its caller while sharing the same
/// version, architecture, cycle, node, and edge traversal as the resolver.
pub(crate) fn resolved_dependency_graph_from_manifests(
    target: &DepsManifest,
    manifests: &BTreeMap<String, DepsManifest>,
    arch: TargetArch,
) -> Result<ResolvedDependencyGraph, String> {
    resolved_dependency_graph_with_loader(target, arch, &mut |name| {
        manifests
            .get(name)
            .cloned()
            .ok_or_else(|| format!("dep {name:?}: no package.toml found in fixed registry snapshot"))
    })
}

fn resolved_dependency_graph_with_loader<F>(
    target: &DepsManifest,
    arch: TargetArch,
    loader: &mut F,
) -> Result<ResolvedDependencyGraph, String>
where
    F: FnMut(&str) -> Result<DepsManifest, String>,
{
    fn visit<F>(
        target: &DepsManifest,
        arch: TargetArch,
        loader: &mut F,
        graph: &mut ResolvedDependencyGraph,
        visited: &mut BTreeSet<(String, TargetArch)>,
        chain: &mut Vec<String>,
    ) -> Result<(), String>
    where
        F: FnMut(&str) -> Result<DepsManifest, String>,
    {
        let identity = (target.name.clone(), arch);
        if visited.contains(&identity) {
            return Ok(());
        }
        if chain.iter().any(|name| name == &target.name) {
            return Err(format!(
                "cycle while collecting source closure: {} -> {}",
                chain.join(" -> "),
                target.name,
            ));
        }
        chain.push(target.name.clone());
        let target_node = ResolvedDependencyNode {
            package_name: target.name.clone(),
            target_arch: arch,
        };
        graph.nodes.insert(target_node.clone(), target.kind);
        for dependency in &target.depends_on {
            let manifest = loader(&dependency.name)?;
            if manifest.version != dependency.version {
                return Err(format!(
                    "{} depends on {}@{}, but registry has {}",
                    target.spec(),
                    dependency.name,
                    dependency.version,
                    manifest.spec(),
                ));
            }
            let dependency_arch = dependency_target_arch(target, &manifest, arch)?;
            let dependency_node = ResolvedDependencyNode {
                package_name: manifest.name.clone(),
                target_arch: dependency_arch,
            };
            graph
                .direct_edges
                .insert((dependency_node, target_node.clone()));
            visit(&manifest, dependency_arch, loader, graph, visited, chain)?;
        }
        chain.pop();
        visited.insert(identity);
        Ok(())
    }

    let mut graph = ResolvedDependencyGraph {
        nodes: BTreeMap::new(),
        direct_edges: BTreeSet::new(),
    };
    let mut visited = BTreeSet::new();
    let mut chain = Vec::new();
    visit(target, arch, loader, &mut graph, &mut visited, &mut chain)?;
    Ok(graph)
}

fn dependency_target_arch(
    parent: &DepsManifest,
    dependency: &DepsManifest,
    requested: TargetArch,
) -> Result<TargetArch, String> {
    canonical_package_target_arch(dependency, requested).ok_or_else(|| {
        format!(
            "{} depends on {} (arch {}), but {} declares neither {} nor wasm32 in target_arches (declared: {:?})",
            parent.spec(),
            dependency.spec(),
            requested.as_str(),
            dependency.spec(),
            requested.as_str(),
            dependency
                .target_arches
                .iter()
                .map(|arch| arch.as_str())
                .collect::<Vec<_>>(),
        )
    })
}

/// Apply the resolver's canonical architecture selection rule to one package:
/// prefer the exact request, otherwise use its declared wasm32 compatibility
/// target. Callers retain ownership of their contextual error.
pub(crate) fn canonical_package_target_arch(
    package: &DepsManifest,
    requested: TargetArch,
) -> Option<TargetArch> {
    if package.target_arches.contains(&requested) {
        Some(requested)
    } else if package.target_arches.contains(&TargetArch::Wasm32) {
        Some(TargetArch::Wasm32)
    } else {
        None
    }
}

/// One direct dependency's resolved cache path plus its manifest kind.
///
/// Carried alongside `dep_dirs` so the build-script env-var emission
/// can switch the suffix per design 12: library/program deps export
/// under `WASM_POSIX_DEP_<NAME>_DIR` (a built-artifact root), source
/// deps under `WASM_POSIX_DEP_<NAME>_SRC_DIR` (an unbuilt source tree).
struct DirectDep {
    materialization: NodeMaterialization,
    kind: ManifestKind,
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum NodeMaterialization {
    CompiledDir(PathBuf),
    VerifiedSourceArchive {
        archive: PathBuf,
        source_url: String,
        sha256: String,
        extract_exclude_members: Vec<String>,
    },
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ResolvedNode {
    materialization: NodeMaterialization,
    transitive_compiled_dirs: BTreeSet<PathBuf>,
    disposition: LocalBuildDisposition,
}

impl ResolvedNode {
    fn compiled(path: PathBuf, transitive_compiled_dirs: BTreeSet<PathBuf>) -> Self {
        Self::compiled_with_disposition(
            path,
            transitive_compiled_dirs,
            LocalBuildDisposition::Cached,
        )
    }

    fn compiled_with_disposition(
        path: PathBuf,
        transitive_compiled_dirs: BTreeSet<PathBuf>,
        disposition: LocalBuildDisposition,
    ) -> Self {
        Self {
            materialization: NodeMaterialization::CompiledDir(path),
            transitive_compiled_dirs,
            disposition,
        }
    }
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
enum BuildPermission {
    Recursive,
    TargetOnly {
        package_name: String,
        target_arch: TargetArch,
    },
}

impl BuildPermission {
    fn permits_compiled_recipe(&self, target: &DepsManifest, arch: TargetArch) -> bool {
        match self {
            Self::Recursive => true,
            Self::TargetOnly {
                package_name,
                target_arch,
            } => package_name == &target.name && *target_arch == arch,
        }
    }
}

fn require_compiled_dir<'a>(
    resolved: &'a ResolvedNode,
    package_name: &str,
    operation: &str,
) -> Result<&'a Path, String> {
    match &resolved.materialization {
        NodeMaterialization::CompiledDir(path) => Ok(path),
        NodeMaterialization::VerifiedSourceArchive { .. } => Err(format!(
            "internal resolver error: package {package_name:?} has a verified source archive, not a compiled directory, for {operation}",
        )),
    }
}

/// Render a multi-tool probe-failure message for `ensure_built_inner`.
///
/// Aggregates every `ProbeFailure` for `target` into one `Err(String)`
/// payload so a user fixes their toolchain in a single round-trip
/// rather than `cargo run`-ing once per missing tool. For each failure
/// we look up the matching `[[host_tools]]` declaration and append the
/// platform-keyed install hint chosen by `cfg!(target_os)`. If the
/// declaration ships hints but none for the current OS, we list which
/// platforms ARE covered so the user knows whether to translate one
/// or to file an issue.
/// Map Rust's `std::env::consts::OS` to the conventional platform key
/// used in `[[host_tools]].install_hints`. The deps-management package-system
/// schema uses unix-y names (`darwin` for macOS, matching bash and
/// `uname`); Rust's runtime constant is `"macos"`. Other names match
/// what users would expect (`linux`, `windows`, `freebsd`, etc.).
fn install_hints_key_for_current_os() -> &'static str {
    match std::env::consts::OS {
        "macos" => "darwin",
        other => other,
    }
}

fn render_probe_failures(target: &DepsManifest, failures: &[ProbeFailure]) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "{}: {} host-tool requirement{} unsatisfied:\n",
        target.spec(),
        failures.len(),
        if failures.len() == 1 { "" } else { "s" }
    ));
    for f in failures {
        out.push_str(&format!("  - {f}\n"));
        let tool_name = match f {
            ProbeFailure::Missing { tool, .. }
            | ProbeFailure::BadOutput { tool, .. }
            | ProbeFailure::BadVersion { tool, .. }
            | ProbeFailure::TooOld { tool, .. } => tool,
        };
        if let Some(decl) = target
            .host_tools
            .iter()
            .find(|d: &&HostTool| &d.name == tool_name)
        {
            let os = install_hints_key_for_current_os();
            if let Some(hint) = decl.install_hints.get(os) {
                out.push_str(&format!("      install hint ({os}): {hint}\n"));
            } else if !decl.install_hints.is_empty() {
                let keys: Vec<&str> = decl.install_hints.keys().map(String::as_str).collect();
                out.push_str(&format!(
                    "      no {os} install hint; available platforms: [{}]\n",
                    keys.join(", ")
                ));
            }
        }
    }
    out
}

/// Process-lifetime memo of `(name, arch, exact cache identity) →
/// ensure_built_uncached`'s result. Within a single `xtask` invocation (e.g. one
/// `archive-stage` run, or a `build-deps resolve` walk that pulls a
/// shared dep transitively), a manifest reached via multiple dependents
/// (mariadb is reached 6× during a force-rebuild-all: directly + via
/// lamp + via mariadb-test + via mariadb-vfs ×2) otherwise re-runs its
/// full source build N times — ~80 minutes of pointless work for
/// mariadb alone. The memo collapses that to one build per
/// `(name, arch)`.
///
/// Caches BOTH `Ok` (so subsequent dependents reuse the resolved
/// path) and `Err` (so a failed manifest doesn't waste 10 more
/// minutes per dependent re-discovering the same failure). Cycle
/// errors are intentionally NOT cached — those depend on the call
/// stack at the moment of detection, and caching them could leak a
/// stale cycle result into a later acyclic traversal.
///
/// Lifetime: process-only. A fresh xtask invocation starts with an
/// empty memo, which keeps CI semantics intact (every run from
/// scratch retries any failures).
///
/// Key dimensions:
/// * `cache_root` — same process can host independent test cases
///   (cargo runs tests in parallel within one process; each test
///   uses a fresh tempdir). In production there's only ever one
///   cache_root per run, so this dimension is invisible to the
///   force-rebuild path.
/// * `name` — the manifest's identifier within its registry.
/// * `arch` — wasm32 vs wasm64. The same name builds independently
///   per-arch.
/// * `cache_identity` — the full recipe/dependency/toolchain digest computed
///   from the current registry. This prevents a result from surviving a
///   build.toml edit or being reused for a same-named package from another
///   registry inside one long-lived process.
/// * `was_force_rebuild` — `force_source_build` bypasses the
///   on-disk cache. Memoizing across the force-rebuild boundary
///   would mean a no-force result satisfies a later force request,
///   defeating the bypass intent. Keep them as separate slots so
///   a force-call after a no-force-call still rebuilds. In
///   a force-rebuild-all loop every call has the same flag, so the
///   memo collapses N calls per (name, arch) into 1 build — the
///   actual optimization we wanted.
type BuildMemoKey = (
    PathBuf,
    String,
    TargetArch,
    ResolvePolicy,
    [u8; 32],
    bool,
    BuildPermission,
);
type BuildMemoValue = Result<ResolvedNode, String>;

fn build_memo() -> &'static Mutex<BTreeMap<BuildMemoKey, BuildMemoValue>> {
    static MEMO: OnceLock<Mutex<BTreeMap<BuildMemoKey, BuildMemoValue>>> = OnceLock::new();
    MEMO.get_or_init(|| Mutex::new(BTreeMap::new()))
}

/// Cycle-error sentinel — these errors must NOT be memoized because
/// they describe the call stack at detection time, not a property of
/// the manifest. A later acyclic call for the same node should be
/// allowed to proceed.
fn is_cycle_error(e: &str) -> bool {
    e.starts_with("cycle while building:")
}

/// Fast path for archive-only resolver callers.
///
/// Browser/dev-server preparation needs to materialize self-contained program
/// archives into `binaries/`. If one of those programs has a stale or corrupt
/// dependency archive, resolving dependencies first can incorrectly force a
/// source build even though the target archive itself is valid. Keep normal
/// source-build resolution unchanged, but allow program archive fetches in
/// binary-materialization mode to satisfy the request before walking deps.
///
/// Fetch-only CI materialization is stricter: it accepts only a valid cache
/// entry or prebuilt archive for the target package and never falls through to
/// dependency resolution/source builds.
fn try_fetch_without_deps(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    abi_version: u32,
    opts: &ResolveOpts<'_>,
    memo: &mut BTreeMap<String, [u8; 32]>,
) -> Result<Option<PathBuf>, String> {
    if opts.policy == ResolvePolicy::SourceOnlyV1 {
        return Ok(None);
    }
    let binary_materialization_fast_path = opts.binaries_dir.is_some()
        && matches!(target.kind, ManifestKind::Program)
        && !target.program_outputs.is_empty();
    if !binary_materialization_fast_path
        || !matches!(target.kind, ManifestKind::Library | ManifestKind::Program)
    {
        return Ok(None);
    }

    let force_rebuild = opts
        .force_source_build
        .map(|s| s.contains(&target.name))
        .unwrap_or(false);
    if force_rebuild {
        return Ok(None);
    }

    if let Some(lr) = opts.local_libs {
        let override_dir = lr.join(&target.name).join("build");
        if override_dir.is_dir() {
            return Ok(Some(override_dir));
        }
    }

    let mut chain: Vec<String> = Vec::new();
    let sha = compute_sha_for_policy(
        target,
        registry,
        arch,
        abi_version,
        opts.policy,
        memo,
        &mut chain,
    )?;
    let canonical = canonical_path(opts.cache_root, target, arch, &sha);
    let cache_key_sha_hex = hex(&sha);
    if canonical.is_dir() {
        match validate_cache_entry(target, &canonical, arch, abi_version, &cache_key_sha_hex) {
            Ok(()) => return Ok(Some(canonical)),
            Err(e) => {
                eprintln!(
                    "warning: ignoring stale cached artifact for {} at {} ({})",
                    target.spec(),
                    canonical.display(),
                    e,
                );
                remove_cache_entry(&canonical, &cache_key_sha_hex).map_err(|remove_err| {
                    format!(
                        "clear stale cache entry {} after validation failure: {remove_err}",
                        canonical.display()
                    )
                })?;
            }
        }
    }

    // Local-first: no remote binary channel. A cache miss here simply falls
    // through to a source build in the caller.
    Ok(None)
}

/// Resolve `target`, returning its on-disk path *and* the set of
/// transitively-resolved lib paths underneath it (its direct deps, their
/// deps, and so on — but NOT `target`'s own path; the caller adds that).
///
/// The transitive set lets the caller compose
/// `WASM_POSIX_DEP_PKG_CONFIG_PATH` for the build script: every node
/// gets every descendant's `lib/pkgconfig/` dir, which mirrors how
/// pkg-config follows `Requires.private` chains.
///
/// Deduped via `BTreeSet` so a diamond dep (`libZ -> {libA, libB} ->
/// libCommon`) only contributes `libCommon`'s path once.
fn ensure_built_inner(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    abi_version: u32,
    opts: &ResolveOpts<'_>,
    memo: &mut BTreeMap<String, [u8; 32]>,
    building: &mut Vec<String>,
    build_permission: &BuildPermission,
    verify_cache: bool,
) -> Result<ResolvedNode, String> {
    // Process-lifetime memo: the same (name, arch) often gets
    // requested multiple times within one resolver run via different
    // dep chains. Without this, mariadb wasm32 source-builds 4 times
    // in a single force-rebuild-all (lamp, mariadb, mariadb-test,
    // mariadb-vfs each independently demand it). See `build_memo`'s
    // doc comment for full rationale.
    // Compute the exact current identity before consulting the process memo.
    // `ensure_built()` supplies a fresh hash memo for every top-level call, so
    // an in-process build.toml edit cannot inherit the prior call's digest;
    // recursive lookups in one unchanged graph remain cheap memo hits.
    let mut identity_chain = Vec::new();
    let cache_identity = compute_sha_for_policy(
        target,
        registry,
        arch,
        abi_version,
        opts.policy,
        memo,
        &mut identity_chain,
    )?;
    let was_force_rebuild = opts
        .force_source_build
        .map(|s| s.contains(&target.name))
        .unwrap_or(false);
    let memo_key: BuildMemoKey = (
        opts.cache_root.to_path_buf(),
        target.name.clone(),
        arch,
        opts.policy,
        cache_identity,
        was_force_rebuild,
        build_permission.clone(),
    );
    if !matches!(build_permission, BuildPermission::TargetOnly { .. }) {
        let cache = build_memo().lock().unwrap();
        if let Some(cached) = cache.get(&memo_key) {
            let mut cached = cached.clone();
            if !was_force_rebuild || target.kind == ManifestKind::Source {
                if let Ok(resolved) = &mut cached {
                    resolved.disposition = LocalBuildDisposition::Cached;
                }
            }
            return cached;
        }
    }

    let result = ensure_built_uncached(
        target,
        registry,
        arch,
        abi_version,
        opts,
        memo,
        building,
        build_permission,
        verify_cache,
    );

    // Don't poison the cache with cycle errors — those reflect the
    // call stack at the moment of detection, not a stable property
    // of the manifest. Everything else (Ok path + non-cycle Err)
    // gets memoized.
    let should_memo = match &result {
        _ if matches!(build_permission, BuildPermission::TargetOnly { .. }) => false,
        Ok(_) => true,
        Err(e) => !is_cycle_error(e) && !e.starts_with("local-build scheduler invariant:"),
    };
    if should_memo {
        build_memo()
            .lock()
            .unwrap()
            .insert(memo_key, result.clone());
    }
    result
}

fn ensure_built_uncached(
    target: &DepsManifest,
    registry: &Registry,
    arch: TargetArch,
    abi_version: u32,
    opts: &ResolveOpts<'_>,
    memo: &mut BTreeMap<String, [u8; 32]>,
    building: &mut Vec<String>,
    build_permission: &BuildPermission,
    verify_cache: bool,
) -> Result<ResolvedNode, String> {
    if building.iter().any(|s| s == &target.name) {
        return Err(format!(
            "cycle while building: {} -> {}",
            building.join(" -> "),
            target.name
        ));
    }
    building.push(target.name.clone());

    if let Some(path) = try_fetch_without_deps(target, registry, arch, abi_version, opts, memo)? {
        building.pop();
        return Ok(ResolvedNode::compiled(path, BTreeSet::new()));
    }

    // Recursively resolve direct deps first; remember their paths so
    // we can surface them to the build script via env vars. The
    // transitive set accumulates every dep path in the subgraph,
    // deduped — diamond deps must only contribute once.
    //
    // We track each direct dep's `kind` alongside its path so that
    // `build_into_cache` can choose the env-var suffix per design 12:
    // library/program → `WASM_POSIX_DEP_<NAME>_DIR` (built artifact
    // root); source → `WASM_POSIX_DEP_<NAME>_SRC_DIR` (unbuilt source
    // tree). Build scripts then self-document what shape they're
    // consuming via the suffix.
    let mut dep_dirs: BTreeMap<String, DirectDep> = BTreeMap::new();
    let mut transitive: BTreeSet<PathBuf> = BTreeSet::new();
    for dref in &target.depends_on {
        let dep_m = registry.load(&dref.name)?;
        if dep_m.version != dref.version {
            return Err(format!(
                "{} depends on {}@{}, but registry has {}",
                target.spec(),
                dref.name,
                dref.version,
                dep_m.spec()
            ));
        }
        // Per the wasm64 build policy (memory/wasm64-build-policy.md):
        // only MariaDB and PHP need wasm64 binaries; everything else
        // is wasm32-only. So a wasm64 program (e.g. mariadb-vfs)
        // depending on a wasm32-only dep (e.g. dinit) is the common
        // case, not a misconfiguration. When the parent arch isn't in
        // the dep's target_arches, fall back to wasm32 (the universal
        // arch) for that dep. The resolver places the dep's binaries
        // under binaries/programs/wasm32/, where build scripts'
        // arch-agnostic tryResolveBinary("programs/<x>.wasm") finds
        // them. The kernel runs mixed-arch programs.
        let dep_arch = dependency_target_arch(target, &dep_m, arch)?;
        let dep_resolved = ensure_built_inner(
            &dep_m,
            registry,
            dep_arch,
            abi_version,
            opts,
            memo,
            building,
            build_permission,
            verify_cache,
        )?;
        // Place binaries/programs/<arch>/<output> symlinks for each
        // program dep so consumer build scripts can find them via
        // `tryResolveBinary("programs/<x>.wasm")`. Only kicks in when
        // the caller opts in with binaries_dir; other ensure_built
        // consumers leave binaries_dir = None and no symlinks land.
        // Library deps and source deps are linked at compile time via
        // WASM_POSIX_DEP_* env vars and don't need a binaries/ entry.
        if let Some(bdir) = opts.binaries_dir {
            if matches!(dep_m.kind, ManifestKind::Program) && !dep_m.program_outputs.is_empty() {
                let cache_key_sha = manifest_cache_key_sha_for_policy(
                    &dep_m,
                    registry,
                    dep_arch,
                    abi_version,
                    opts.policy,
                )?;
                let dep_path =
                    require_compiled_dir(&dep_resolved, &dep_m.name, "program binary projection")?;
                let repo_root = opts
                    .repo_root
                    .map(Path::to_path_buf)
                    .unwrap_or_else(crate::repo_root);
                publish_resolved_program_artifacts(
                    &dep_m,
                    dep_path,
                    &repo_root,
                    bdir,
                    dep_arch,
                    &cache_key_sha,
                    false,
                )?;
            }
        }
        if let NodeMaterialization::CompiledDir(dep_path) = &dep_resolved.materialization {
            transitive.insert(dep_path.clone());
        }
        transitive.extend(dep_resolved.transitive_compiled_dirs.iter().cloned());
        dep_dirs.insert(
            dep_m.name.clone(),
            DirectDep {
                materialization: dep_resolved.materialization,
                kind: dep_m.kind,
            },
        );
    }

    building.pop();

    if opts.policy == ResolvePolicy::SourceOnlyV1 && target.kind == ManifestKind::Source {
        if target.source.provider != SourceProvider::Archive {
            return Err(format!(
                "{}: source-only source dependency requires source.provider = \"archive\"",
                target.spec(),
            ));
        }
        let source_cache_root = opts
            .source_cache_root
            .ok_or_else(|| format!("{}: validated source-cache base is missing", target.spec()))?;
        let archive = source_archive_cache::fetch_verified_archive_with_disposition(
            source_cache_root,
            &target.source.url,
            &target.source.sha256,
        )
        .map_err(|error| {
            format!(
                "{}: acquire verified source archive: {error}",
                target.spec()
            )
        })?;
        return Ok(ResolvedNode {
            materialization: NodeMaterialization::VerifiedSourceArchive {
                archive: archive.path,
                source_url: target.source.url.clone(),
                sha256: target.source.sha256.clone(),
                extract_exclude_members: target.source.extract_exclude_members.clone(),
            },
            transitive_compiled_dirs: transitive,
            disposition: match archive.disposition {
                source_archive_cache::SourceArchiveDisposition::Cached => {
                    LocalBuildDisposition::Cached
                }
                source_archive_cache::SourceArchiveDisposition::Published => {
                    LocalBuildDisposition::Published
                }
            },
        });
    }

    // Local-libs override: hand-patched source wins. The override dir
    // still contributes to `transitive` for any consumer above us.
    if opts.policy == ResolvePolicy::Default {
        if let Some(lr) = opts.local_libs {
            let override_dir = lr.join(&target.name).join("build");
            if override_dir.is_dir() {
                return Ok(ResolvedNode::compiled(override_dir, transitive));
            }
        }
    }

    // Compute canonical cache path.
    let mut chain: Vec<String> = Vec::new();
    let sha = compute_sha_for_policy(
        target,
        registry,
        arch,
        abi_version,
        opts.policy,
        memo,
        &mut chain,
    )?;
    let canonical = canonical_path(opts.cache_root, target, arch, &sha);
    let cache_key_sha_hex = hex(&sha);
    let source_only_cache_parent = (opts.policy == ResolvePolicy::SourceOnlyV1)
        .then(|| SourceOnlyCacheParentGuard::prepare(opts.cache_root, &canonical))
        .transpose()?;

    let force_rebuild = opts
        .force_source_build
        .map(|s| s.contains(&target.name))
        .unwrap_or(false);

    // Cache hit: validate before using it. The cache key includes the
    // numeric kernel ABI, but fork-continuation mechanism changes have
    // previously produced stale artifacts with a matching ABI number
    // (legacy Asyncify exports instead of wpk_fork_*). Reject those so
    // the resolver can fetch a current remote artifact or source-build.
    let canonical_is_cache_hit = match opts.policy {
        // Preserve the exact public Default predicate. `Path::is_dir` follows
        // symlinks and treats regular/dangling entries as misses; changing it
        // would alter long-standing repair/error behavior outside SourceOnly.
        ResolvePolicy::Default => canonical.is_dir(),
        ResolvePolicy::SourceOnlyV1 => path_entry_exists(&canonical)?,
    };
    if !force_rebuild && canonical_is_cache_hit {
        if let Some(parent) = &source_only_cache_parent {
            if verify_cache {
                capture_source_only_cache_entry_snapshot(
                    target,
                    parent,
                    &canonical,
                    arch,
                    abi_version,
                    &cache_key_sha_hex,
                )
                .map_err(|error| {
                    format!(
                        "{}: invalid source-only canonical cache entry was preserved at {}: {error}",
                        target.spec(),
                        canonical.display()
                    )
                })?;
            } else if !source_only_cache_entry_is_trusted(
                target,
                &canonical,
                arch,
                abi_version,
                &cache_key_sha_hex,
            )? {
                return Err(format!(
                    "{}: source-only cache entry at {} vanished after admission",
                    target.spec(),
                    canonical.display()
                ));
            }
            return Ok(ResolvedNode::compiled(canonical, transitive));
        }
        match validate_cache_entry(target, &canonical, arch, abi_version, &cache_key_sha_hex) {
            Ok(()) => {
                return Ok(ResolvedNode::compiled(canonical, transitive));
            }
            Err(e) => {
                eprintln!(
                    "warning: ignoring stale cached artifact for {} at {} ({})",
                    target.spec(),
                    canonical.display(),
                    e,
                );
                remove_cache_entry(&canonical, &cache_key_sha_hex).map_err(|remove_err| {
                    format!(
                        "clear stale cache entry {} after validation failure: {remove_err}",
                        canonical.display()
                    )
                })?;
            }
        }
    }
    if force_rebuild
        && opts.policy == ResolvePolicy::Default
        && canonical.is_dir()
    {
        remove_cache_entry(&canonical, &cache_key_sha_hex)
            .map_err(|e| format!("force-rebuild: clear {}: {e}", canonical.display()))?;
    }
    if opts.policy == ResolvePolicy::SourceOnlyV1
        && !build_permission.permits_compiled_recipe(target, arch)
    {
        return Err(format!(
            "local-build scheduler invariant: prerequisite {} ({}) is not a completed source-only cache hit at {}",
            target.name,
            arch.as_str(),
            canonical.display()
        ));
    }

    // Run host-tool probes before any work that might invoke a build
    // script (or fetch+extract a source-kind tarball). Cache hits skip
    // this — probes are only needed when we might actually invoke
    // `bash build-<x>.sh` or similar work. Aggregate ALL probe
    // failures so users fix everything in one round-trip.
    if !target.host_tools.is_empty() {
        let mut failures: Vec<ProbeFailure> = Vec::new();
        for tool in &target.host_tools {
            if let Err(e) = host_tool_probe::probe(tool) {
                failures.push(e);
            }
        }
        if !failures.is_empty() {
            return Err(render_probe_failures(target, &failures));
        }
    }

    // Cache-miss dispatch. Three flavors of recipe:
    //
    //   (Source, None)     — default fetch+extract from `[source]`.
    //   (Source, Some(_))  — override path: the manifest ships its own
    //                        build script (e.g. patch overlay, git clone,
    //                        multi-tarball assembly). Run it through
    //                        `build_into_cache` with the standard env-var
    //                        contract; validation is non-emptiness of
    //                        OUT_DIR rather than a declared outputs list.
    //   (Library | Program,_) — source-build through the SDK/resolver.
    //                        Resolution is local-first; there is no
    //                        prebuilt-archive channel.
    match (target.kind, target.build.script_path.is_some()) {
        (ManifestKind::Source, false) => {
            let parent = canonical
                .parent()
                .ok_or_else(|| format!("canonical path has no parent: {}", canonical.display()))?;
            std::fs::create_dir_all(parent)
                .map_err(|e| format!("create cache parent {}: {e}", parent.display()))?;
            let tmp = parent.join(format!(
                "{}.tmp-{}",
                canonical
                    .file_name()
                    .expect("canonical path has a filename")
                    .to_string_lossy(),
                std::process::id()
            ));
            if tmp.exists() {
                std::fs::remove_dir_all(&tmp)
                    .map_err(|e| format!("clean stale {}: {e}", tmp.display()))?;
            }
            if let Err(e) =
                source_extract::fetch_and_extract(&target.source.url, &target.source.sha256, &tmp)
            {
                let _ = std::fs::remove_dir_all(&tmp);
                return Err(format!(
                    "{}: source fetch+extract failed: {e}",
                    target.spec()
                ));
            }
            if let Err(e) =
                write_cache_provenance(target, &canonical, arch, abi_version, &cache_key_sha_hex)
            {
                let _ = std::fs::remove_dir_all(&tmp);
                return Err(e);
            }
            // Race against a peer process that finished its own extract
            // first: keep theirs, drop ours. Identical inputs produce
            // identical outputs.
            if canonical.exists() {
                let _ = std::fs::remove_dir_all(&tmp);
                validate_cache_entry(target, &canonical, arch, abi_version, &cache_key_sha_hex)?;
                return Ok(ResolvedNode::compiled(canonical, transitive));
            }
            std::fs::rename(&tmp, &canonical)
                .map_err(|e| format!("rename {} -> {}: {e}", tmp.display(), canonical.display()))?;
            Ok(ResolvedNode::compiled(canonical, transitive))
        }
        (ManifestKind::Source, true) => {
            // Override path: run the script. No remote-binary fetch for
            // sources (`[binary]` is rejected at parse time for source
            // kind), so we go straight to `build_into_cache`.
            let pkgconfig_path = compose_pkgconfig_path(&transitive);
            let repo_root = opts
                .repo_root
                .map(Path::to_path_buf)
                .unwrap_or_else(crate::repo_root);
            let disposition = build_into_cache(
                target,
                registry,
                arch,
                abi_version,
                &cache_key_sha_hex,
                opts.cache_root,
                opts.source_cache_root,
                &canonical,
                &dep_dirs,
                &pkgconfig_path,
                &repo_root,
                opts.policy,
                force_rebuild,
            )?;
            Ok(ResolvedNode::compiled_with_disposition(
                canonical,
                transitive,
                disposition,
            ))
        }
        (ManifestKind::Library | ManifestKind::Program, _) => {
            // Resolution is local-first: packages are always built from source
            // through the SDK/resolver. The remote binary channel (prebuilt
            // archives fetched from a release index) has been removed; a build
            // is the only way to produce an artifact.
            let pkgconfig_path = compose_pkgconfig_path(&transitive);
            let repo_root = opts
                .repo_root
                .map(Path::to_path_buf)
                .unwrap_or_else(crate::repo_root);
            let disposition = build_into_cache(
                target,
                registry,
                arch,
                abi_version,
                &cache_key_sha_hex,
                opts.cache_root,
                opts.source_cache_root,
                &canonical,
                &dep_dirs,
                &pkgconfig_path,
                &repo_root,
                opts.policy,
                force_rebuild,
            )?;
            // Persist the SourceOnlyV1 package receipt sidecar for the entry we
            // just stored. This is the `xtask build-deps resolve` path (run.sh's
            // node.wasm bootstrap, package build-script dependency resolution);
            // without this write the Task-7 build-key belt check has no receipt
            // to read and stays a permanent no-op for these entries. The receipt
            // is byte-identical to the projection-hooks path's for the same
            // node. Best-effort, matching that path's convention: a failure here
            // only forces the next run to recompute, never a wrong result.
            if opts.policy == ResolvePolicy::SourceOnlyV1 {
                if let Err(error) = write_canonical_receipt(
                    target,
                    opts.cache_root,
                    &canonical,
                    &cache_key_sha_hex,
                    arch,
                    abi_version,
                ) {
                    eprintln!(
                        "{}: warning: persist source-only cache receipt: {error}",
                        target.spec()
                    );
                }
            }
            Ok(ResolvedNode::compiled_with_disposition(
                canonical,
                transitive,
                disposition,
            ))
        }
    }
}

/// Build the `WASM_POSIX_DEP_PKG_CONFIG_PATH` value for a build script.
///
/// Joins every transitive lib path's `lib/pkgconfig/` subdirectory with
/// `:` — POSIX's standard search-path separator, and what pkg-config
/// itself uses for `PKG_CONFIG_PATH`. Paths whose `lib/pkgconfig/`
/// directory doesn't exist (e.g. ncurses, libs that ship no .pc file)
/// are skipped: handing pkg-config a list of nonexistent search paths
/// clutters diagnostics with no benefit.
///
/// Returns an empty string when no transitive lib ships pkgconfig. The
/// caller still sets the env var to that empty string, keeping the
/// contract uniform: the var is *always* defined for build scripts.
fn compose_pkgconfig_path(paths: &BTreeSet<PathBuf>) -> String {
    paths
        .iter()
        .filter_map(|p| {
            let pc = p.join("lib").join("pkgconfig");
            if pc.is_dir() {
                Some(pc.to_string_lossy().into_owned())
            } else {
                None
            }
        })
        .collect::<Vec<_>>()
        .join(":")
}

#[derive(Debug)]
struct ProvisionedGitInput {
    declaration: GitBuildInput,
    checkout: PathBuf,
    worktree_digest: [u8; 32],
}

#[derive(Debug)]
struct GitCommandIsolation {
    home: PathBuf,
    xdg_config_home: PathBuf,
    empty_templates: PathBuf,
    empty_hooks: PathBuf,
    askpass: PathBuf,
}

/// Temporary, detached checkouts for a package's declared `git_inputs`.
/// Dropping the guard removes every checkout, including error paths.
#[derive(Debug, Default)]
struct ProvisionedGitInputs {
    root: Option<PathBuf>,
    #[cfg(unix)]
    owned_root: Option<OwnedPrivateDirectory>,
    isolation: Option<GitCommandIsolation>,
    inputs: Vec<ProvisionedGitInput>,
}

impl ProvisionedGitInputs {
    fn provision(target: &DepsManifest, canonical: &Path) -> Result<Self, String> {
        let build_path = target.dir.join("build.toml");
        if !build_path.exists() {
            return Ok(Self::default());
        }
        let declarations = BuildToml::load(&target.dir)?.git_inputs;
        if declarations.is_empty() {
            return Ok(Self::default());
        }

        Self::provision_declarations(&target.spec(), canonical, declarations)
    }

    #[cfg(unix)]
    fn provision_source_only(
        target: &DepsManifest,
        source_inputs: &AnchoredDirectory,
    ) -> Result<Self, String> {
        let build_path = target.dir.join("build.toml");
        if !build_path.exists() {
            return Ok(Self::default());
        }
        let declarations = BuildToml::load(&target.dir)?.git_inputs;
        if declarations.is_empty() {
            return Ok(Self::default());
        }
        Self::provision_declarations_inner(
            &target.spec(),
            Path::new("source-only-owned-git-inputs"),
            declarations,
            &[],
            Some(source_inputs.try_clone("source-only input root")?),
        )
    }

    fn provision_declarations(
        package_spec: &str,
        canonical: &Path,
        declarations: Vec<GitBuildInput>,
    ) -> Result<Self, String> {
        Self::provision_declarations_inner(package_spec, canonical, declarations, &[], None)
    }

    #[cfg(test)]
    fn provision_declarations_with_ambient_env(
        package_spec: &str,
        canonical: &Path,
        declarations: Vec<GitBuildInput>,
        ambient_env: &[(std::ffi::OsString, std::ffi::OsString)],
    ) -> Result<Self, String> {
        Self::provision_declarations_inner(
            package_spec,
            canonical,
            declarations,
            ambient_env,
            None,
        )
    }

    fn provision_declarations_inner(
        package_spec: &str,
        canonical: &Path,
        declarations: Vec<GitBuildInput>,
        ambient_env: &[(std::ffi::OsString, std::ffi::OsString)],
        #[cfg(unix)] source_only_parent: Option<AnchoredDirectory>,
        #[cfg(not(unix))] _source_only_parent: Option<AnchoredDirectory>,
    ) -> Result<Self, String> {
        #[cfg(unix)]
        let (root, owned_root) = if let Some(parent) = source_only_parent {
            let owned = OwnedPrivateDirectory::reserve_below(
                parent,
                "git-inputs",
                "source-only immutable git-input root",
            )?;
            (owned.path().to_path_buf(), Some(owned))
        } else {
            let parent = canonical.parent().ok_or_else(|| {
                format!(
                    "{}: canonical cache path has no parent for git inputs: {}",
                    package_spec,
                    canonical.display()
                )
            })?;
            let basename = canonical
                .file_name()
                .ok_or_else(|| {
                    format!(
                        "canonical cache path has no filename: {}",
                        canonical.display()
                    )
                })?
                .to_string_lossy();
            (create_git_input_root(parent, &basename)?, None)
        };
        #[cfg(not(unix))]
        let root = {
            let parent = canonical.parent().ok_or_else(|| {
                format!(
                    "{}: canonical cache path has no parent for git inputs: {}",
                    package_spec,
                    canonical.display()
                )
            })?;
            let basename = canonical
                .file_name()
                .ok_or_else(|| {
                    format!(
                        "canonical cache path has no filename: {}",
                        canonical.display()
                    )
                })?
                .to_string_lossy();
            create_git_input_root(parent, &basename)?
        };

        let mut provisioned = Self {
            root: Some(root.clone()),
            #[cfg(unix)]
            owned_root,
            isolation: None,
            inputs: Vec::with_capacity(declarations.len()),
        };
        let isolation = create_git_command_isolation(&root)?;
        let checkouts = root.join("checkouts");
        std::fs::create_dir(&checkouts).map_err(|e| {
            format!(
                "create immutable git-input checkout root {}: {e}",
                checkouts.display()
            )
        })?;
        provisioned.isolation = Some(isolation);
        for declaration in declarations {
            let isolation = provisioned
                .isolation
                .as_ref()
                .expect("git command isolation was initialized");
            let checkout = checkouts.join(&declaration.name);
            std::fs::create_dir(&checkout)
                .map_err(|e| format!("create git-input checkout {}: {e}", checkout.display()))?;
            run_git(
                &checkout,
                &["init", "--quiet", "--object-format=sha1"],
                &declaration.repository,
                isolation,
                ambient_env,
            )?;
            run_git(
                &checkout,
                &[
                    "fetch",
                    "--quiet",
                    "--depth=1",
                    "--no-tags",
                    "--no-recurse-submodules",
                    &declaration.repository,
                    &declaration.commit,
                ],
                &declaration.repository,
                isolation,
                ambient_env,
            )?;
            run_git(
                &checkout,
                &["checkout", "--quiet", "--detach", "FETCH_HEAD"],
                &declaration.repository,
                isolation,
                ambient_env,
            )?;
            verify_git_input(&declaration, &checkout, isolation, ambient_env)?;
            validate_git_input_tree(&declaration, &checkout, isolation, ambient_env)?;
            let worktree_digest = digest_git_input_worktree(&checkout)?;
            set_git_input_tree_read_only(&checkout, true)?;
            provisioned.inputs.push(ProvisionedGitInput {
                declaration,
                checkout,
                worktree_digest,
            });
        }
        // Seal the containing directory as well as each checkout. Otherwise a
        // build that cannot edit files could still rename or replace the path
        // exported in WASM_POSIX_BUILD_GIT_*_DIR.
        set_git_input_tree_read_only(&root, true)?;
        #[cfg(unix)]
        if let Some(owned) = &provisioned.owned_root {
            owned.validate_named_root()?;
        }
        Ok(provisioned)
    }

    fn export_to(&self, command: &mut Command) {
        for input in &self.inputs {
            let key = input.declaration.name.to_ascii_uppercase();
            command.env(format!("WASM_POSIX_BUILD_GIT_{key}_DIR"), &input.checkout);
            command.env(
                format!("WASM_POSIX_BUILD_GIT_{key}_COMMIT"),
                &input.declaration.commit,
            );
        }
    }

    fn verify_unchanged(&self) -> Result<(), String> {
        if self.inputs.is_empty() {
            return Ok(());
        }
        let isolation = self
            .isolation
            .as_ref()
            .ok_or_else(|| "immutable Git inputs lack command isolation".to_string())?;
        for input in &self.inputs {
            verify_git_input(&input.declaration, &input.checkout, isolation, &[])?;
            validate_git_input_tree(&input.declaration, &input.checkout, isolation, &[])?;
            let actual_digest = digest_git_input_worktree(&input.checkout)?;
            if actual_digest != input.worktree_digest {
                return Err(format!(
                    "git input {:?}: immutable working-tree digest changed during build",
                    input.declaration.name
                ));
            }
        }
        Ok(())
    }

    fn cleanup_source_only(&mut self) -> Result<(), String> {
        #[cfg(not(unix))]
        return Err("source-only immutable git-input cleanup requires Unix dirfd semantics".to_string());
        #[cfg(unix)]
        {
            let Some(owned) = self.owned_root.as_mut() else {
                return Ok(());
            };
            owned.cleanup()?;
            self.owned_root = None;
            self.root = None;
            self.isolation = None;
            self.inputs.clear();
            Ok(())
        }
    }
}

impl Drop for ProvisionedGitInputs {
    fn drop(&mut self) {
        #[cfg(unix)]
        if let Some(mut owned) = self.owned_root.take() {
            let _ = owned.cleanup();
            self.root = None;
            return;
        }
        if let Some(root) = self.root.take() {
            let _ = set_git_input_tree_read_only(&root, false);
            let _ = std::fs::remove_dir_all(root);
        }
    }
}

static GIT_INPUT_TEMP_COUNTER: AtomicU64 = AtomicU64::new(0);

fn create_git_input_root(parent: &Path, basename: &str) -> Result<PathBuf, String> {
    for _ in 0..10_000 {
        let counter = GIT_INPUT_TEMP_COUNTER.fetch_add(1, Ordering::Relaxed);
        let root = parent.join(format!(
            ".{basename}.git-inputs-{}-{counter}",
            std::process::id()
        ));
        match std::fs::create_dir(&root) {
            Ok(()) => {
                #[cfg(unix)]
                {
                    use std::os::unix::fs::PermissionsExt;
                    std::fs::set_permissions(&root, std::fs::Permissions::from_mode(0o700))
                        .map_err(|e| {
                            format!(
                                "set exclusive git-input root permissions {}: {e}",
                                root.display()
                            )
                        })?;
                }
                return Ok(root);
            }
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(e) => {
                return Err(format!(
                    "create exclusive git-input root {}: {e}",
                    root.display()
                ));
            }
        }
    }
    Err(format!(
        "could not allocate an exclusive git-input root below {}",
        parent.display()
    ))
}

fn create_git_command_isolation(root: &Path) -> Result<GitCommandIsolation, String> {
    let home = root.join("home");
    let xdg_config_home = root.join("xdg-config");
    let empty_templates = root.join("empty-templates");
    let empty_hooks = root.join("empty-hooks");
    for path in [&home, &xdg_config_home, &empty_templates, &empty_hooks] {
        std::fs::create_dir(path)
            .map_err(|e| format!("create isolated Git directory {}: {e}", path.display()))?;
    }

    let askpass = root.join("askpass-deny.sh");
    std::fs::write(&askpass, "#!/bin/sh\nexit 1\n")
        .map_err(|e| format!("write isolated Git askpass {}: {e}", askpass.display()))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&askpass, std::fs::Permissions::from_mode(0o500))
            .map_err(|e| format!("seal isolated Git askpass {}: {e}", askpass.display()))?;
    }

    Ok(GitCommandIsolation {
        home,
        xdg_config_home,
        empty_templates,
        empty_hooks,
        askpass,
    })
}

/// Construct a Git subprocess that cannot inherit source credentials, token
/// headers, hooks, or repository selection from the caller's environment.
/// Build-time Git inputs are public source inputs; a private checkout would be
/// both unreproducible and an accidental credential dependency.
fn hardened_git_command(
    repository: &str,
    isolation: &GitCommandIsolation,
    ambient_env: &[(std::ffi::OsString, std::ffi::OsString)],
) -> Command {
    let mut command = Command::new("git");
    // Test callers can inject a hostile ambient environment without mutating
    // process-global state. Production passes an empty slice; Command still
    // begins with the real inherited environment in both cases.
    command.envs(ambient_env.iter().cloned());
    command
        .arg("-c")
        .arg(format!(
            "core.hooksPath={}",
            isolation.empty_hooks.to_string_lossy()
        ))
        .arg("-c")
        .arg(format!(
            "init.templateDir={}",
            isolation.empty_templates.to_string_lossy()
        ))
        .arg("-c")
        .arg("credential.helper=")
        .arg("-c")
        .arg("credential.interactive=false")
        .arg("-c")
        .arg("http.extraHeader=")
        .arg("-c")
        .arg("http.cookieFile=")
        .arg("-c")
        .arg("http.saveCookies=false")
        .arg("-c")
        .arg("http.followRedirects=false")
        .arg("-c")
        .arg("submodule.recurse=false")
        .arg("-c")
        .arg("core.autocrlf=false")
        .arg("-c")
        .arg("core.eol=lf")
        .env("HOME", &isolation.home)
        .env("XDG_CONFIG_HOME", &isolation.xdg_config_home)
        .env("GIT_ATTR_NOSYSTEM", "1")
        .env("GIT_CONFIG_NOSYSTEM", "1")
        .env("GIT_CONFIG_GLOBAL", "/dev/null")
        .env("GIT_CONFIG_SYSTEM", "/dev/null")
        .env("GIT_CONFIG_COUNT", "0")
        .env("GIT_TERMINAL_PROMPT", "0")
        .env("GIT_ASKPASS", &isolation.askpass)
        .env("GIT_ASKPASS_REQUIRE", "force")
        .env("SSH_ASKPASS", &isolation.askpass)
        .env("SSH_ASKPASS_REQUIRE", "force")
        .env("GIT_OPTIONAL_LOCKS", "0")
        .env("GIT_DEFAULT_HASH", "sha1")
        .env("GIT_NO_REPLACE_OBJECTS", "1")
        .env("GIT_PROTOCOL_FROM_USER", "0")
        .env(
            "GIT_ALLOW_PROTOCOL",
            if repository.starts_with("file://") {
                // Private test helpers construct local repositories directly;
                // BuildToml validation makes this unreachable for real inputs.
                "https:file"
            } else {
                "https"
            },
        );

    for key in [
        "GH_TOKEN",
        "GITHUB_TOKEN",
        "GIT_DIR",
        "GIT_COMMON_DIR",
        "GIT_WORK_TREE",
        "GIT_INDEX_FILE",
        "GIT_OBJECT_DIRECTORY",
        "GIT_ALTERNATE_OBJECT_DIRECTORIES",
        "GIT_CONFIG_PARAMETERS",
        "GIT_CONFIG",
        "GIT_SSH",
        "GIT_SSH_COMMAND",
        "GIT_TEMPLATE_DIR",
        "GIT_EXEC_PATH",
        "GIT_PROXY_COMMAND",
        "GIT_NAMESPACE",
        "GIT_REPLACE_REF_BASE",
        "GIT_SHALLOW_FILE",
        "GIT_GRAFT_FILE",
        "GIT_CEILING_DIRECTORIES",
        "GIT_DISCOVERY_ACROSS_FILESYSTEM",
        "GIT_EXTERNAL_DIFF",
        "GIT_DIFF_OPTS",
        "GIT_EDITOR",
        "GIT_PAGER",
        "GIT_TRACE",
        "GIT_TRACE2",
        "GIT_TRACE_CURL",
        "GIT_CURL_VERBOSE",
        "NETRC",
        "SSH_AUTH_SOCK",
    ] {
        command.env_remove(key);
    }
    for (key, _) in std::env::vars_os().chain(ambient_env.iter().cloned()) {
        let key_text = key.to_string_lossy();
        if key_text.starts_with("GIT_CONFIG_KEY_")
            || key_text.starts_with("GIT_CONFIG_VALUE_")
            || key_text.starts_with("GIT_TRACE_")
        {
            command.env_remove(key);
        }
    }
    command
}

fn git_output(
    checkout: &Path,
    args: &[&str],
    repository: &str,
    isolation: &GitCommandIsolation,
    ambient_env: &[(std::ffi::OsString, std::ffi::OsString)],
) -> Result<std::process::Output, String> {
    let mut command = hardened_git_command(repository, isolation, ambient_env);
    let output = command
        .arg("-C")
        .arg(checkout)
        .args(args)
        .output()
        .map_err(|e| format!("spawn isolated git in {}: {e}", checkout.display()))?;
    Ok(output)
}

fn run_git(
    checkout: &Path,
    args: &[&str],
    repository: &str,
    isolation: &GitCommandIsolation,
    ambient_env: &[(std::ffi::OsString, std::ffi::OsString)],
) -> Result<(), String> {
    let output = git_output(checkout, args, repository, isolation, ambient_env)?;
    if output.status.success() {
        return Ok(());
    }
    Err(format!(
        "isolated git {:?} failed in {} with {}: {}",
        args,
        checkout.display(),
        output.status,
        String::from_utf8_lossy(&output.stderr).trim()
    ))
}

fn verify_git_input(
    input: &GitBuildInput,
    checkout: &Path,
    isolation: &GitCommandIsolation,
    ambient_env: &[(std::ffi::OsString, std::ffi::OsString)],
) -> Result<(), String> {
    let head = git_output(
        checkout,
        &["rev-parse", "HEAD^{commit}"],
        &input.repository,
        isolation,
        ambient_env,
    )?;
    if !head.status.success() {
        return Err(format!(
            "git input {:?}: cannot resolve detached HEAD in {}: {}",
            input.name,
            checkout.display(),
            String::from_utf8_lossy(&head.stderr).trim()
        ));
    }
    let actual = String::from_utf8_lossy(&head.stdout).trim().to_string();
    if actual != input.commit {
        return Err(format!(
            "git input {:?}: expected commit {}, checkout has {}",
            input.name, input.commit, actual
        ));
    }

    if let Some(expected_tree) = &input.tree {
        let tree = git_output(
            checkout,
            &["rev-parse", "HEAD^{tree}"],
            &input.repository,
            isolation,
            ambient_env,
        )?;
        if !tree.status.success() {
            return Err(format!(
                "git input {:?}: cannot resolve parent tree in {}: {}",
                input.name,
                checkout.display(),
                String::from_utf8_lossy(&tree.stderr).trim()
            ));
        }
        let actual_tree = String::from_utf8_lossy(&tree.stdout).trim().to_string();
        if actual_tree != *expected_tree {
            return Err(format!(
                "git input {:?}: expected tree {}, checkout has {}",
                input.name, expected_tree, actual_tree
            ));
        }
    }

    let branch = git_output(
        checkout,
        &["rev-parse", "--abbrev-ref", "HEAD"],
        &input.repository,
        isolation,
        ambient_env,
    )?;
    if !branch.status.success() || String::from_utf8_lossy(&branch.stdout).trim() != "HEAD" {
        return Err(format!(
            "git input {:?}: checkout must remain at a detached HEAD",
            input.name
        ));
    }

    let status = git_output(
        checkout,
        &[
            "status",
            "--porcelain=v1",
            "--untracked-files=all",
            "--ignored=matching",
        ],
        &input.repository,
        isolation,
        ambient_env,
    )?;
    if !status.status.success() {
        return Err(format!(
            "git input {:?}: cannot verify clean checkout: {}",
            input.name,
            String::from_utf8_lossy(&status.stderr).trim()
        ));
    }
    if !status.stdout.is_empty() {
        return Err(format!(
            "git input {:?}: build mutated immutable checkout {}:\n{}",
            input.name,
            checkout.display(),
            String::from_utf8_lossy(&status.stdout).trim()
        ));
    }
    Ok(())
}

fn validate_git_input_tree(
    input: &GitBuildInput,
    checkout: &Path,
    isolation: &GitCommandIsolation,
    ambient_env: &[(std::ffi::OsString, std::ffi::OsString)],
) -> Result<(), String> {
    let index = git_output(
        checkout,
        &["ls-files", "--stage", "-z"],
        &input.repository,
        isolation,
        ambient_env,
    )?;
    if !index.status.success() {
        return Err(format!(
            "git input {:?}: cannot inspect index: {}",
            input.name,
            String::from_utf8_lossy(&index.stderr).trim()
        ));
    }
    let mut gitlinks = Vec::new();
    for record in index
        .stdout
        .split(|byte| *byte == 0)
        .filter(|record| !record.is_empty())
    {
        let tab = record.iter().position(|byte| *byte == b'\t').ok_or_else(|| {
            format!(
                "git input {:?}: malformed index record while checking gitlinks",
                input.name
            )
        })?;
        let metadata = &record[..tab];
        let mode = metadata
            .split(|byte| *byte == b' ')
            .next()
            .unwrap_or(metadata);
        if mode == b"160000" {
            if !input.allow_uninitialized_gitlinks {
                return Err(format!(
                    "git input {:?}: submodule gitlinks are not allowed in immutable build inputs",
                    input.name
                ));
            }
            let path = std::str::from_utf8(&record[tab + 1..]).map_err(|_| {
                format!(
                    "git input {:?}: gitlink path is not valid UTF-8",
                    input.name
                )
            })?;
            let relative = Path::new(path);
            if path.is_empty()
                || path.contains('\\')
                || !relative
                    .components()
                    .all(|component| matches!(component, std::path::Component::Normal(_)))
            {
                return Err(format!(
                    "git input {:?}: gitlink path must be a normalized relative path, got {path:?}",
                    input.name
                ));
            }
            gitlinks.push(relative.to_path_buf());
        }
    }

    let canonical = std::fs::canonicalize(checkout)
        .map_err(|e| format!("resolve git input root {}: {e}", checkout.display()))?;
    let git_metadata_path = checkout.join(".git");
    let git_metadata_lstat = std::fs::symlink_metadata(&git_metadata_path).map_err(|e| {
        format!(
            "inspect git input metadata directory {}: {e}",
            git_metadata_path.display()
        )
    })?;
    if !git_metadata_lstat.is_dir() || git_metadata_lstat.file_type().is_symlink() {
        return Err(format!(
            "git input {:?}: .git must be a real non-symlink directory inside its checkout",
            input.name
        ));
    }
    let git_metadata = std::fs::canonicalize(&git_metadata_path).map_err(|e| {
        format!(
            "resolve git input metadata directory {}: {e}",
            checkout.join(".git").display()
        )
    })?;
    if !git_metadata.starts_with(&canonical) {
        return Err(format!(
            "git input {:?}: .git resolves outside immutable checkout {}",
            input.name,
            checkout.display()
        ));
    }
    for relative in gitlinks {
        let path = checkout.join(&relative);
        let metadata = std::fs::symlink_metadata(&path).map_err(|e| {
            format!(
                "git input {:?}: inspect uninitialized gitlink {}: {e}",
                input.name,
                path.display()
            )
        })?;
        let resolved = std::fs::canonicalize(&path).map_err(|e| {
            format!(
                "git input {:?}: resolve uninitialized gitlink {}: {e}",
                input.name,
                path.display()
            )
        })?;
        let expected = canonical.join(&relative);
        let empty = if metadata.is_dir() && !metadata.file_type().is_symlink() && resolved == expected
        {
            std::fs::read_dir(&path)
                .map_err(|e| {
                    format!(
                        "git input {:?}: read uninitialized gitlink {}: {e}",
                        input.name,
                        path.display()
                    )
                })?
                .next()
                .transpose()
                .map_err(|e| {
                    format!(
                        "git input {:?}: read uninitialized gitlink entry below {}: {e}",
                        input.name,
                        path.display()
                    )
                })?
                .is_none()
        } else {
            false
        };
        if !empty {
            return Err(format!(
                "git input {:?}: allowed uninitialized gitlink {} must be an empty real directory with no symlinked path components",
                input.name,
                path.display()
            ));
        }
    }
    validate_git_input_tree_entries(input, checkout, checkout, &canonical, &git_metadata)
}

fn validate_git_input_tree_entries(
    input: &GitBuildInput,
    checkout: &Path,
    directory: &Path,
    canonical: &Path,
    git_metadata: &Path,
) -> Result<(), String> {
    let mut entries = std::fs::read_dir(directory)
        .map_err(|e| format!("read git input directory {}: {e}", directory.display()))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|e| format!("read git input entry below {}: {e}", directory.display()))?;
    entries.sort_by_key(|entry| entry.path());
    for entry in entries {
        let path = entry.path();
        if directory == checkout && entry.file_name() == ".git" {
            continue;
        }
        let metadata = std::fs::symlink_metadata(&path)
            .map_err(|e| format!("stat git input entry {}: {e}", path.display()))?;
        if metadata.file_type().is_symlink() {
            let resolved = std::fs::canonicalize(&path).map_err(|e| {
                format!(
                    "git input {:?}: symlink {} cannot be resolved inside its checkout: {e}",
                    input.name,
                    path.display()
                )
            })?;
            if !resolved.starts_with(canonical) {
                return Err(format!(
                    "git input {:?}: symlink {} escapes immutable checkout {}",
                    input.name,
                    path.display(),
                    checkout.display()
                ));
            }
            if resolved == git_metadata || resolved.starts_with(git_metadata) {
                return Err(format!(
                    "git input {:?}: symlink {} resolves into private Git metadata {}",
                    input.name,
                    path.display(),
                    git_metadata.display()
                ));
            }
        } else if metadata.is_dir() {
            validate_git_input_tree_entries(input, checkout, &path, canonical, git_metadata)?;
        } else if !metadata.is_file() {
            return Err(format!(
                "git input {:?}: {} is not a regular file, directory, or contained symlink",
                input.name,
                path.display()
            ));
        }
    }
    Ok(())
}

/// Hash the exported working tree independently of Git's index/status view.
/// A build can toggle index flags such as `assume-unchanged`; it cannot make a
/// byte, symlink target, path, or executable-bit mutation disappear from this
/// resolver-owned digest.
fn digest_git_input_worktree(checkout: &Path) -> Result<[u8; 32], String> {
    let mut hasher = Sha256::new();
    hasher.update(b"kandelo-immutable-git-working-tree-v1\0");
    digest_git_input_directory(checkout, checkout, &mut hasher)?;
    Ok(hasher.finalize().into())
}

fn digest_git_input_directory(
    checkout: &Path,
    directory: &Path,
    hasher: &mut Sha256,
) -> Result<(), String> {
    let mut entries = std::fs::read_dir(directory)
        .map_err(|e| format!("read immutable Git tree {}: {e}", directory.display()))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|e| format!("read immutable Git tree entry {}: {e}", directory.display()))?;
    entries.sort_by_key(|entry| entry.file_name());
    for entry in entries {
        if directory == checkout && entry.file_name() == ".git" {
            continue;
        }
        let path = entry.path();
        let relative = path
            .strip_prefix(checkout)
            .map_err(|_| format!("immutable Git path escaped checkout: {}", path.display()))?;
        let path_bytes = relative.as_os_str().as_encoded_bytes();
        let metadata = std::fs::symlink_metadata(&path)
            .map_err(|e| format!("stat immutable Git path {}: {e}", path.display()))?;
        if metadata.file_type().is_symlink() {
            let target = std::fs::read_link(&path)
                .map_err(|e| format!("read immutable Git symlink {}: {e}", path.display()))?;
            hasher.update(b"symlink\0");
            hasher.update((path_bytes.len() as u64).to_le_bytes());
            hasher.update(path_bytes);
            let target_bytes = target.as_os_str().as_encoded_bytes();
            hasher.update((target_bytes.len() as u64).to_le_bytes());
            hasher.update(target_bytes);
        } else if metadata.is_dir() {
            hasher.update(b"directory\0");
            hasher.update((path_bytes.len() as u64).to_le_bytes());
            hasher.update(path_bytes);
            digest_git_input_directory(checkout, &path, hasher)?;
        } else if metadata.is_file() {
            hasher.update(b"file\0");
            hasher.update((path_bytes.len() as u64).to_le_bytes());
            hasher.update(path_bytes);
            hasher.update([git_input_file_is_executable(&metadata) as u8]);
            hasher.update(metadata.len().to_le_bytes());
            let mut file = std::fs::File::open(&path)
                .map_err(|e| format!("open immutable Git file {}: {e}", path.display()))?;
            std::io::copy(&mut file, hasher)
                .map_err(|e| format!("hash immutable Git file {}: {e}", path.display()))?;
        } else {
            return Err(format!(
                "immutable Git path is not a file, directory, or symlink: {}",
                path.display()
            ));
        }
    }
    Ok(())
}

#[cfg(unix)]
fn git_input_file_is_executable(metadata: &std::fs::Metadata) -> bool {
    use std::os::unix::fs::PermissionsExt;
    metadata.permissions().mode() & 0o111 != 0
}

#[cfg(not(unix))]
fn git_input_file_is_executable(_metadata: &std::fs::Metadata) -> bool {
    false
}

#[cfg(unix)]
fn set_git_input_tree_read_only(path: &Path, read_only: bool) -> Result<(), String> {
    use std::os::unix::fs::PermissionsExt;

    let metadata = std::fs::symlink_metadata(path)
        .map_err(|e| format!("stat immutable git input {}: {e}", path.display()))?;
    if metadata.file_type().is_symlink() {
        return Ok(());
    }
    if metadata.is_dir() && !read_only {
        let mut permissions = metadata.permissions();
        permissions.set_mode(permissions.mode() | 0o700);
        std::fs::set_permissions(path, permissions)
            .map_err(|e| format!("unseal git input directory {}: {e}", path.display()))?;
    }
    if metadata.is_dir() {
        let entries = std::fs::read_dir(path)
            .map_err(|e| format!("read immutable git input {}: {e}", path.display()))?;
        for entry in entries {
            let entry = entry.map_err(|e| format!("read immutable git input entry: {e}"))?;
            set_git_input_tree_read_only(&entry.path(), read_only)?;
        }
    }
    let metadata = std::fs::symlink_metadata(path)
        .map_err(|e| format!("restat immutable git input {}: {e}", path.display()))?;
    // Removing a tree only requires writable/searchable directories. Never
    // chmod regular leaves while unsealing scratch: a recipe may have created
    // a hardlink to an inode outside the resolver-owned work root.
    if !read_only && !metadata.is_dir() {
        return Ok(());
    }
    let mut permissions = metadata.permissions();
    if read_only {
        permissions.set_mode(permissions.mode() & !0o222);
    } else {
        permissions.set_mode(permissions.mode() | 0o600);
    }
    std::fs::set_permissions(path, permissions).map_err(|e| {
        format!(
            "{} immutable git input {}: {e}",
            if read_only { "seal" } else { "unseal" },
            path.display()
        )
    })
}

#[cfg(not(unix))]
fn set_git_input_tree_read_only(path: &Path, read_only: bool) -> Result<(), String> {
    let metadata = std::fs::symlink_metadata(path)
        .map_err(|e| format!("stat immutable git input {}: {e}", path.display()))?;
    if metadata.file_type().is_symlink() {
        return Ok(());
    }
    if metadata.is_dir() && !read_only {
        let mut permissions = metadata.permissions();
        permissions.set_readonly(false);
        std::fs::set_permissions(path, permissions)
            .map_err(|e| format!("unseal git input directory {}: {e}", path.display()))?;
    }
    if metadata.is_dir() {
        for entry in std::fs::read_dir(path)
            .map_err(|e| format!("read immutable git input {}: {e}", path.display()))?
        {
            let entry = entry.map_err(|e| format!("read immutable git input entry: {e}"))?;
            set_git_input_tree_read_only(&entry.path(), read_only)?;
        }
    }
    let mut permissions = std::fs::symlink_metadata(path)
        .map_err(|e| format!("restat immutable git input {}: {e}", path.display()))?
        .permissions();
    permissions.set_readonly(read_only);
    std::fs::set_permissions(path, permissions).map_err(|e| {
        format!(
            "{} immutable git input {}: {e}",
            if read_only { "seal" } else { "unseal" },
            path.display()
        )
    })
}

struct BuildWorkRoot {
    path: PathBuf,
    recipe_work: PathBuf,
    source_inputs: PathBuf,
    identity: PackageMirrorIdentity,
    #[cfg(unix)]
    owned: Option<OwnedPrivateDirectory>,
    #[cfg(unix)]
    recipe_work_anchor: Option<AnchoredDirectory>,
    #[cfg(unix)]
    source_inputs_anchor: Option<AnchoredDirectory>,
}

impl BuildWorkRoot {
    fn cleanup_source_only(&mut self) -> Result<(), String> {
        #[cfg(not(unix))]
        return Err("source-only build work cleanup requires Unix dirfd semantics".to_string());
        #[cfg(unix)]
        {
            if self.owned.is_none() {
                return Ok(());
            }
            let owned = self.owned.as_mut().ok_or_else(|| {
                "source-only build work root lacks its owned directory guard".to_string()
            })?;
            owned.validate_named_root()?;
            let recipe = self.recipe_work_anchor.as_ref().ok_or_else(|| {
                "source-only build work root lacks its recipe-work identity".to_string()
            })?;
            let source_inputs = self.source_inputs_anchor.as_ref().ok_or_else(|| {
                "source-only build work root lacks its source-inputs identity".to_string()
            })?;
            let names = stable_receipt_directory_names(&owned.root.file, owned.path())?;
            if names != [OsString::from("recipe-work"), OsString::from("source-inputs")] {
                owned.preserve = true;
                return Err(format!(
                    "source-only build work root top-level ownership changed and was preserved: {}",
                    owned.path().display()
                ));
            }
            for (name, anchor, label) in [
                (OsStr::new("recipe-work"), recipe, "recipe-work"),
                (OsStr::new("source-inputs"), source_inputs, "source-inputs"),
            ] {
                let current = receipt_at_metadata_snapshot(
                    &owned.root.file,
                    name,
                    &owned.path().join(name),
                )?;
                if current.kind != 2 || current.identity != anchor.identity {
                    owned.preserve = true;
                    return Err(format!(
                        "source-only build {label} identity changed and was preserved: {}",
                        owned.path().join(name).display()
                    ));
                }
            }
            let expected_children = [
                (OsString::from("recipe-work"), recipe.identity.clone()),
                (OsString::from("source-inputs"), source_inputs.identity.clone()),
            ];
            owned.cleanup_scratch_recursively(&expected_children)?;
            self.recipe_work_anchor = None;
            self.source_inputs_anchor = None;
            self.owned = None;
            Ok(())
        }
    }
}

impl Drop for BuildWorkRoot {
    fn drop(&mut self) {
        #[cfg(unix)]
        if self.owned.is_some() {
            let _ = self.cleanup_source_only();
            return;
        }
        let unchanged = std::fs::symlink_metadata(&self.path)
            .ok()
            .filter(|metadata| metadata.is_dir() && !metadata.file_type().is_symlink())
            .and_then(|metadata| package_mirror_identity(&metadata).ok())
            .is_some_and(|identity| identity == self.identity);
        if !unchanged {
            return;
        }
        let _ = set_git_input_tree_read_only(&self.path, false);
        let _ = std::fs::remove_dir_all(&self.path);
    }
}

static BUILD_WORK_TEMP_COUNTER: AtomicU64 = AtomicU64::new(0);

fn create_build_work_root(
    parent: &Path,
    basename: &str,
    policy: ResolvePolicy,
    source_only_parent: Option<&SourceOnlyCacheParentGuard>,
) -> Result<BuildWorkRoot, String> {
    if policy == ResolvePolicy::SourceOnlyV1 {
        #[cfg(not(unix))]
        return Err(
            "source-only build work roots require Unix dirfd filesystem semantics".to_string(),
        );
        #[cfg(unix)]
        {
            let prefix = format!("{basename}.work");
            let guard = source_only_parent.ok_or_else(|| {
                "source-only package work root is missing its anchored cache parent".to_string()
            })?;
            if guard.parent != parent {
                return Err(format!(
                    "source-only work-root parent differs from its anchored cache parent: {} != {}",
                    parent.display(),
                    guard.parent.display()
                ));
            }
            guard.validate()?;
            let mut owned = OwnedPrivateDirectory::reserve_below(
                guard.parent_anchor.try_clone("source-only cache kind parent")?,
                &prefix,
                "source-only package work root",
            )?;
            let recipe_work_anchor = match owned.root.create_named_child_directory_with_after_create(
                OsStr::new("recipe-work"),
                0o700,
                "private recipe work root",
                &mut |_| {},
            ) {
                Ok(anchor) => anchor,
                Err(error) => {
                    owned.preserve = true;
                    return Err(error);
                }
            };
            let source_inputs_anchor = match owned.root.create_named_child_directory_with_after_create(
                OsStr::new("source-inputs"),
                0o700,
                "private source-input root",
                &mut |_| {},
            ) {
                Ok(anchor) => anchor,
                Err(error) => {
                    owned.preserve = true;
                    return Err(error);
                }
            };
            owned.parent.validate_path()?;
            owned.validate_named_root()?;
            return Ok(BuildWorkRoot {
                path: owned.path().to_path_buf(),
                recipe_work: recipe_work_anchor.path.clone(),
                source_inputs: source_inputs_anchor.path.clone(),
                identity: owned.identity().clone(),
                owned: Some(owned),
                recipe_work_anchor: Some(recipe_work_anchor),
                source_inputs_anchor: Some(source_inputs_anchor),
            });
        }
    }
    for _ in 0..10_000 {
        let counter = BUILD_WORK_TEMP_COUNTER.fetch_add(1, Ordering::Relaxed);
        let path = parent.join(format!(
            ".{basename}.work-{}-{counter}",
            std::process::id()
        ));
            match create_private_transaction_directory(&path) {
            Ok(()) => {
                let identity = package_mirror_identity(
                    &std::fs::symlink_metadata(&path).map_err(|error| {
                        format!("inspect private package work root {}: {error}", path.display())
                    })?,
                )?;
                let (recipe_work, source_inputs) = match policy {
                    ResolvePolicy::Default => (path.clone(), path.clone()),
                    ResolvePolicy::SourceOnlyV1 => {
                        (path.join("recipe-work"), path.join("source-inputs"))
                    }
                };
                let work = BuildWorkRoot {
                    path,
                    recipe_work,
                    source_inputs,
                    identity,
                    #[cfg(unix)]
                    owned: None,
                    #[cfg(unix)]
                    recipe_work_anchor: None,
                    #[cfg(unix)]
                    source_inputs_anchor: None,
                };
                return Ok(work);
            }
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(e) => {
                return Err(format!(
                    "create exclusive package work root {}: {e}",
                    path.display()
                ));
            }
        }
    }
    Err(format!(
        "could not allocate an exclusive package work root below {}",
        parent.display()
    ))
}

#[derive(Debug)]
struct PrimarySourceHandoff {
    archive: PathBuf,
    source_dir: PathBuf,
}

fn configure_primary_source_environment(
    command: &mut Command,
    target: &DepsManifest,
    policy: ResolvePolicy,
    handoff: Option<&PrimarySourceHandoff>,
) -> Result<(), String> {
    for variable in [
        "WASM_POSIX_DEP_SOURCE_ARCHIVE",
        "WASM_POSIX_DEP_SOURCE_DIR",
        "WASM_POSIX_DEP_SOURCE_URL",
        "WASM_POSIX_DEP_SOURCE_SHA256",
    ] {
        command.env_remove(variable);
    }

    match (policy, target.source.provider) {
        (ResolvePolicy::SourceOnlyV1, SourceProvider::Archive) => {
            let handoff = handoff.ok_or_else(|| {
                format!(
                    "{}: source-only Archive provider is missing its verified source handoff",
                    target.spec(),
                )
            })?;
            command.env("WASM_POSIX_DEP_SOURCE_ARCHIVE", &handoff.archive);
            command.env("WASM_POSIX_DEP_SOURCE_DIR", &handoff.source_dir);
            command.env("WASM_POSIX_DEP_SOURCE_URL", &target.source.url);
            command.env("WASM_POSIX_DEP_SOURCE_SHA256", &target.source.sha256);
        }
        (ResolvePolicy::SourceOnlyV1, SourceProvider::Repository | SourceProvider::DevShell) => {
            if handoff.is_some() {
                return Err(format!(
                    "{}: {} provider must not receive an archive source handoff",
                    target.spec(),
                    target.source.provider.as_str(),
                ));
            }
        }
        (ResolvePolicy::Default, SourceProvider::Archive) => {
            if handoff.is_some() {
                return Err(format!(
                    "{}: default Archive provider does not accept resolver-owned source paths",
                    target.spec(),
                ));
            }
            command.env("WASM_POSIX_DEP_SOURCE_URL", &target.source.url);
            command.env("WASM_POSIX_DEP_SOURCE_SHA256", &target.source.sha256);
        }
        (ResolvePolicy::Default, SourceProvider::Repository | SourceProvider::DevShell) => {
            if handoff.is_some() {
                return Err(format!(
                    "{}: default {} provider must not receive an archive source handoff",
                    target.spec(),
                    target.source.provider.as_str(),
                ));
            }
        }
    }
    Ok(())
}

fn source_dependency_key(name: &str) -> String {
    let mut key = String::with_capacity(2 + name.len() * 2);
    key.push_str("K_");
    for byte in name.as_bytes() {
        use std::fmt::Write as _;
        write!(&mut key, "{byte:02X}").expect("writing to a String cannot fail");
    }
    key
}

fn direct_dependency_variable_names(
    dependencies: &BTreeMap<String, DirectDep>,
    policy: ResolvePolicy,
) -> Result<BTreeMap<String, String>, String> {
    const RESERVED_RESOLVER_VARIABLES: &[&str] = &[
        "WASM_POSIX_DEP_NAME",
        "WASM_POSIX_DEP_OUT_DIR",
        "WASM_POSIX_DEP_PKG_CONFIG_PATH",
        "WASM_POSIX_DEP_PKG_VERSION",
        "WASM_POSIX_DEP_RECIPE_DIR",
        "WASM_POSIX_DEP_REVISION",
        "WASM_POSIX_DEP_SOURCE_ARCHIVE",
        "WASM_POSIX_DEP_SOURCE_DIR",
        "WASM_POSIX_DEP_SOURCE_SHA256",
        "WASM_POSIX_DEP_SOURCE_URL",
        "WASM_POSIX_DEP_TARGET_ARCH",
        "WASM_POSIX_DEP_VERSION",
        "WASM_POSIX_DEP_WORK_DIR",
    ];
    let mut variables = BTreeMap::new();
    let mut owners: BTreeMap<String, String> = BTreeMap::new();
    for (name, dependency) in dependencies {
        let (key, suffix) = match (policy, dependency.kind) {
            (ResolvePolicy::SourceOnlyV1, ManifestKind::Source) => {
                (source_dependency_key(name), "SRC_DIR")
            }
            (_, ManifestKind::Source) => (env_key(name), "SRC_DIR"),
            (_, ManifestKind::Library | ManifestKind::Program) => (env_key(name), "DIR"),
        };
        let variable = format!("WASM_POSIX_DEP_{key}_{suffix}");
        if RESERVED_RESOLVER_VARIABLES.contains(&variable.as_str()) {
            return Err(format!(
                "direct dependency {name:?} maps to reserved resolver variable {variable}; refusing to mutate the build command environment",
            ));
        }
        if let Some(previous) = owners.insert(variable.clone(), name.clone()) {
            return Err(format!(
                "direct dependencies {previous:?} and {name:?} both map to {variable}; refusing to mutate the build command environment",
            ));
        }
        variables.insert(name.clone(), variable);
    }
    Ok(variables)
}

fn validate_source_link(root: &Path, link: &Path, target: &Path) -> Result<(), String> {
    if target.is_absolute() {
        return Err(format!(
            "source tree symlink {} has absolute target {}",
            link.display(),
            target.display(),
        ));
    }
    let relative = link.strip_prefix(root).map_err(|_| {
        format!(
            "source tree entry {} escaped {}",
            link.display(),
            root.display()
        )
    })?;
    let mut depth = relative
        .parent()
        .map(|parent| {
            parent
                .components()
                .filter(|component| matches!(component, Component::Normal(_)))
                .count()
        })
        .unwrap_or(0);
    for component in target.components() {
        match component {
            Component::CurDir => {}
            Component::ParentDir if depth > 0 => depth -= 1,
            Component::ParentDir => {
                return Err(format!(
                    "source tree symlink {} escapes its root with target {}",
                    link.display(),
                    target.display(),
                ));
            }
            Component::Normal(_) => depth += 1,
            Component::RootDir | Component::Prefix(_) => {
                return Err(format!(
                    "source tree symlink {} has unsupported target {}",
                    link.display(),
                    target.display(),
                ));
            }
        }
    }
    Ok(())
}

fn validate_source_tree(root: &Path, directory: &Path) -> Result<(), String> {
    let metadata = std::fs::symlink_metadata(directory)
        .map_err(|error| format!("inspect source directory {}: {error}", directory.display()))?;
    if metadata.file_type().is_symlink() || !metadata.file_type().is_dir() {
        return Err(format!(
            "source tree directory must be a real directory: {}",
            directory.display(),
        ));
    }
    for entry in std::fs::read_dir(directory)
        .map_err(|error| format!("read source directory {}: {error}", directory.display()))?
    {
        let entry = entry.map_err(|error| format!("read source tree entry: {error}"))?;
        let path = entry.path();
        let metadata = std::fs::symlink_metadata(&path)
            .map_err(|error| format!("inspect source tree entry {}: {error}", path.display()))?;
        if metadata.file_type().is_dir() {
            validate_source_tree(root, &path)?;
        } else if metadata.file_type().is_symlink() {
            let target = std::fs::read_link(&path)
                .map_err(|error| format!("read source tree symlink {}: {error}", path.display()))?;
            validate_source_link(root, &path, &target)?;
        } else if !metadata.file_type().is_file() {
            return Err(format!(
                "source tree entry {} has unsupported special type",
                path.display(),
            ));
        }
    }
    Ok(())
}

#[cfg(unix)]
fn seal_source_tree_entry(path: &Path) -> Result<(), String> {
    use std::os::unix::fs::PermissionsExt;

    let metadata = std::fs::symlink_metadata(path)
        .map_err(|error| format!("inspect source tree entry {}: {error}", path.display()))?;
    if metadata.file_type().is_symlink() {
        return Ok(());
    }
    if metadata.file_type().is_dir() {
        for entry in std::fs::read_dir(path)
            .map_err(|error| format!("read source directory {}: {error}", path.display()))?
        {
            let entry = entry.map_err(|error| format!("read source tree entry: {error}"))?;
            seal_source_tree_entry(&entry.path())?;
        }
    } else if !metadata.file_type().is_file() {
        return Err(format!(
            "source tree entry {} has unsupported special type",
            path.display(),
        ));
    }
    let mut permissions = metadata.permissions();
    permissions.set_mode(permissions.mode() & !0o222);
    std::fs::set_permissions(path, permissions)
        .map_err(|error| format!("seal source tree entry {}: {error}", path.display()))
}

#[cfg(not(unix))]
fn seal_source_tree_entry(path: &Path) -> Result<(), String> {
    let metadata = std::fs::symlink_metadata(path)
        .map_err(|error| format!("inspect source tree entry {}: {error}", path.display()))?;
    if metadata.file_type().is_symlink() {
        return Ok(());
    }
    if metadata.file_type().is_dir() {
        for entry in std::fs::read_dir(path)
            .map_err(|error| format!("read source directory {}: {error}", path.display()))?
        {
            let entry = entry.map_err(|error| format!("read source tree entry: {error}"))?;
            seal_source_tree_entry(&entry.path())?;
        }
    } else if !metadata.file_type().is_file() {
        return Err(format!(
            "source tree entry {} has unsupported special type",
            path.display(),
        ));
    }
    let mut permissions = metadata.permissions();
    permissions.set_readonly(true);
    std::fs::set_permissions(path, permissions)
        .map_err(|error| format!("seal source tree entry {}: {error}", path.display()))
}

fn validate_and_seal_source_tree(root: &Path) -> Result<(), String> {
    validate_source_tree(root, root)?;
    seal_source_tree_entry(root)?;
    validate_source_tree(root, root)
}

fn prepare_primary_source_handoff(
    target: &DepsManifest,
    policy: ResolvePolicy,
    source_cache_root: Option<&Path>,
    work_root: &Path,
) -> Result<Option<PrimarySourceHandoff>, String> {
    match (policy, target.source.provider) {
        (ResolvePolicy::SourceOnlyV1, SourceProvider::Archive) => {
            let source_cache_root = source_cache_root.ok_or_else(|| {
                format!("{}: validated source-cache base is missing", target.spec())
            })?;
            let archive = source_archive_cache::fetch_verified_archive(
                source_cache_root,
                &target.source.url,
                &target.source.sha256,
            )
            .map_err(|error| {
                format!(
                    "{}: acquire verified primary source: {error}",
                    target.spec()
                )
            })?;
            let source_dir = work_root.join("primary-source");
            source_extract::extract_verified_archive_with_excluded_members(
                &archive,
                &target.source.url,
                &source_dir,
                &target.source.extract_exclude_members,
            )
            .map_err(|error| {
                format!(
                    "{}: extract verified primary source: {error}",
                    target.spec()
                )
            })?;
            validate_and_seal_source_tree(&source_dir).map_err(|error| {
                format!("{}: seal verified primary source: {error}", target.spec())
            })?;
            Ok(Some(PrimarySourceHandoff {
                archive,
                source_dir,
            }))
        }
        (ResolvePolicy::SourceOnlyV1, SourceProvider::Repository | SourceProvider::DevShell)
        | (ResolvePolicy::Default, _) => Ok(None),
    }
}

fn materialize_direct_dependencies(
    target: &DepsManifest,
    dependencies: &BTreeMap<String, DirectDep>,
    policy: ResolvePolicy,
    source_cache_root: Option<&Path>,
    work_root: &Path,
) -> Result<BTreeMap<String, PathBuf>, String> {
    let mut paths = BTreeMap::new();
    let mut source_root_created = false;
    let source_root = work_root.join("source-deps");
    for (name, dependency) in dependencies {
        let path = match (&dependency.materialization, dependency.kind, policy) {
            (NodeMaterialization::CompiledDir(path), _, _) => path.clone(),
            (
                NodeMaterialization::VerifiedSourceArchive {
                    archive,
                    source_url,
                    sha256,
                    extract_exclude_members,
                },
                ManifestKind::Source,
                ResolvePolicy::SourceOnlyV1,
            ) => {
                let source_cache_root = source_cache_root.ok_or_else(|| {
                    format!("{}: validated source-cache base is missing", target.spec())
                })?;
                let verified_archive = source_archive_cache::fetch_verified_archive(
                    source_cache_root,
                    source_url,
                    sha256,
                )
                .map_err(|error| {
                    format!(
                        "{}: reverify source dependency {name:?} archive before extraction: {error}",
                        target.spec(),
                    )
                })?;
                if &verified_archive != archive {
                    return Err(format!(
                        "internal resolver error: source dependency {name:?} for {} changed canonical archive payload from {} to {}",
                        target.spec(),
                        archive.display(),
                        verified_archive.display(),
                    ));
                }
                if !source_root_created {
                    create_private_transaction_directory(&source_root).map_err(|error| {
                        format!(
                            "{}: create private source-dependency root {}: {error}",
                            target.spec(),
                            source_root.display(),
                        )
                    })?;
                    source_root_created = true;
                }
                let destination = source_root.join(source_dependency_key(name));
                source_extract::extract_verified_archive_with_excluded_members(
                    &verified_archive,
                    source_url,
                    &destination,
                    extract_exclude_members,
                )
                .map_err(|error| {
                    format!(
                        "{}: extract verified source dependency {name:?}: {error}",
                        target.spec(),
                    )
                })?;
                validate_and_seal_source_tree(&destination).map_err(|error| {
                    format!(
                        "{}: seal verified source dependency {name:?}: {error}",
                        target.spec(),
                    )
                })?;
                destination
            }
            (NodeMaterialization::VerifiedSourceArchive { .. }, kind, _) => {
                return Err(format!(
                    "internal resolver error: dependency {name:?} for {} has a verified source archive with kind {kind:?} under policy {policy:?}",
                    target.spec(),
                ));
            }
        };
        paths.insert(name.clone(), path);
    }
    Ok(paths)
}

/// Run the build script with `WASM_POSIX_DEP_*` env vars set, validate
/// outputs under the temp directory, then `rename(2)` into place.
///
/// `pkgconfig_path` is the pre-composed value for
/// `WASM_POSIX_DEP_PKG_CONFIG_PATH` — a colon-joined list of every
/// transitive lib's `lib/pkgconfig/` dir. Always set, even when empty,
/// so the contract for build scripts stays uniform.
#[derive(Clone, Debug, Eq, PartialEq)]
enum CacheProvenanceSnapshot {
    Absent,
    Present(LocalMirrorEntrySnapshot),
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct CacheEntrySnapshot {
    identity: PackageMirrorIdentity,
    receipt: CompleteCacheReceiptV1,
    provenance: CacheProvenanceSnapshot,
}

#[derive(Debug)]
struct SourceOnlyCacheParentGuard {
    root: PathBuf,
    root_identity: PackageMirrorIdentity,
    parent: PathBuf,
    parent_identity: PackageMirrorIdentity,
    #[cfg(unix)]
    root_anchor: AnchoredDirectory,
    #[cfg(unix)]
    parent_anchor: AnchoredDirectory,
    #[cfg(unix)]
    parent_name: OsString,
}

impl SourceOnlyCacheParentGuard {
    fn prepare(cache_root: &Path, canonical: &Path) -> Result<Self, String> {
        #[cfg(not(unix))]
        return Err(
            "source-only compiled-cache transactions require Unix dirfd semantics".to_string(),
        );
        #[cfg(unix)]
        {
        let exact_root = std::fs::canonicalize(cache_root).map_err(|error| {
            format!(
                "canonicalize source-only compiled cache root {}: {error}",
                cache_root.display()
            )
        })?;
        if exact_root != cache_root {
            return Err(format!(
                "source-only compiled cache root must use its exact canonical spelling {}; got {}",
                exact_root.display(),
                cache_root.display()
            ));
        }
        let parent = canonical.parent().ok_or_else(|| {
            format!("source-only canonical cache path has no parent: {}", canonical.display())
        })?;
        if parent.parent() != Some(cache_root) {
            return Err(format!(
                "source-only canonical cache parent {} is not an immediate child of {}",
                parent.display(),
                cache_root.display()
            ));
        }
        let parent_name = parent
            .file_name()
            .ok_or_else(|| format!("source-only cache kind parent has no name: {}", parent.display()))?
            .to_os_string();
        let root_anchor = AnchoredDirectory::open_existing(
            cache_root,
            "source-only compiled cache root",
        )?;
        let parent_anchor = root_anchor.ensure_child_directory(
            &parent_name,
            0o755,
            "source-only cache kind parent",
        ).map_err(|error| {
            format!(
                "source-only cache kind parent must be a real nonsymlink directory: {}; {error}",
                parent.display()
            )
        })?;
        let canonical_parent = std::fs::canonicalize(parent).map_err(|error| {
            format!(
                "canonicalize source-only cache kind parent {}: {error}",
                parent.display()
            )
        })?;
        if canonical_parent != parent || !canonical_parent.starts_with(cache_root) {
            return Err(format!(
                "source-only cache kind parent escaped its compiled root: {}",
                parent.display()
            ));
        }
        let guard = Self {
            root: cache_root.to_path_buf(),
            root_identity: root_anchor.identity.clone(),
            parent: parent.to_path_buf(),
            parent_identity: parent_anchor.identity.clone(),
            root_anchor,
            parent_anchor,
            parent_name,
        };
        guard.validate()?;
        Ok(guard)
        }
    }

    fn validate(&self) -> Result<(), String> {
        #[cfg(not(unix))]
        return Err(
            "source-only compiled-cache transactions require Unix dirfd semantics".to_string(),
        );
        #[cfg(unix)]
        {
        self.root_anchor.validate_path()?;
        self.parent_anchor.validate_path()?;
        let parent_at = receipt_at_metadata_snapshot(
            &self.root_anchor.file,
            &self.parent_name,
            &self.parent,
        )?;
        if parent_at.kind != 2 || parent_at.identity != self.parent_identity {
            return Err(format!(
                "source-only cache kind parent changed below its opened root: {}",
                self.parent.display()
            ));
        }
        for (path, expected, label) in [
            (&self.root, &self.root_identity, "compiled cache root"),
            (&self.parent, &self.parent_identity, "cache kind parent"),
        ] {
            let metadata = std::fs::symlink_metadata(path).map_err(|error| {
                format!("inspect source-only {label} {}: {error}", path.display())
            })?;
            if metadata.file_type().is_symlink()
                || !metadata.is_dir()
                || &package_mirror_identity(&metadata)? != expected
            {
                return Err(format!(
                    "source-only {label} changed identity or stopped being a real nonsymlink directory: {}",
                    path.display()
                ));
            }
        }
        let canonical_parent = std::fs::canonicalize(&self.parent).map_err(|error| {
            format!(
                "canonicalize source-only cache kind parent {}: {error}",
                self.parent.display()
            )
        })?;
        if canonical_parent != self.parent || !canonical_parent.starts_with(&self.root) {
            return Err(format!(
                "source-only cache kind parent escaped its compiled root: {}",
                self.parent.display()
            ));
        }
        Ok(())
        }
    }

    #[cfg(unix)]
    fn canonical_name(&self, canonical: &Path) -> Result<OsString, String> {
        if canonical.parent() != Some(self.parent.as_path()) {
            return Err(format!(
                "source-only canonical cache entry is not below its anchored kind parent: {}",
                canonical.display()
            ));
        }
        let name = canonical
            .file_name()
            .ok_or_else(|| {
                format!(
                    "source-only canonical cache entry has no filename: {}",
                    canonical.display()
                )
            })?
            .to_os_string();
        validate_single_path_component(&name, "source-only canonical cache entry")?;
        Ok(name)
    }

    #[cfg(unix)]
    fn open_canonical_entry(
        &self,
        canonical: &Path,
    ) -> Result<(OsString, AnchoredDirectory, ReceiptAtMetadataSnapshot), String> {
        let name = self.canonical_name(canonical)?;
        let before = receipt_at_metadata_snapshot(&self.parent_anchor.file, &name, canonical)?;
        if before.kind != 2 {
            return Err(format!(
                "canonical cache entry must be a real nonsymlink directory: {}",
                canonical.display()
            ));
        }
        let entry = self
            .parent_anchor
            .open_child_directory(&name, "source-only canonical cache entry")?;
        if entry.identity != before.identity {
            return Err(format!(
                "canonical cache entry changed while opening: {}",
                canonical.display()
            ));
        }
        Ok((name, entry, before))
    }
}

#[cfg(unix)]
fn require_source_only_receipt_entry<'a>(
    target: &DepsManifest,
    receipt: &'a CompleteCacheReceiptV1,
    relative: &str,
    label: &str,
    require_regular: bool,
) -> Result<&'a CompleteCacheReceiptEntryV1, String> {
    let path = receipt_relative_path(Path::new(relative))?;
    let entry = receipt
        .entries
        .iter()
        .find(|entry| entry.path == path)
        .ok_or_else(|| {
            format!(
                "{}: declared {label} output {relative:?} missing from cache entry",
                target.spec()
            )
        })?;
    if entry.kind == "symlink" {
        return Err(format!(
            "{}: declared {label} output {relative:?} must not be a symlink",
            target.spec()
        ));
    }
    if require_regular && entry.kind != "file" {
        return Err(format!(
            "{}: declared {label} output {relative:?} must be a regular file",
            target.spec()
        ));
    }
    if !require_regular && entry.kind == "directory" {
        let prefix = format!("{path}/");
        if !receipt.entries.iter().any(|candidate| candidate.path.starts_with(&prefix)) {
            return Err(format!(
                "{}: declared {label} output {relative:?} is an empty directory and cannot round-trip through an artifact archive",
                target.spec()
            ));
        }
    } else if !require_regular && entry.kind != "file" {
        return Err(format!(
            "{}: declared {label} output {relative:?} must be a regular file or directory",
            target.spec()
        ));
    }
    Ok(entry)
}

#[cfg(unix)]
fn validate_source_only_cache_artifacts_from_receipt(
    target: &DepsManifest,
    root: &AnchoredDirectory,
    receipt: &CompleteCacheReceiptV1,
) -> Result<(), String> {
    match target.kind {
        ManifestKind::Library => {
            for relative in &target.outputs.libs {
                require_source_only_receipt_entry(target, receipt, relative, "libs", true)?;
            }
            for relative in &target.outputs.headers {
                require_source_only_receipt_entry(target, receipt, relative, "headers", false)?;
            }
            for relative in &target.outputs.pkgconfig {
                require_source_only_receipt_entry(target, receipt, relative, "pkgconfig", true)?;
            }
            for relative in &target.outputs.files {
                require_source_only_receipt_entry(target, receipt, relative, "files", true)?;
            }
        }
        ManifestKind::Program => {
            for output in &target.program_outputs {
                let entry = require_source_only_receipt_entry(
                    target,
                    receipt,
                    &output.wasm,
                    "wasm",
                    true,
                )?;
                let mut source = StableProjectionSource::open_from_anchored_root(
                    root,
                    &output.wasm,
                )?;
                let mut bytes = Vec::new();
                std::io::Read::read_to_end(&mut source.file, &mut bytes).map_err(|error| {
                    format!(
                        "read declared wasm output {}: {error}",
                        source.path.display()
                    )
                })?;
                source.validate()?;
                let digest: [u8; 32] = Sha256::digest(&bytes).into();
                if entry.size != Some(bytes.len() as u64)
                    || entry.sha256.as_deref() != Some(hex(&digest).as_str())
                {
                    return Err(format!(
                        "{}: declared wasm output changed after its complete receipt: {:?}",
                        target.spec(),
                        output.wasm
                    ));
                }
                let failures = wasm_artifact_policy_failures_for(
                    &bytes,
                    output.fork_instrumentation,
                    required_exports_for_program_output(target, output),
                );
                if !failures.is_empty() {
                    return Err(format!(
                        "{}: {}",
                        source.path.display(),
                        failures.join("; ")
                    ));
                }
            }
            for runtime_file in &target.runtime_files {
                require_source_only_receipt_entry(
                    target,
                    receipt,
                    &runtime_file.artifact,
                    "runtime file",
                    true,
                )?;
            }
        }
        ManifestKind::Source => {}
    }
    Ok(())
}

#[cfg(unix)]
fn capture_source_only_provenance_anchored(
    target: &DepsManifest,
    guard: &SourceOnlyCacheParentGuard,
    canonical: &Path,
    arch: TargetArch,
    abi_version: u32,
    cache_key_sha: &str,
) -> Result<CacheProvenanceSnapshot, String> {
    let expected = expected_cache_provenance_bytes(target, arch, abi_version, cache_key_sha)?;
    let provenance_path = cache_provenance_path(canonical, cache_key_sha)?;
    if provenance_path.parent() != Some(guard.parent.as_path()) {
        return Err(format!(
            "cache provenance escaped its anchored parent: {}",
            provenance_path.display()
        ));
    }
    let name = provenance_path
        .file_name()
        .ok_or_else(|| format!("cache provenance has no filename: {}", provenance_path.display()))?;
    validate_single_path_component(name, "cache provenance")?;
    let exists = guard.parent_anchor.child_exists(name, "cache provenance")?;
    match (expected, exists) {
        (None, false) => Ok(CacheProvenanceSnapshot::Absent),
        (None, true) => Err(format!(
            "{}: cache entry has unexpected immutable Git provenance marker {}",
            target.spec(),
            provenance_path.display()
        )),
        (Some(_), false) => Err(format!(
            "{}: cache entry lacks immutable Git provenance marker {}",
            target.spec(),
            provenance_path.display()
        )),
        (Some(expected), true) => {
            let (actual, snapshot) = read_exact_regular_child_at(
                &guard.parent_anchor,
                name,
                &provenance_path,
                MAX_CACHE_PROVENANCE_BYTES,
                "cache provenance",
            )?;
            if actual != expected {
                return Err(format!(
                    "{}: cached immutable Git provenance differs from current identity",
                    target.spec()
                ));
            }
            Ok(CacheProvenanceSnapshot::Present(snapshot))
        }
    }
}

#[cfg(unix)]
fn capture_source_only_cache_entry_snapshot(
    target: &DepsManifest,
    guard: &SourceOnlyCacheParentGuard,
    canonical: &Path,
    arch: TargetArch,
    abi_version: u32,
    cache_key_sha: &str,
) -> Result<CacheEntrySnapshot, String> {
    capture_source_only_cache_entry_snapshot_with_after_validate(
        target,
        guard,
        canonical,
        arch,
        abi_version,
        cache_key_sha,
        &mut || {},
    )
}

#[cfg(not(unix))]
fn capture_source_only_cache_entry_snapshot(
    _target: &DepsManifest,
    _guard: &SourceOnlyCacheParentGuard,
    _canonical: &Path,
    _arch: TargetArch,
    _abi_version: u32,
    _cache_key_sha: &str,
) -> Result<CacheEntrySnapshot, String> {
    Err("source-only cache admission requires Unix no-follow filesystem semantics".to_string())
}

#[cfg(unix)]
fn capture_source_only_cache_entry_snapshot_with_after_validate<F>(
    target: &DepsManifest,
    guard: &SourceOnlyCacheParentGuard,
    canonical: &Path,
    arch: TargetArch,
    abi_version: u32,
    cache_key_sha: &str,
    after_validate: &mut F,
) -> Result<CacheEntrySnapshot, String>
where
    F: FnMut(),
{
    guard.validate()?;
    let (name, root, root_at) = guard.open_canonical_entry(canonical)?;
    let before_receipt = complete_cache_receipt_v1_from_anchored_root(
        &root,
        ResolvePolicy::SourceOnlyV1,
        &target.name,
        arch,
        cache_key_sha,
    )?;
    let before_provenance = capture_source_only_provenance_anchored(
        target,
        guard,
        canonical,
        arch,
        abi_version,
        cache_key_sha,
    )?;
    validate_source_only_cache_artifacts_from_receipt(target, &root, &before_receipt)?;
    after_validate();
    let after_receipt = complete_cache_receipt_v1_from_anchored_root(
        &root,
        ResolvePolicy::SourceOnlyV1,
        &target.name,
        arch,
        cache_key_sha,
    )?;
    let after_provenance = capture_source_only_provenance_anchored(
        target,
        guard,
        canonical,
        arch,
        abi_version,
        cache_key_sha,
    )?;
    let final_at = receipt_at_metadata_snapshot(&guard.parent_anchor.file, &name, canonical)?;
    if final_at != root_at
        || root.identity != root_at.identity
        || after_receipt != before_receipt
        || after_provenance != before_provenance
    {
        return Err(format!(
            "canonical cache entry or provenance changed across semantic validation: {}",
            canonical.display()
        ));
    }
    guard.validate()?;
    Ok(CacheEntrySnapshot {
        identity: root.identity,
        receipt: before_receipt,
        provenance: before_provenance,
    })
}

#[cfg(unix)]
fn validate_source_only_cache_entry_snapshot(
    target: &DepsManifest,
    guard: &SourceOnlyCacheParentGuard,
    canonical: &Path,
    arch: TargetArch,
    abi_version: u32,
    cache_key_sha: &str,
    expected: &CacheEntrySnapshot,
) -> Result<(), String> {
    let actual = capture_source_only_cache_entry_snapshot(
        target,
        guard,
        canonical,
        arch,
        abi_version,
        cache_key_sha,
    )?;
    if &actual != expected {
        return Err(format!(
            "canonical cache entry or provenance changed during rebuild: {}",
            canonical.display()
        ));
    }
    Ok(())
}

