    #[test]
    fn source_context_check_rejects_revision_input_and_transitive_input_mutations() {
        let root = tempdir("program-index-context-source-freshness");
        write(&root, "dependency", "1.0.0", &[]);
        write_build_with_input(&root, "dependency", 1, "recipe.txt", "dependency-one\n");
        write_program(
            &root,
            "command",
            "1.0.0",
            &["dependency@1.0.0"],
            ":",
            &[("command", "command.wasm")],
        );
        write_build_with_input(&root, "command", 1, "recipe.txt", "command-one\n");
        let registry = Registry {
            roots: vec![root.clone()],
        };
        let index = root.join("program-packages.json");
        let refresh = || {
            fs::write(
                &index,
                serialize_program_package_index(&root, &registry).unwrap(),
            )
            .unwrap();
        };
        let assert_stale = |reason: &str| {
            let error = check_program_package_indexes_in_context(&registry, true).unwrap_err();
            assert!(error.contains("is stale"), "{reason}: got {error}");
        };

        refresh();
        let command_build = root.join("command/build.toml");
        let original_command_build = fs::read_to_string(&command_build).unwrap();
        fs::write(
            &command_build,
            original_command_build.replace("revision = 1", "revision = 2"),
        )
        .unwrap();
        assert_stale("program build.toml revision mutation");

        fs::write(&command_build, &original_command_build).unwrap();
        refresh();
        fs::write(root.join("command/recipe.txt"), "command-two\n").unwrap();
        assert_stale("program declared build input mutation");

        fs::write(root.join("command/recipe.txt"), "command-one\n").unwrap();
        refresh();
        fs::write(root.join("dependency/recipe.txt"), "dependency-two\n").unwrap();
        assert_stale("transitive dependency declared build input mutation");
    }

    #[test]
    fn selected_program_index_omits_unrelated_rows_and_tracks_its_dependency_closure() {
        let root = tempdir("program-index-selected-closure");
        write(&root, "dependency", "1.0.0", &[]);
        write_build_with_input(&root, "dependency", 1, "recipe.txt", "dependency-one\n");
        write_program(
            &root,
            "selected-command",
            "1.0.0",
            &["dependency@1.0.0"],
            ":",
            &[("selected-command", "selected-command.wasm")],
        );
        write_build_with_input(&root, "selected-command", 1, "recipe.txt", "selected-one\n");
        write_program(
            &root,
            "unrelated-command",
            "1.0.0",
            &[],
            ":",
            &[("unrelated-command", "unrelated-command.wasm")],
        );
        write_build_with_input(
            &root,
            "unrelated-command",
            1,
            "recipe.txt",
            "unrelated-one\n",
        );
        let registry = Registry {
            roots: vec![root.clone()],
        };
        let selected = vec!["selected-command".to_string()];
        let before = selected_program_package_index_for_root(&root, &registry, &selected).unwrap();

        assert_eq!(
            before.packages.keys().cloned().collect::<Vec<_>>(),
            ["selected-command"]
        );
        assert_eq!(
            before.identities.keys().cloned().collect::<Vec<_>>(),
            ["dependency", "selected-command"]
        );
        assert!(!before.identities.contains_key("unrelated-command"));

        fs::write(root.join("unrelated-command/recipe.txt"), "unrelated-two\n").unwrap();
        let after_unrelated =
            selected_program_package_index_for_root(&root, &registry, &selected).unwrap();
        assert_eq!(
            serde_json::to_value(&before).unwrap(),
            serde_json::to_value(&after_unrelated).unwrap(),
            "an unrelated valid package row must not couple the selected projection",
        );

        fs::write(root.join("dependency/recipe.txt"), "dependency-two\n").unwrap();
        let after_dependency =
            selected_program_package_index_for_root(&root, &registry, &selected).unwrap();
        assert_ne!(
            serde_json::to_value(&before).unwrap(),
            serde_json::to_value(&after_dependency).unwrap(),
            "a selected package's dependency identity must remain source-current",
        );
    }

