    #[test]
    fn compute_cache_key_sha_uses_ordered_git_input_identities() {
        let root = tempdir("ckcs-git-inputs");
        write(&root, "libGit", "1.0.0", &[]);
        let reg = Registry {
            roots: vec![root.clone()],
        };
        let package = root.join("libGit");
        let build_path = package.join("build.toml");
        std::fs::write(
            &build_path,
            r#"
script_path = "packages/registry/libGit/build-libGit.sh"
repo_url = "https://example.test/kandelo.git"
commit = "deadbeefdeadbeefdeadbeefdeadbeefdeadbeef"
revision = 1

[[git_inputs]]
name = "first"
repository = "https://example.test/first.git"
commit = "1111111111111111111111111111111111111111"

[[git_inputs]]
name = "second"
repository = "https://example.test/second.git"
commit = "2222222222222222222222222222222222222222"
"#,
        )
        .unwrap();
        let manifest = reg.load("libGit").unwrap();
        let sha_before = compute_sha(
            &manifest,
            &reg,
            TEST_ARCH,
            TEST_ABI,
            &mut BTreeMap::new(),
            &mut Vec::new(),
        )
        .unwrap();
        let cache_root = root.join("cache");
        let old_canonical = canonical_path(&cache_root, &manifest, TEST_ARCH, &sha_before);
        std::fs::create_dir_all(&old_canonical).unwrap();
        std::fs::write(old_canonical.join("stale"), "old git identity\n").unwrap();

        let original = std::fs::read_to_string(&build_path).unwrap();
        std::fs::write(
            &build_path,
            original.replace(
                "1111111111111111111111111111111111111111",
                "3333333333333333333333333333333333333333",
            ),
        )
        .unwrap();
        let sha_changed_commit = compute_sha(
            &manifest,
            &reg,
            TEST_ARCH,
            TEST_ABI,
            &mut BTreeMap::new(),
            &mut Vec::new(),
        )
        .unwrap();
        assert_ne!(sha_before, sha_changed_commit);
        let changed_canonical =
            canonical_path(&cache_root, &manifest, TEST_ARCH, &sha_changed_commit);
        assert_ne!(old_canonical, changed_canonical);
        assert!(
            !changed_canonical.exists(),
            "a cache hit built for a prior Git identity must not satisfy the current identity"
        );

        std::fs::write(
            &build_path,
            original
                .replace("name = \"first\"", "name = \"temporary\"")
                .replace("name = \"second\"", "name = \"first\"")
                .replace("name = \"temporary\"", "name = \"second\""),
        )
        .unwrap();
        let sha_reordered = compute_sha(
            &manifest,
            &reg,
            TEST_ARCH,
            TEST_ABI,
            &mut BTreeMap::new(),
            &mut Vec::new(),
        )
        .unwrap();
        assert_ne!(
            sha_before, sha_reordered,
            "authored git-input order is part of the cache identity"
        );
    }

    #[test]
    fn compute_cache_key_sha_binds_git_input_tree_and_gitlink_permission() {
        let root = tempdir("ckcs-git-input-tree-capability");
        write(&root, "libGit", "1.0.0", &[]);
        let registry = Registry {
            roots: vec![root.clone()],
        };
        let package = root.join("libGit");
        let build_path = package.join("build.toml");
        std::fs::write(
            &build_path,
            r#"
script_path = "packages/registry/libGit/build-libGit.sh"
repo_url = "https://example.test/kandelo.git"
commit = "deadbeefdeadbeefdeadbeefdeadbeefdeadbeef"
revision = 1

[[git_inputs]]
name = "source"
repository = "https://example.test/source.git"
commit = "1111111111111111111111111111111111111111"
tree = "2222222222222222222222222222222222222222"
allow_uninitialized_gitlinks = true
"#,
        )
        .unwrap();
        let manifest = registry.load("libGit").unwrap();
        let initial = compute_sha(
            &manifest,
            &registry,
            TEST_ARCH,
            TEST_ABI,
            &mut BTreeMap::new(),
            &mut Vec::new(),
        )
        .unwrap();

        let authored = std::fs::read_to_string(&build_path).unwrap();
        std::fs::write(
            &build_path,
            authored.replace(
                "tree = \"2222222222222222222222222222222222222222\"",
                "tree = \"3333333333333333333333333333333333333333\"",
            ),
        )
        .unwrap();
        let changed_tree = compute_sha(
            &manifest,
            &registry,
            TEST_ARCH,
            TEST_ABI,
            &mut BTreeMap::new(),
            &mut Vec::new(),
        )
        .unwrap();
        assert_ne!(initial, changed_tree, "the exact parent tree is identity");

        std::fs::write(
            &build_path,
            authored.replace("allow_uninitialized_gitlinks = true\n", ""),
        )
        .unwrap();
        let denied_gitlinks = compute_sha(
            &manifest,
            &registry,
            TEST_ARCH,
            TEST_ABI,
            &mut BTreeMap::new(),
            &mut Vec::new(),
        )
        .unwrap();
        assert_ne!(
            initial, denied_gitlinks,
            "the narrow uninitialized-gitlink permission is identity"
        );
    }

