    #[test]
    fn program_artifact_policy_rejects_missing_duplicate_and_malformed_descriptors() {
        let imports = wasm_posix_shared::abi::WPK_FORK_REQUIRED_IMPORTS
            .iter()
            .map(|requirement| requirement.name)
            .collect::<Vec<_>>();
        let exports = wasm_posix_shared::abi::WPK_FORK_REQUIRED_EXPORTS
            .iter()
            .map(|requirement| requirement.name)
            .collect::<Vec<_>>();
        let good = linked_frame_descriptor(4);

        let cases: Vec<(&str, Vec<Vec<u8>>)> = vec![
            ("missing", vec![]),
            ("exactly one", vec![good.clone(), good.clone()]),
            ("bytes, expected", vec![good[..23].to_vec()]),
            (
                "invalid magic",
                vec![{
                    let mut descriptor = good.clone();
                    descriptor[0] ^= 0xff;
                    descriptor
                }],
            ),
            (
                "version",
                vec![{
                    let mut descriptor = good.clone();
                    descriptor[4..6].copy_from_slice(&2u16.to_le_bytes());
                    descriptor
                }],
            ),
            (
                "declares size",
                vec![{
                    let mut descriptor = good.clone();
                    descriptor[6..8].copy_from_slice(&23u16.to_le_bytes());
                    descriptor
                }],
            ),
            (
                "pointer width",
                vec![{
                    let mut descriptor = good.clone();
                    descriptor[8] = 16;
                    descriptor
                }],
            ),
            (
                "alignment",
                vec![{
                    let mut descriptor = good.clone();
                    descriptor[9] = 4;
                    descriptor
                }],
            ),
            (
                "flags",
                vec![{
                    let mut descriptor = good.clone();
                    descriptor[10..12].copy_from_slice(&1u16.to_le_bytes());
                    descriptor
                }],
            ),
            (
                "header sizes",
                vec![{
                    let mut descriptor = good.clone();
                    descriptor[12..16].copy_from_slice(&64u32.to_le_bytes());
                    descriptor
                }],
            ),
        ];

        for (expected, descriptors) in cases {
            let bytes = wasm_fork_artifact(4, 4, 4, true, &imports, &exports, &descriptors);
            let failures = wasm_artifact_policy_failures(&bytes, ForkInstrumentationPolicy::Auto);
            assert!(
                failures.iter().any(|failure| failure.contains(expected)),
                "descriptor case {expected:?} was not reported: {failures:?}"
            );
        }
    }

    #[test]
    fn program_artifact_policy_rejects_every_unsafe_activation_capability_shape() {
        use wasm_posix_shared::abi;

        let imports = abi::WPK_FORK_REQUIRED_IMPORTS
            .iter()
            .map(|requirement| requirement.name)
            .collect::<Vec<_>>();
        let exports = abi::WPK_FORK_REQUIRED_EXPORTS
            .iter()
            .map(|requirement| requirement.name)
            .collect::<Vec<_>>();
        let safe = vec![
            abi::WPK_FORK_CAPABILITIES_VERSION,
            abi::WPK_FORK_CAP_ACTIVATION_STATE_SAFE,
        ];
        let cases: Vec<(&str, Vec<Vec<u8>>)> = vec![
            ("missing required", vec![]),
            ("expected exactly one", vec![safe.clone(), safe]),
            (
                "bytes, expected 2",
                vec![vec![abi::WPK_FORK_CAPABILITIES_VERSION]],
            ),
            (
                "version",
                vec![vec![
                    abi::WPK_FORK_CAPABILITIES_VERSION + 1,
                    abi::WPK_FORK_CAP_ACTIVATION_STATE_SAFE,
                ]],
            ),
            (
                "unknown flags",
                vec![vec![
                    abi::WPK_FORK_CAPABILITIES_VERSION,
                    abi::WPK_FORK_CAP_KNOWN_MASK | 0x80,
                ]],
            ),
            (
                "omit required flags",
                vec![vec![abi::WPK_FORK_CAPABILITIES_VERSION, 0]],
            ),
        ];

        for (expected, capabilities) in cases {
            let bytes = wasm_fork_artifact_with_capabilities(
                4,
                4,
                4,
                true,
                &imports,
                &exports,
                &[linked_frame_descriptor(4)],
                &capabilities,
                false,
                false,
            );
            let failures = wasm_artifact_policy_failures(&bytes, ForkInstrumentationPolicy::Auto);
            assert!(
                failures.iter().any(|failure| failure.contains(expected)),
                "capability case {expected:?} was not reported: {failures:?}"
            );
        }
    }

