    #[test]
    fn cmd_resolve_with_binaries_dir_places_single_output_symlink() {
        // Single-output program: symlink lands at
        //   <binaries_dir>/programs/<arch>/<output.name>.<ext>
        // i.e. flat under the per-arch subdir, no per-program nest.
        let root = tempdir("resolve-bdir-single-reg");
        let cache = tempdir("resolve-bdir-single-cache");
        let bin_dir = tempdir("resolve-bdir-single-bin");
        write_program(
            &root,
            "tinybin",
            "0.1.0",
            &[],
            &emit_wasm_build_script("tinybin.wasm", &minimal_executable_wasm()),
            &[("tinybin", "tinybin.wasm")],
        );
        let reg = Registry {
            roots: vec![root.clone()],
        };
        let m = reg.load("tinybin").unwrap();

        // Repo root for cmd_resolve = registry root (script_path
        // resolves repo-relative; for these tests the per-package
        // dir contains its own build script and the package.toml's
        // script_path is unset, so the resolver's
        // "<repo>/<dir-rel>/build-<name>.sh" fallback finds it).
        cmd_resolve_with_test_cache(&m, &reg, &root, TargetArch::Wasm32, &cache, Some(&bin_dir))
            .unwrap();

        let link = bin_dir.join("programs/wasm32/tinybin.wasm");
        assert!(
            link.symlink_metadata().is_ok(),
            "symlink missing: {}",
            link.display()
        );
        let target = std::fs::read_link(&link).unwrap();
        assert!(target.is_absolute(), "symlink must be absolute: {target:?}");
        assert!(target.ends_with("tinybin.wasm"), "got: {target:?}");
        // The symlink resolves to a real file in the cache.
        assert!(
            link.exists(),
            "symlink target unreadable: {}",
            link.display()
        );
    }

    #[test]
    fn forced_source_resolve_into_repo_local_binaries_claims_local_generation() {
        let root = tempdir("resolve-local-generation-reg");
        let cache = tempdir("resolve-local-generation-cache");
        let bin_dir = root.join("local-binaries");
        std::fs::create_dir(&bin_dir).unwrap();
        write_program(
            &root,
            "localproof",
            "0.1.0",
            &[],
            &emit_wasm_build_script("localproof.wasm", &minimal_executable_wasm()),
            &[("localproof", "localproof.wasm")],
        );
        let registry = Registry {
            roots: vec![root.clone()],
        };
        let manifest = registry.load("localproof").unwrap();
        let forced = BTreeSet::from([manifest.name.clone()]);
        let opts = ResolveOpts {
            policy: ResolvePolicy::Default,
            source_cache_root: None,
            cache_root: &cache,
            local_libs: None,
            force_source_build: Some(&forced),
            repo_root: Some(&root),
            binaries_dir: None,
        };
        let canonical =
            ensure_built(&manifest, &registry, TEST_ARCH, TEST_ABI, &opts).unwrap();
        let cache_key_sha =
            manifest_cache_key_sha(&manifest, &registry, TEST_ARCH, TEST_ABI).unwrap();

        publish_resolved_program_artifacts(
            &manifest,
            &canonical,
            &root,
            &bin_dir,
            TEST_ARCH,
            &cache_key_sha,
            true,
        )
        .unwrap();

        let mirror = bin_dir.join("programs/wasm32/localproof.wasm");
        let target = std::fs::read_link(&mirror).unwrap();
        let identity_root = std::fs::canonicalize(
            bin_dir
                .join(LOCAL_GENERATIONS_DIR)
                .join("wasm32/localproof")
                .join(&cache_key_sha),
        )
        .unwrap();
        assert!(target.starts_with(&identity_root), "got: {}", target.display());
        let generation = target.parent().unwrap();
        let session = generation.file_name().unwrap().to_string_lossy();
        let claim = identity_root.join(format!(".{session}.publication-claimed"));
        assert!(claim.is_file(), "missing claim: {}", claim.display());
        assert_eq!(
            std::fs::read(&mirror).unwrap(),
            minimal_executable_wasm(),
        );
        assert!(
            !target.starts_with(&cache),
            "local mirror must not point directly into the fetched cache",
        );

        let mut rebuilt = minimal_executable_wasm();
        rebuilt.extend(wasm_section(0, wasm_name("forced-source-rebuild")));
        std::fs::write(canonical.join("localproof.wasm"), &rebuilt).unwrap();
        publish_resolved_program_artifacts(
            &manifest,
            &canonical,
            &root,
            &bin_dir,
            TEST_ARCH,
            &cache_key_sha,
            true,
        )
        .unwrap();
        let rebuilt_target = std::fs::read_link(&mirror).unwrap();
        assert_ne!(
            rebuilt_target, target,
            "a forced source build must publish its rebuilt generation",
        );
        assert_eq!(std::fs::read(&mirror).unwrap(), rebuilt);
    }

    #[test]
    fn ordinary_source_fallback_into_repo_local_binaries_claims_local_generation() {
        let root = tempdir("resolve-local-generation-ordinary-reg");
        let cache = tempdir("resolve-local-generation-ordinary-cache");
        let bin_dir = root.join("local-binaries");
        std::fs::create_dir(&bin_dir).unwrap();
        write_program(
            &root,
            "localdep",
            "0.1.0",
            &[],
            &emit_wasm_build_script("localdep.wasm", &minimal_executable_wasm()),
            &[("localdep", "localdep.wasm")],
        );
        write_program(
            &root,
            "localfallback",
            "0.1.0",
            &["localdep@0.1.0"],
            &emit_wasm_build_script("localfallback.wasm", &minimal_executable_wasm()),
            &[("localfallback", "localfallback.wasm")],
        );
        let registry = Registry {
            roots: vec![root.clone()],
        };
        let manifest = registry.load("localfallback").unwrap();
        let cache_key_sha =
            manifest_cache_key_sha(&manifest, &registry, TEST_ARCH, TEST_ABI).unwrap();
        let mirror = bin_dir.join("programs/wasm32/localfallback.wasm");
        cmd_resolve_with_test_cache(
            &manifest,
            &registry,
            &root,
            TEST_ARCH,
            &cache,
            Some(&bin_dir),
        )
        .unwrap();

        let opts = ResolveOpts {
            policy: ResolvePolicy::Default,
            source_cache_root: None,
            cache_root: &cache,
            local_libs: None,
            force_source_build: None,
            repo_root: Some(&root),
            binaries_dir: None,
        };
        let cached = ensure_built(
            &manifest,
            &registry,
            TEST_ARCH,
            TEST_ABI,
            &opts,
        )
        .unwrap();
        std::fs::remove_file(&mirror).unwrap();
        symlink_file(&cached.join("localfallback.wasm"), &mirror).unwrap();

        cmd_resolve_with_test_cache(
            &manifest,
            &registry,
            &root,
            TEST_ARCH,
            &cache,
            Some(&bin_dir),
        )
        .unwrap();

        let target = std::fs::read_link(&mirror).unwrap();
        let identity_root = std::fs::canonicalize(
            bin_dir
                .join(LOCAL_GENERATIONS_DIR)
                .join("wasm32/localfallback")
                .join(&cache_key_sha),
        )
        .unwrap();
        assert!(target.starts_with(&identity_root), "got: {}", target.display());
        assert!(
            !target.starts_with(&cache),
            "ordinary source fallback must not point the local mirror directly into the cache",
        );
        let dependency_manifest = registry.load("localdep").unwrap();
        let dependency_cache_key = manifest_cache_key_sha(
            &dependency_manifest,
            &registry,
            TEST_ARCH,
            TEST_ABI,
        )
        .unwrap();
        let dependency_mirror = bin_dir.join("programs/wasm32/localdep.wasm");
        let dependency_target = std::fs::read_link(&dependency_mirror).unwrap();
        let dependency_identity_root = std::fs::canonicalize(
            bin_dir
                .join(LOCAL_GENERATIONS_DIR)
                .join("wasm32/localdep")
                .join(dependency_cache_key),
        )
        .unwrap();
        assert!(
            dependency_target.starts_with(&dependency_identity_root),
            "transitive program mirror escaped its local generation: {}",
            dependency_target.display(),
        );

        cmd_resolve_with_test_cache(
            &manifest,
            &registry,
            &root,
            TEST_ARCH,
            &cache,
            Some(&bin_dir),
        )
        .unwrap();
        assert_eq!(
            std::fs::read_link(&mirror).unwrap(),
            target,
            "a cache hit must preserve the current claimed local generation",
        );
    }

